window.__D("text/likkutei-sichot/c156",{"p":[[1300241147,"רבא<sup data-n=\"89\">89</sup>: „הי׳ להם לסנהדרי גדולה שהניח משה ויהושע כו׳ לקשור חבלים של ברזל במתניהם ולהגבי׳ בגדיהם למעלה מארכובותיהן ויחזרו בכל עיירות ישראל יום אחד ללכיש כו׳ וכן בכל מקומות ישראל וילמדו את ישראל כו׳ כדי שיתגדל ויתקדש שמו של הקב״ה בעולמות כו׳“.\nולהעיר — אז אין תנא דבא״ר ווערט דאס געזאגט בנוגע די „שבעים אלף<sup data-n=\"90\">90</sup> שנהרגו בגבעת בנימין“, אז „לא הרג אותן אלא סנהדרי גדולה כו׳“, ווען זיי וואלטן ארויס בעיירי ישראל וכו׳ וואלט ניט געקומען צו מעשה פילגש בגבעה:\nעאכו״כ ווען עס רעדט זיך וועגן אידן וואס געפינען זיך בשדה, א מקום אן תורה און מצות, אז דאס איז א חיוב ואחריות וואס ליגט אויף ב״ד ישראל.\nאון דאס איז די הוראה פאר יעדן אידן בימינו אלו, ובפרט אין דעם זמן פון חודש אלול, אז מ׳דארף ארויסגיין במקום מושבי בני ישראל<sup data-n=\"91\">91</sup>, אויך אין אן ארט וואס איז ניט קיין סביבה פון תומ״צ („שדה“) און אונטערהעלפן יעדן אידן און אים מעורר זיין אז אין דעם זמן פון אלול געפינט זיך דער מלך מלכי המלכים הקב״ה „בשדה“, און איז מקבל יעדן איינעם אין וואס פאר א מעמד ומצב ער זאל זיין „בסבר פנים יפות ומראה פנים שוחקות לכולם“<sup data-n=\"92\">92</sup>, און דאס גופא העלפט ארויס דעם אידן ארויסצו־גיין פון דעם מעמד ומצב פון „שדה“ אין וועלכן ער געפינט זיך.\nאון דעמאלט איז „בלכתו (המלך) העירה הרי הם הולכים אחריו“, אין דעם זמן פון ימים נוראים<sup data-n=\"93\">93</sup>, ווען מ׳איז ממלא בקשת הקב״ה „שתמליכוני עליכם“<sup data-n=\"94\">94</sup>, ביז צו דעם „כפר לעמך ישראל“<sup data-n=\"95\">95</sup> ביום הכיפורים, ווען עס ווערט אויפגעטאן די כפרה וסליחה ומחילה פאר יעדן אידן און פארן גאנצן כלל ישראל, און — סלחתי כדבריך,\nאון יעדער איינער און איינע ווערט נכתב ונחתם לאלתר בספרן של צדיקים<sup data-n=\"96\">96</sup> גמורים.\n(משיחות ש״פ: שופטים תצא ותבוא — תשמ״א)",[["89","89","פי״א."],["90","90","כ״ה בתדבא״ר שם, וביל״ש שופטים רמז סח: ע״ב אלף. ובמפרשים (זיקוקין דנורא. ישועות יעקב) שבשניהם הוא ס״ה כי לא מצינו בקרא שנהרגו כ״א ס״ה אלף ומאה ושלשים. ולחומר הקושיא — י״ל דקים להו דנשים וטף דבנימין שנהרגו — השלימו לשבעים אלף (שבתדבא״ר) והרוגי יבש גלעד — לע״ב אלף (שביל״ש), ועפ״ז גם לא הוי פלוגתא במציאות. ועפ״ז גם מבואר צע״ג במרז״ל הנ״ל (תדא״ר וילי״ש) שמדגיש שזה שיש בידו למחות ולא מיחה הרי „הכל נעשה על ידו“ ומפרש בהדוגמא „שנהרגו בגבעת בנימין“ ותו לו! ועפהנ״ל מובן בפשטות כי בזה נכללו גם נשים וטף דבנימין והרוגי דיבש גלעד — אלא שלתדא״ר הרוגי דיבש גלעד — אין שייך לעניננו בכלל, כי זה הי׳ מפני „השבועה הגדולה“ (שופטים כא, ה). וענין „פלגש בגבעה“ הי׳ רק סיבה דסיבה וכו׳."],["91","91","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091325\" data-slug=\"likkutei-sichot\" data-id=\"1300091325\">לקו״ש ח״ט ע׳ 298</a> ואילך. וש״נ."],["92","92","לקו״ת שם לב, ריש ע״ב."],["93","93","ראה לקו״ת שם לה, ג."],["94","94","ר״ה טז, סע״א."],["95","95","פרשתנו כא, ח."],["96","96","ר״ה שם, סע״ב."]]],[1300241148,"<h3>תצא</h3>\nא. בקשר מיטן פסוק בפרשתנו1 „וכי יהי' באיש חטא משפט מות והומת ותלית אותו על עץ\", איז ידוע2 אז אין דעם הספד וואס דער אריז\"ל האט מספיד געווען דעם רמ\"ק האט ער גע־טייטשט דעם פסוק:\n„וכי3 יהי' באיש חטא משפט מות, פי' שיחסר (חטא מלשון חסרון) טעם משפט מות כי לא פעל רע ולמה ימות, ותלית אותו על עץ מחמת עץ הדעת שגזרו4 מיתה, בשביל כך מת\".\nפון שטחיות הלשון איז משמע5, אז דער תוכן פון דער דרשה איז ווי דער מאמר חז\"ל6 „ד' מתו בעטיו של נחש\" — אז כשם ווי די פיר האבן ניט געהאט קיין חטא און זייער מיתה איז געווען נאר בסיבת ה„נחש\", צוליבן חטא עץ הדעת (בעצתו7 של נחש) איז „נגזרה8 גזירת מיתה על כל תולדותיו של אדה\"ר\" — עד\"ז איז געווען ביים רמ\"ק, אז זיין „והומת\" איז געווען נאר צוליבן „עץ (הדעת)\".\nוי\"ל, אז ס'איז ניט נאר וואס דער אריז\"ל דרשנ'ט דעם פסוק אויף דעם ענין „מתו בעטיו של נחש\", נאר דער־מיט זאגט ער און מחדש א נייעם גדר.\nב. ובהקדם דעם חילוק צווישן די צוויי ענינים הנ\"ל: די גמרא זאגט „מתו בעטיו של נחש\", דער אריז\"ל (טייטשט און לערנט דעם פסוק) — „ותלית אותו על עץ\"; וואס דאס איז א חילוק (ניט נאר אין לשון, נאר) אין תוכן:\n„עטיו (עצתו) של נחש\" — וואס ער האט גע'עצה'ט חוה צו עסן פונעם עץ הדעת — רעדט זיך וועגן רע, עצה למעשה חטא9; „ותלית אותו על עץ\" (וואס דער אריז\"ל שטעלט זיך אויף עם) רעדט וועגן דער זאך דורך וועלכער אדם איז באגאנגען דעם חטא, אבער דער „עץ\" גופא איז ניט אן ענין של חסרון10, ואדרבה, בפשוטו של מקרא — כפרש\"י11 — איז עס געווען אן עץ תאנה, פון די מינים שנשתבחה בהם",[["1","1","כא, כב."],["2","2","יערות דבש ח\"ב (דרשות בק\"ק אה\"ו דרשה ב' בסופה (בדפוס ווארשא — קכו, ג)). חידא\"א — נחל קדומים פרשתנו עה\"פ ובדברים אחדים דרוש כ (קז, סע\"ד). ועיין ג\"כ של\"ה דרוש להספד רט, ב בשם התיקונים (ראה תקו\"ז בהשמטות ת\"ה (קמא, ב), הובא ביערות דבש שם). ולהעיר ג\"כ משל\"ה פרשתנו שפד, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071179\" data-slug=\"likkutei-sichot\" data-id=\"1300071179\">לקו\"ש ח\"ז ע' 167</a> ואילך. — ולהעיר אשר בש\"ך עה\"ת עה\"פ פי' להיפך, שאין לתלות מיתת הצדיק „על העץ\". ע\"ש."],["3","3","ל' היערות דבש. ובנחל קדומים — בשינוי לשון. וראה לקמן הערה 5."],["4","4","אולי צ\"ל: שנגזר."],["5","5","וכן משמע בדברים אחדים שם שמוסיף (על ל' היע\"ד) „כלומר בעטיו של נחש\". וכן בנחל קדומים שם: ותלית אותו על עץ ר\"ל בעטיו של נחש. — אבל ע\"פ המבואר לקמן בפנים עכצ\"ל שכוונתו רק בכללות ולא שזהו אותו הענין ממש. ולהעיר שגם בשל\"ה שם לא הובא מחז\"ל „בעטיו של נחש\"."],["6","6","שבת נה, ב. ב\"ב יז, א."],["7","7","רש\"י שבת וב\"ב שם. רבינו גרשום ב\"ב שם."],["8","8","ל' רש\"י ב\"ב שם."],["9","9","להעיר מר\"ג לב\"ב שם."],["10","10","ובפרט ע\"פ המבואר (ראה קונטרס עה\"ח פ\"י — מהרח\"ו) „שהי' צריך לאכול מעה\"ד אחרי (או עם) עה\"ח, „ואז . . אדרבא היא מבררת אותם\" (החיצונים)."],["11","11","בראשית ג, ז. — ועפ\"ז נאסר אדה\"ר באכילת תאנה — וע\"פ פשוטו ש\"מ ה\"ז איסור עולם!"]]],[1300241149,"ארץ ישראל12. אויך זיין נאמען איז „עץ הדעת\", אז עס טוט אויף ענין הדעת13. ואפילו דער חטא צו וועלכען ער קען בריינגען — אכילה פון עץ הדעת, איז (ע\"פ דרז\"ל וכו' איז) עס געווען נאר (במשך פון די דריי שעה) ביז שבת14.\nד. ה. דער אריז\"ל רעדט וועגן סיבה דסיבה כו' נאך א פריערדיקע און ווי־טערדיקע סיבה — ניט וועגן דעם חטא עה\"ד וואס האט געבראכט גזירת מיתה בפועל, נאר וועגן דעם („עץ\") וואס האט געגעבן די אפשריות אויף ענין המיתה (אויב מען וועט פון אים עסן (ווען ער איז טוב ורע<sup data-n=\"15\">15</sup> איז „מות תמות\"<sup data-n=\"16\">16</sup>.\nבסגנון אחר (וע\"פ לשון המדרש<sup data-n=\"17\">17</sup>: בשעת הבריאה האט דער אויבערשטער געטראכט אז עס זאל זיין מיתה בעולם18 (וואס דערפאר איז „מיום הראשון ברא מלאך המות\"<sup data-n=\"19\">19</sup>, נאר מצד דעם „נורא עלילה על בני אדם\"20 איז אויסגע־שטעלט געווארן אזוי, אז די גזירת מיתה בפועל זאל קומען דורכן אדם. און דער־פאר האט דער אויבערשטער גע־שטעלט אדם'ען פאר דעם גרויסן נסיון פון עץ הדעת — דורך איינפלאנצן אין גן עדן „כל עץ נחמד למראה וטוב למאכל\"21 אויך דעם עץ הדעת וכו' — וואס דורך דעם אלעם איז ארויס די גזירה בפועל.\nג. און דאס איז דער חילוק צווישן די צוויי ענינים — „מתו בעטיו של נחש\" און „ותלית אותו על עץ\":\nדער ענין פון „מתו בעטיו של נחש\" וואס ווערט געזאגט אין גמרא — נגלה דתורה — רעדט וועגן דעם ענין המיתה ווי דאס איז געווארן בפועל ובגלוי (ב„נגלה\"):\nמשא\"כ דער ענין פון „ותלית אותו על עץ\" — וועלכן דער אריז\"ל האט מגלה געווען, ובשייכות צום רמ\"ק, וואס ענינם איז22 גילוי תורת הסוד, פנימיות התורה — רעדט ווי דאס איז בפנימיות, וואס מצד פנימיות הענין איז עס פאר־בונדן (ניט מיט „עטיו של נחש\", נאר) מיטן „עץ\" — דער נסיון פון „עץ הדעת\", וואס דער אויבערשטער האט צוגעשטעלט אדם'ען מצד רצונו ית' וכוונתו בהבריאה.\nד. בעומק יותר, זיינען די צוויי ענינים („עטיו של נחש\" און „ותלית",[["12","12","עקב ח, ח. ולהעיר אשר כן הוא גם למ\"ד חטה הייתה (ברכות מ, סע\"א), גפן הי' (שם)."],["13","13","ת\"א בראשית ב, ט. ברכות מ, סע\"א. ועוד. — וראה רמב\"ן בראשית (שם — ולכאורה הוא דלא כהרמב\"ם מו\"נ ח\"א פ\"ב). ואכ\"מ."],["14","14","ש\"ך עה\"ת קדושים יט, כג ד\"ה עוד ונטעתם (מב, ב). וראה לקו\"ת ר\"פ קדושים. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080143\" data-slug=\"or-hatorah-hb\" data-id=\"8160080143\">אוה\"ת</a> (ויקרא כרך א') קדושים ס\"ע קמג. רח\"צ (הובא לעיל הערה 10) ועוד. — ובאוה\"ת בראשית מו סע\"א: דלכאורה תמוה שהרי נאמר סתם ומעה\"ד טו\"ר לא תאכל ממנו אלא דהפי' כו' כי בשבת כו' עה\"ד . . טוב לבד ועז\"ז לא באה האזהרה כלל. עיי\"ש."],["15","15","ראה הערה שלפנ\"ז."],["16","16","בראשית שם, יז."],["17","17","תנחומא וישב ד."],["18","18","כמו שמוכיח בתנחומא שם ממש\"נ (חוקת יט, יד) „זאת התורה אדם כי ימות באהל\", אף ש„עד שלא בראת עולמך קודם שני אלפים שנה היתה תורה אצלך\", ו„אלולי שהתקנת מות לבריות היית כותב בה כך\". ועד\"ז בזח\"ג קנט, א."],["19","19","תנחומא שם."],["20","20","תהלים סו, ה. וראה בארוכה תו\"ח תולדות ד\"ה ויתן לך פ\"י ואילך. ועוד."],["21","21","בראשית שם, ט. וראה גם שם ג, ו."],["22","22","להעיר מהגהות כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע לסידור (בהוצאת קה\"ת — שיט, סע\"ד): ואין הפרש בינו (הרמ\"ק) לקבלת האריז\"ל אלא כו' בכלל מאתיים מנה כו'. וראה שיחת ש\"פ שמיני תשמ\"א."]]],[1300241150,"אותו על עץ\") פארבונדן מיט צוויי סוגי צדיקים:\n„מתו בעטיו של נחש\" זיינען די וואס זייער מיתה נעמט זיך פון דעם חטא; עס איז אבער פאראן א סוג פון צדיקים23, וואס זיי קען „עטיו של נחש\" ניט אנ־רירן, און דער ענין המיתה ביי זיי איז שייך, „ותלית אותו\", נאר מצד — „על עץ\".\nדי הסברה אין דעם:\nדער אלטער רבי איז מבאר אין תורה אור24, אז „מתו בעטיו של נחש\" איז ווייל די פיר צדיקים, אע\"פ אז זיי זיינען געווען צדיקים גמורים, איז אין זיי נאך געבליבן „איזה שמץ מזוהמת הנחש25 שלא יכלו להסירו מכל וכל\", און ווי ער איז דאס מבאר אין עבודת האדם, אז זוהמת הנחש איז דער ענין פון „גסות הרוח שנעשה בטבע האדם . . שרואה את עצמו ומכיר חסרונו או יודע שזה טוב לו\" — מען פילט „זיך\".\nד. ה. „עטיו של נחש\" מיינט, אז דער חטא עה\"ד האט אויפגעטאן א חסרון אין דעם צדיק, וואס דאס איז גורם מיתה. אבער דעם חסרון האט גורם געווען ניט דער צדיק עצמו ח\"ו, נאר דער נחש וואס האט געבראכט „זוהמא\" בעולם25.\nאון דאס איז דער יתרון פון „ותלית אותו על עץ\" לגבי „מתו בעטיו של נחש\":\nדער פגם פון א חטא קען אנרירן נאר די חיצוניות פון א אידן, אבער די פני־מיות פון א אידן בלייבט אלעמאל גאנץ, „גם בשעת החטא היתה באמנה אתו\"26, ובפרט מצד פנימיות הנשמה וואס איז מלכתחילה העכער פון דעם גאנצן ענין החטא27.\nדערפון איז אויך פארשטאנדיק בנוגע דער „זוהמת הנחש\" שע\"י חטא עה\"ד, אז די „זוהמא\" פון נחש האט נאר אנגע־רירט די חיצוניות פון אידן, אבער ניט ח\"ו די פנימיות פון א אידן.\nאון דערפאר, בשעת די פנימיות הנשמה פון א אידן איז ביי אים מאיר בגילוי, ביז דאס נעמט דורך זיין חיצוניות, איז ביי אים ניט שייך דער ענין פון „מתו בעטיו של נחש\".\nאון דאס זאגט דער אריז\"ל: „וכי יהי' באיש חטא משפט מות, פי' שיחסר טעם משפט מות כי לא פעל רע\" — שיש לומר אז דערמיט מיינט ער כולל זיין אויך דעם „טעם משפט מות\" פון „עטיו — זוהמת הנחש\" —\nאיז „ותלית אותו על עץ\", אז דאס וואס ביי אים איז פאראן דער ענין המיתה, איז עס בלויז מצד דעם וואס „נורא עלילה על בני אדם\", וואס דער אויבערשטער האט געמאכט (ע\"י עץ הדעת) דעם ענין המיתה בעולם28.",[["23","23","להעיר מחדא\"ג מהר\"ל ב\"ב שם, שהד' שמתו בעטיו של נחש הם למטה מן המנויים בגמ' לפנ\"ז שלא שלטה בהם כו'."],["24","24","ס\"פ משפטים. תו\"ח שם (ד\"ה לא תהי' פכ\"א). ועד\"ז הוא בזהר הרקיע (סט, א ואילך) לסבא דמשפטים (צו, א) — הובא גם באהבת איתן לע\"י שבת שם. וראה גם יערות דבש שם דרשה ט בסופה (קמט, סע\"ד)."],["25","25","ראה שבת קמו, רע\"א. וש\"נ. זח\"א נב, ב. קכו, ב. זח\"ב קצג, סע\"ב."],["26","26","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ\"ד</a>."],["27","27","ראה זח\"ג טז, א. שם יג, ב."],["28","28","עפ\"ז י\"ל שיש חילוק גם בתוכן ענין המיתה: כאשר סיבתו „עטיו של נחש\" מובן שהור\"ע לגריעותא; משא\"כ כאשר המיתה היא רק מצד רצונו של הקב\"ה שתהי' מיתה בעולם — מובן, שאצל הצדיק נרגש שכל ענין המיתה הוא רק (כמו שהוא מצד הקב\"ה, היינו) העילוי הבא עי\"ז, עלי' למעלה מעלה ממדריגתו עצמו, ע\"ד עליית צדיקים שבבחי' שור הבר ע\"י צדיקים שבבחי' לויתן (לקו\"ת ר\"פ שמיני). דרושי דלעתא\"ל עושה קניגי כו' (ראה תו\"ח"]]],[1300241151,"ועפ\"ז וועט זיין פארשטאנדיק די שייכות פון דעם ענין צום רמ\"ק ואריז\"ל, וואס ענינם איז, כנ\"ל, גילוי פנימיות התורה — ווייל דער גילוי פון „סתים דאורייתא\" איז פארבונדן מיטן גילוי פון „סתים דנשמתא\"29 וואס איז העכער פון „עטיו של נחש\". וכידוע30, אז פנימיות התורה איז „עץ חיים\" (אילנא דחיי) וואס איז העכער פון „אילנא דטוב ורע\" (עץ הדעת).\nה. וויבאלד אז זינט דעם זמן האריז\"ל איז „מצוה לגלות זאת החכ־מה\"31, איז אע\"פ, אז „מי הוא זה ואיזהו אשר ערב לבו\"32 צו זאגן אז ער האט א שייכות צו די מדריגות הנ\"ל פון רמ\"ק און אריז\"ל — פונדעסטוועגן, היות מ'האט אונז דערציילט אויך וועגן דעם ענין איז מובן, אז „אפס קצהו ושמץ מנהו\"32 איז שייך צו יעדער אידן. וע\"ד ווי מ'זאגט בנוגע צו משה רבינו33 אז אע\"פ אז „מי הוא זה ואיזהו אשר ערב לבו לגשת להשיג אפי' חלק אחד מני אלף ממדרגת אהבת רעיא מהימנא מ\"מ הרי אפס קצהו ושמץ מנהו כו' מאיר לכללות ישראל בכל דור ודור\".\nובנדו\"ד, איז אדרבה: דער ענין פון „מתו בעטיו של נחש\" — אז מ'האט ניט קיין אנדער חטא וחסרון, נאר דאס וואס מ'האט ניט געקענט אראפנעמען „זוהמת הנחש . . מכל וכל\" — איז שייך אין דער דרגא אין נפש וואו די „זוהמא\" קען אנרירן. ד.ה. אין חיצוניות האדם וכחות הגלויים שלו, וואס אזא שלימות ועילוי (אויך) אין די דרגות חיצוניות איז אנגי־מאסטן נאר פאר יחידי סגולה און דאס איז ניט שייך לכל אחד ואחד.\nמשא\"כ דער ענין פון „חטא משפט מות . . שיחסר טעם משפט מות\" שמצד סתים דנשמתא (וואו דער „עטיו של נחש\" קען ניט אנרירן) ופשיטא אין עצם נשמתו — איז דאס אזוי ביי יעדן אידן; ווארום די פנימיות פון יעדער אידן, יהי' מי שיהי' און וואס פאר א מצב ער זאל נאר זיין, איז העכער פון יעדער זוהמא של חטא. ביז אז עס קען ארויס בגלוי ממש און ווירקען בפועל ממש און להלכה בפועל.\nווי מען זעט עס, אז א איד וואס זאגט בגלוי ובכל התוקף אז ער וועט ניט מקיים זיין פס\"ד ב\"ד וואס הייסט עם בריינגען א קרבן — איז דער ב\"ד עם כופה ביז אז אומר רוצה אני און דאמאלס זאגט תורת אמת אז דאס איז זיין אמת'ער לרצונו34.\nאון יעדערער בזמננו וואס מצוה לגלות זאת החכמה קען און איז מצווה דאס ארויסברענגען בגילוי, דורך דעם וואס מ'איז מגלה ביי זיך „סתים דנשמתא\", וואס דאס ווערט דורך דעם לימוד פון „סתים דאורייתא\" אין אן אופן אז דער „סתים\" זאל ווערן „גליא\" — אז",[["","","שם פי\"ז ואילך. — ענין הקניגי בכלל — נתבאר בשני המאורות (לבוב, תרמ\"ב) י, א (מאמרי אדה\"ז על מארז\"ל ע' קמא). ד\"ה ויתן לך וביאורו — מאמרי אדה\"ז — תקס\"ב ובתו\"ח תולדות שם. ד\"ה ומשה נגש — מאמרי אדה\"ז — פרשיות ח\"א ובאוה\"ת יתרו פ\"ה). וראה ד\"ה זאת התורה תרע\"ט."],["29","29","ראה זח\"ג עג, א."],["30","30","רע\"מ נשא (קכד, ב) הובא ונת' באגה\"ק סכ\"ו. וראה תו\"ח שם (פכ\"ב־ג) איך שביטול תערובת הרע דחטא עה\"ד (עטיו של נחש) הוא ע\"י עץ החיים דתורה. וראה בארוכה קונטרס עה\"ח פ\"ג ואילך. ועוד."],["31","31","אגה\"ק שם (קמב, ב)."],["32","32","לשון התניא דלקמן בפנים."],["33","33","<a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד (סג, א</a>)."],["34","34","רמב\"ם הל' גירושין ספ\"ב."]]],[1300241152,"יתפרנסון מיני'35 מען פארשטייט עס אין חב\"ד שבנפש, ביז עס נעמט דורך דעם מענטשן אינגאנצן.\nאון בשעת די „מעינות\" הנשמה נעמען דורך אויך דעם „חוצה\" שבאדם, ווערט ער אין א מצב אז ער איז ניט שייך צו א חטא.\nו. די הוראה בפועל מכל הנ\"ל:\nעס דארף זיין — „יפוצו מעינותיך חוצה\": מען דארף מפיץ זיין די מעינות פון פנימיות התורה, אז זיי זאלן ארויס־קומען בגילוי ביז אין חוצה, צו יעדער איד. און ביז צום חוצה פון א אידן התחתון ביותר (ברוחניות). ווארום יעדער איד, מצד פנימיות נשמתו, איז פארבונדן מיט פנימיות (מעינות) התורה.\nאון דורך דעם גופא וואס מען לערנט מיט אים פנימיות התורה — אע\"פ אז כדי לערנען מיט אים דארף מען דאס איבערזעצן אויף אן אנדער שפראך און געבן אים צו פארשטיין אין א סגנון וואס ער קען פארשטיין במצבו בהווה — איז דאס מעורר זיין פנימיות הנשמה און הויבט אים אויף ממעמדו ומצבו.\nאון דורך דער הנהגה איז מען מבטל דעם „חטאינו\" (כולל — חטא עץ הדעת) — וואס דאס איז די איינציקע סיבה אויף דעם גלות, מפני „חטאינו גלינו\", און עס ווערט בדרך ממילא בטל דער מסובב („גלינו\"), און עס קומט די גאולה האמיתית והשלימה דורך משיח צדקנו, ובמהרה בימינו ממש.\n(משיחת ש\"פ מטות תשמ\"א)",[["35","35","תקו\"ז (ת\"י בסופו). וכפי' המק\"מ (הקדמה לזהר): יתפרנסון . . כשיפורש להם אמיתות מאמריו כו'. ובכסא מלך (לתקו\"ז שם): בדרא בתראה דוקא קרוב לימות המשיח כו' (אף אשר) זה כמה מאות שנים שנתגלה כו' (כי הלימוד צ\"ל דוקא באופן של יתפרנסון כו' יפורשו מאמריו העמוקים בהקדמות שגילה האר\"י זלה\"ה כו' שיבינו כו' כי הלומד גירסא בעלמא הגם שיש לו שכר טוב כו' עכ\"ז הסגולה דבגיני' וקראתם דרור היא כשיתפרנסון וילמדו פירושי המאמרים כו'. — ראה גם כן הקדמת הרח\"ו לשער ההקדמות."]]],[1300241153,"<h3>תצא ב</h3>\nא. אויפן פסוק¹ „כי תבנה בית חדש ועשית מעקה לגגך“ שטייט אין ספרי²: „בית — לרבות היכל“,\nאז די מעקה אויפן גג פון היכל המקדש³ איז געווען (ניט נאר „לנוי“⁴ וכיו״ב, נאר) א חיוב, מצות מעקה.\nאיז ידוע די שאלה⁵: דער דין איז, אז בתי כנסיות ובתי מדרשות זיינען פטור פון א מעקה, ווי די גמרא⁶ דרשנט „גגך . . למעוטי בתי כנסיות ובתי מדרשות“ — איז פארוואס איז דער היכל המקדש מחוייב במעקה?\nב. דער ראגאטשאוור⁷ ענטפערט אויף דעם, אז דער חיוב מעקה איז חל (ווי עס שטייט אין ספרי⁸) „משעת חידושו“⁹ — גלייך ווען דער בית ווערט געבויט (נאך איידער מ׳הויבט אן אים נוצן¹⁰); און וויבאלד אז ביים מקדש איז\nדער דין¹¹ „בונין בחול ואח״כ מקדישין“, קומט אויס, אז „בשעת חידושו“ (ווען דער מקדש ווערט געבויט), האט ער נאך ניט קיין קדושה ובמילא איז ער דאן חייב במעקה.\nדער תירוץ איז אבער צע״ג¹²:\nא) דאס וואס בתי כנסיות ובתי מדרשות זיינען פטור ממעקה איז (ניט ווייל זיי זיינען „קודש“¹³, נאר) ווייל זיי זיינען ניט „גגך“ — זיי האבן ניט קיין בעלים¹⁴; וא״כ האט אויך היכל המקדש געדארפט זיין פטור ממעקה, ווארום כאטש ער ווערט נבנה בחול, ווערט ער אבער ניט דערמיט „גגך“.",[["1","1","פרשתנו כב, ח."],["2","2","אף שיש מוחקים זה — הרי נוסף ע״ז שכן הוא בדפוס וויניציא וכו׳ — כן הוא גם בכת״י הספרי (ראה הוצאות ר״מ א״ש, האראוויץ — הובאו באנצ׳ תלמודית מע׳ היכל ע׳ מח)."],["3","3","מדות פ״ד מ״ו. רמב״ם הל׳ בית הבחירה פ״ד ה״ג."],["4","4","כמו שפי׳ בספרי דבי רב לספרי שם."],["5","5","ספרי דבי רב שם. מנ״ח מצוה תקמו. ועוד."],["6","6","חולין קלו, א."],["7","7","ראה הנעתק בצפע״נ עה״ת פרשתנו שם. צפע״נ להל׳ בית הבחירה שם (ירושלים תשל״ט) ובהנסמן שם."],["8","8","פרשתנו שם."],["9","9","כ״ה בילק״ש פרשתנו שם. ועוד. ובספרי לפנינו: חדשתו."],["10","10","כן מפרש גם ברבינו הלל וספרי דבי רב לספרי שם. אבל בתולדות אדם שם: כשהוא חדש לו ויכנוס לדור בו."],["11","11","מעילה יד, א."],["12","12","נוסף על העיקר, שדין הנ״ל בספרי דחייב „משעת חידושו“ הוא דעת יחיד, ולא הובא ברמב״ם כו׳ (ראה ספרי דבי רב שם. וראה מגדל עוז להל׳ רוצח ושמירת נפש פי״א ה״ג)."],["13","13","גבי מזוזה כתב הרמב״ם (הל׳ מזוזה פ״ו ה״ו) ש„פטורין לפי שהן קדש“, אבל [נוסף לזה שגם בזה פירש בחת״ס (שו״ת יו״ד סרפ״א) שהטעם הוא לפי שאינם דירת הדיוט, ודוקא דירת הדיוט חייבת במזוזה ע״ש. ועיין ל׳ החינוך מצוה תכג — הרי] גבי מעקה לא הובא טעם זה (אבל ראה הערה הבאה). וברמב״ם (הל׳ רוצח כו׳ שם ה״ב) מפורש שנתמעטו מגגך „לפי שאינן עשויים לדירה“, כדלקמן בפנים."],["14","14","כפרש״י חולין שם — נעתק לקמן בפנים (ר״ס ג). ואולי י״ל (בדעת הצפע״נ), ע״פ מ״ש במ״א (צפע״נ שו״ת וארשא סי׳ קיב. וראה שו״ת דווינסק ח״ב סי״ב) בביאור פרש״י זה, ד„דבר שבקדושה אין בו קנין עצם“ — שזהו מחמת הקדושה שבו. וא״כ במקדש קודם שמקדישין אותו אין שייך טעם זה. ולהעיר ממנ״ח שם: שאינן בית דירה מכש״כ היכל וגם הוא לגבוה ולא קרי גגך כי הוא של גבוה כמו שדרשינן בכל מקום שלך ולא של גבוה (אבל כותב זה רק בנוגע להיכל, ולא לביהכנ״ס כו׳ שאינם „של גבוה“ כ״א דבני העיר. וראה לקמן סעיף ג)."]]],[1300241154,"מען קען ניט ענטפערן אז תירוצו איז לויטן טעם הרמב״ם¹⁵ — אז דאס וואס בתי כנסיות ובתי מדרשות זיינען פטור ממעקה איז (ניט ווייל זיי באלאנגען ניט צו יחידים, נאר) „לפי שאינן עשויים לדירה“: משא״כ דער היכל וואס בשעת בנינו איז ער נאך „חול“, קען ער דעמאלט גענוצט ווערן לדירה, און דערפאר איז ער מחויב במעקה,\nווייל¹⁶ אע״פ אז „בונין בחול ואח״כ מקדישין“, וויבאלד אבער אז עס ווערט געבויט לשם מקדש, איז מסתבר, אז מען האט זיך ניט משתמש געווען (אדער — מען טאר ניט משתמש זיין זיך) מיטן בית לצרכי הדיוט¹⁷.\nב) א בית המחויב במעקה — אז מ׳האט אים דערנאך געמאכט פאר א ביהכנ״ס (וכיו״ב — בית הפטור ממעקה), ווערט במילא בטל חיוב המצוה דמעקה¹⁸.\nג. ויש לומר הביאור בזה:\nרש״י¹⁹ איז מסביר, אז דאס וואס בתי כנסיות ובתי מדרשות זיינען ניט בכלל „גגך“ איז ווייל „אין חלק לאחד מהן בו שאף לבני עבר הים הוא“. דערמיט בא־וארנט רש״י פארוואס בתי כנסיות כו׳ זיינען אנדערש פון א בית של שותפין:\nדער דין איז, אז בית של שותפין איז\nחייב במעקה, ווי די גמרא⁶ זאגט, אז כאטש פון וואָרט „גגך“ איז משמע „דידך אין דשותפות לא“, פונדעסט־וועגן, וויבאלד דער פסוק טייטשט אויס דעם טעם פון מעקה — „כי יפול הנופל ממנו“, און מצד דעם חשש איז ניט קיין נפק״מ צי ס׳איז א בית של יחיד אדער של שותפין, דעריבער איז א בית של שותפין מחויב במעקה²⁰ —\nווערט דאך לפ״ז קשה: מיט וואס זיינען אנדערש בתי כנסיות ובתי מדרשות וואס ווערן יע נתמעט פון וואָרט „גגך“? אפילו אז ס׳איז ניט „גגך“, מוז מען דאך אבער באווארענען דעם חשש פון „כי יפול הנופל ממנו“.\nאיז רש״י מסביר, אז ביי בתי כנסיות ובתי מדרשות איז ניטא וועמען צו מחייב זיין: דער חיוב מעקה איז אויף די בעלים פון דעם בית (און ביי בית של שותפין — איז דער חיוב מעקה אויף יעדערן און אלע שותפים), אבער די בני העיר (וועלכע האבן געבויט דעם ביהכנ״ס אדער ביהמ״ד) אין חלק לאחד מהן אין ביהכנ״ס וביהמ״ד, ווייל „אף לבני עבר הים הוא“²¹, איז במילא ניט שייך ארויפצולייגן אויף זיי דעם חיוב צו מאכן א מעקה.\nס׳איז קיין סתירה ניט פון דעם וואס מען געפינט, אז לגבי אנדערע דינים²² ווערן די בני העיר יא פאררעכנט ווי די",[["15","15","הל׳ רוצח כו׳ שם. וכ״ה בשו״ע חו״מ סתכ״ז ס״ג."],["16","16","נוסף לזה שאע״פ לפרש כן בצפע״נ, שלא הביא שם דברי הרמב״ם."],["17","17","ולהעיר מהאיסור לבנות בית בתבנית היכל (ע״ז מג, א. וש״נ. רמב״ם הל׳ ביהב״ח פ״ז ה״י)."],["18","18","דבפטור ביהכנ״ס וכו׳ אין תנאי בזה שצ״ל נבנה מתחלתו לשם זה, ולא כשקנו בית (דירה) ועשאוהו ביהכנ״ס כו׳ — ומעשה רב."],["19","19","חולין שם (בטעם הראשון. בטעם השני — ראה לקמן סעיף ה)."],["20","20","ובל׳ הרמב״ם הל׳ רוצח כו׳ שם: לא תלה אלא בנופל."],["21","21","ובמילא אין חלק מבורר, או אינו שוה פרוטה ועוד. וראה לקמן הערה 31. ועצ״ע."],["22","22","כמו גבי מזוזה ונגעים (אם יש בו בית דירה) — ראה יומא יא, ב ואילך (ועיין פרש״י שם יב, רע״א החילוק בין דכפרים לדכרכים. וראה אנציקלופדי׳ תלמודית ע׳ בית הכנסת ע׳ רא. וש״נ). וראה גם משנה נדרים (מח, רע״א) „ואסורים בדבר של אותה העיר . . (ו)בית הכנסת“. ועוד."]]],[1300241155,"בעלים פון דעם ביהכנ״ס כו׳ — ווייל לגבי חיוב מעקה איז נוגע (ניט נאר דער קנין הגוף פון ביהכנ״ס כו׳, וואס געהערט בלויז צו די בני העיר, נאר אויך) אז דאס איז זייער א מקום לדור²³,\nמשא״כ ביהכנ״ס וואס כל ישראל האבן רעכט צו אריינגיין און משתמש זיין זיך מיט יעדן בית הכנסת שבכל עיירות שבעולם²⁴; ובלשון פון ראגאטשאוור²⁵: „גבי מעקה . . תלי׳ בדירה ודירת בהכ״נ שייך לכל“²⁶.\nד. עפ״ז ווערט אויך רעכט פאר־וואס דער היכל המקדש איז חייב במעקה:\nאין דעם מקדש האבן אלע אידן געהאט א חלק, (כעין) שותפות: סיי אין דעם מקום מקדש, וואס דוד המלך האט געקויפט פון ארונה היבוסי מיטן געלט וואס ער האט גענומען פון אלע שבטים²⁷: און עד״ז דער מקדש גופא ווערט דאך געבויט פון נדבות הצבור (און פונקט ווי אלע אידן האבן זיך משתתף געווען אין נדבת המשכן, איז מסתבר, אז אלע אידן האבן זיך משתתף געווען אויך אין דער קופה ולשכה פון וועלכער מ׳האט געבויט (אדער בדק בית ה)מקדש):\nאון אע״פ אז בשעת דער יחיד גיט זיין נדבה אין דער קופה, איז עס באופן פון „מסרם לצבור יפה יפה“²⁸ (ניט ווי ממון וואס געהערט צו כמה יחידים בתור שותפות) — פונדעסטוועגן ווערט דורך דעם ניט נתבטל (לגמרי) דער חלק היחיד²⁹ (כידוע די ראי׳ אויף דעם פון בקשת משה (בקשר צו קורח ועדתו): „חלקם (בתמידי צבור) לא יקובל“³⁰): און דערפאר איז דער מקדש (עכ״פ) מעין שותפות דכל ישראל³¹.\nאון וויבאלד אז יעדער איד האט א חלק אין ביהמ״ק — כנ״ל (ובמכש״כ — פון תמיד), דעריבער זיינען די אידן³²",[["23","23","שבזה תלוי העניין ד„יפול הנופל ממנו“. וראה לקמן הערה 39."],["24","24","ראה גם נמוק״י נדרים שם. וראה המובא באנציקלופדי׳ תלמודית שם."],["25","25","צפע״נ מהד״ת פז, א. ועייג״כ שו״ת צפע״נ דווינסק ח״ב סי״ג."],["26","26","ומסיים „ואין נ״מ בין של כפרים לשל כרכים“ (ראה הנסמן לעיל הערה 22). ולהעיר מהשקו״ט אם שוכר חייב במעקה מה״ת (שד״ח כללים מע׳ המ״ם כלל קצה. וש״נ). ואכ״מ."],["27","27","ספרי (ורש״י) ראה יב, יד. זבחים קטז, ב. פרש״י יומא שם ד״ה אלא."],["28","28","ר״ה ז, ריש ע״ב. וש״נ."],["29","29","האריך בזה בצפע״נ בכ״מ (ראה מפענח צפונות פ״ד ס״ב וס״ד, וש״נ. אבל ראה השקו״ט בזה (שו״ת שם סי״ב־יג. ועוד) גם גבי ביהכנ״ס, דאף ששייך לכל (בני) העיר, נשאר בו חלק היחיד). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181121\" data-slug=\"likkutei-sichot\" data-id=\"1300181121\">לקו״ש חי״ח ע׳ 112</a> ואילך."],["30","30","פרש״י קרח טז, טו. מבמדב״ר פ״ח, י."],["31","31","כן מוכח ג״כ ממ״ש בפיה״מ נדרים שם גבי דבר של עולי בבל מותר: „דבר של עולי בבל הוא הדבר המשותף לכל עולי הרגל . . שבונין אותן . . מממון כל ישראל ויש לכל אחד מהם בהן קנין אלא שהוא מועט מאד אין חוששין לו“ (כ״ה הלשון בתרגום קאפח. ועד״ז הובא במאירי שם (וכ״כ בפירושו הוא). ובפיה״מ לפנינו (הובא בתויו״ט): אין זה כ״א זכות מעט מאוד שאין לאחד מהם שום רשות). וגם להטעם (תוס׳, ר״ן, פי׳ הרא״ש, רע״ב ועוד שם) משום דהפקר הוי ולא דשותפין — היינו משום ד„לא נתנוהו להם להיות שותפין בו לענין שיוכל האחד לאסור חלק חבירו“ (תוס׳ שם). — ומכיון שכל בנ״י משתתפים בממונם בבנין המקדש, לכם, חלקם במקדש (לענין חיוב מעקה) הוא יותר מהחלק שיש לכל ישראל בביהכנ״ס מחמת זה ש„דירת בהכ״נ שייך לכל“ (כנ״ל ס״ג מפרש״י והצפע״נ) — ראה לעיל הערה 21."],["32","32","ואף שישראל מותר להכנס רק בעזרות ולא בהיכל שעליו המעקה*) — ה״ז רק משום ארי׳ דרביע *) אבל ראה לקמן הערה 39 — בנוגע לעליית וגג ההיכל."]]],[1300241156,"נתחייב געווארן צו מאכן א מעקה ווען זיי האבן געבויט דעם ביהמ״ק³³.\nאון צו זיין מחויב במעקה מוז ניט זיין „גגך“ בשלימות ממש (וכנ״ל סעיף ג׳, אז אויך א בית של שותפים איז ניט קיין אמת׳ער „גגך“) און מען מוז בא־ווארענען דעם „כי יפול הנופל ממנו“³⁴.\nה. מען קען נאך אבער פרעגן:\nדער חיוב מעקה איז דוקא בא א „בית דירה“³⁵ (ווייל אנדערש איז דאך „אינו זקוק לו“³⁶); וואס (אויך) מטעם זה זיינען בתי כנסיות ובתי מדרשות פטור ממעקה, ווייל ביהכנ״ס „אינו בית דירה“³⁷ [ובפרט לדעת הרמב״ם וואס ברענגט נאר דעם טעם — „לפי שאינן עשויים לדירה“³⁸ — כנ״ל סעיף ב] —\nאון דער היכל איז דאך ניט א בית דירה?\nויש לומר בזה³⁹: דער ענין הדירה איז פארבונדן בעיקר מיט אכילה, ווי דער דין ביי סוכה, וואו עס דארף זיין „תשבו",[["","","עלי׳ איסור התורה, ולא מצד חסרון בבעלות שלהם (ולהעיר מתוי״ט למשנה נדרים שם), ולכן יש לומר דגם ישראל מצ״ע מחויב במעקה כדי ש„לא יפול הנופל ממנו“, ולא רק מפני שצריכים להשתתף בבנית כל ביהמ״ק."],["33","33","משא״כ בביהכנ״ס כו׳ (שלא נבנה מקופת ציבור דכל ישראל) אין לחייב (רק) בני העיר בענין ששייך לכל ישראל. וצ״ע."],["34","34","עוד י״ל — את״ל דמאמר חז״ל (שמו״ר פ״ל, ט) „מה שהוא עושה הוא אומר לישראל לעשות“ (שהקב״ה מקיים מצוות התורה) הוא גם גדר בהלכה: ביהמ״ק הוא דירת הקב״ה* [ונק׳ „בית לה׳“ (הובא בהלכה — רמב״ם ריש הל׳ ביהב״ח), ואומר עליו „זאת מנוחתי“ (תהלים קלב, יד. רמב״ם שם פ״א ה״ג), דירת קבע — לאחרי ואהלתך באוהל]: ולכן יש חיוב כביכול על הקב״ה לעשות מעקה על גג דירתו, ובנ״י עשאוה בשליחותו של הקב״ה. [ויש לחלק בין זה למ״ש בשו״ת חת״ס (הנ״ל הערה 13) דאין חיוב מזוזה על ביהכנ״ס כי הוא דירה של קדש, „דירת גבוה“, ודוקא דירת הדיוט חייבת במזוזה (ולא אמרינן בזה „מה שהוא עושה כו׳“) — כי ענין המזוזה הוא קביעות שם ה׳ על פתח הבית, ואין צורך בזה ב„דירת גבוה ה׳ אלקי ישראל“ (ל׳ החת״ס שם), משא״כ מעקה שענינו שמירת הבית ש„לא יפול הנופל ממנו“, צ״ל גם בדירת הקב״ה (אם בנ״א משתמשים בו. וראה לקמן סעיף ה)]. *) ומ״ש בחת״ס (שבפנים ההערה) דגם ביהכנ״ס הוא „דירת גבוה“ — היינו רק לענין „דירה“ שצ״ל במזוזה, דדירת גבוה לא נק׳ דירה; משא״כ מעקה — תלוי ב„גגך“ וביפול הנופל — כבפנים."],["35","35","ספרי פרשתנו שם. רמב״ם הל׳ רוצח כו׳ רפי״א. שו״ע חו״מ ר״ס תכז. שו״ע אדה״ז חלק חו״מ הל׳ שמירת גוף ונפש כו׳ סעיף א."],["36","36","רמב״ם שם (וראה הערה 38). שו״ע שם. וראה שו״ע אדה״ז שם."],["37","37","רש״י חולין (הנ״ל הערה 19)."],["38","38","וצ״ע, לכאורה, דא״כ למה צריכים מיעוט מיוחד ד„גגך“ — והרי „אינו זקוק לו“ מכיון שאינו עשוי לדירה; ועכ״פ נלמד זה מ„בית“ (כבספרי שם. וראה הגמ׳ שם). וראה סמ״ע שם סק״ה. ויש לומר, דהו״א דביהכנ״ס וביהמ״ד נק׳ בית דירה, מכיון שמשתמש בו היחיד בקביעות לתפלה ותורה*, ולכן צ״ל מיעוט מיוחד (שגם הם בכלל „אינם עשויים לדירה“)."],["39","39","גם י״ל להמ״ד דגגין של היכל לא נתקדשו (ראה אנציקלופדי׳ תלמודית ע׳ גגין ועליות (ע׳ קלג) וש״נ), וא״כ מותרת ההשתמשות בם — והרי הפטור דאינו בית דירה הוא מפני שאין משתמשין על הגג (ראה שו״ע אדה״ז שם). ולהעיר משו״ת מבי״ט סק״י. שד״ח כללים מע׳ המ״ם כלל קצה (תקנה, ב). ולהעיר דאת״ל שעליית ההיכל לא הייתה פתוחה להיכל צ״ע אם קדושתה כהיכל או כעזרה (ראה צל״ח פסחים פו, א. אנצק׳ תל׳ שם). כן להעיר ממלכים (ב יא, ב ואילך) שהסתירו את יואש בחדר המטות — עליית בית קדש הקדשים (רש״י שם) — שש שנים. *) להעיר דמדינא תדורו דסוכה — הוא גם בנוגע לת״ח (מקומות שנסמנו בהערה 40)."]]],[1300241157,"כעין תדורו“⁴⁰, אז „עיקר מצות הישיבה בסוכה“ איז די אכילה בסוכה⁴¹.\nאון דערפאר איז מקדש א „בית דירה“, ווייל דאס איז דער מקום קבוע אויף אכילת קדשים⁴²; און אע״פ אז אכילת קדשים איז נאר בעזרה און ניט אין היכל (אויף וועלכן ס׳איז געווען די מעקה (על גגו)) — איז אבער דער דין⁴³, אז מען מעג\nויותר מזה — מען דארף און מען מוז (בשעת הדחק) עסן קדשי קדשים בהיכל.\n[ס׳איז קיין קשיא ניט פון דעם וואס בשעת הדחק מעג א ת״ח עסן אויך אין א ביהכנ״ס⁴⁴ (וכש״כ אין א ביהמ״ד⁴⁵) און אעפ״כ ווערן זיי ניט אנגערופן „בית דירה“ כנ״ל — ווייל דארטן איז דער היתר מצד דעם וואס אזא אכילה ושתי׳ (ושינה) איז דרך עראי, און דערפאר הייסט עס ניט א „בית דירה“ אויף נתחייב ווערן במעקה, ווייל ס׳איז נאר ע״ד ווי א דירת עראי (סוכה⁴⁶; בית בחו״ל פחות מל׳ יום וואס איז פטור ממזוזה⁴⁷)]:\nמשא״כ אכילת קדשי קדשים, וואס די אכילה איז א מצוה וואס מצותי׳ אחשבי׳⁴⁸ ובפרט אז עס דארף זיין אין אן אופן פון „למשחה — לגדולה“⁴⁹, איז דאס אן ענין של קביעות. תורה האט געהייסן עסן ק״ק בהיכל (עכ״פ בשעת הדחק), איז עס א „בית דירה“⁵⁰].\nו. דער ביאור החילוק צווישן ביהכנ״ס כו׳ און ביהמ״ק (לגבי חיוב מעקה) בפנימיות הענינים — וועט זיין פארשטאנדיק לויטן ביאור ענין המעקה בעבודה רוחנית:\nדער פירוש פנימי אין „ועשית מעקה לגגך גו׳ כי יפול הנופל ממנו“ איז: „גגך“ ווייזט אויף הגבהה וגאוה⁵¹, און „ועשית מעקה לגגך“ מיינט, אז מען מוז פארצאמען און מגביל זיין די גאוה⁵²: „כי יפול הנופל ממנו“ — ווייל מדת הגאוה איז דער שרש פון יעדער נפילה רוחנית, כידוע⁵³ אז מדות רעות ביים אדם נעמען זיך פון זיין ישות וגאוה.\nאון דאס איז אויך די הוראה כללית פון דעם וואס אויך דער היכל דארף האבן א מעקה:",[["40","40","סוכה כח, ב. וש״נ. טושו״ע (ואדה״ז) או״ח ר״ס תרלט."],["41","41","שו״ע אדה״ז שם סי״ב. וראה טור שם. נ״כ השו״ע שם בסוף הסימן."],["42","42","להעיר דישיבת מלכי בית דוד היא בעזרה (רמב״ם הל׳ ביהב״ח פ״ז ה״ו)."],["43","43","זבחים סג, א. ספרי קרח יח, י. רמב״ם הל׳ מעה״ק פ״י ה״ג. וראה מנ״ח מצוה קפד."],["44","44","רמב״ם הל׳ תפלה פי״א ה״ו (וראה כס״מ שם). טושו״ע או״ח ר״ס קנא ונ״כ. וראה אנציקלופדי׳ תלמודית ע׳ בית הכנסת ע׳ קצה. וש״נ."],["45","45","ראה רמ״א שם. וראה פרטי החילוקים בביהמ״ד לגבי ביהכנ״ס — אנציקלופדי׳ תלמודית ע׳ בית המדרש ע׳ ריא. וש״נ."],["46","46","סוכה בתחלתה."],["47","47","מנחות מד, א. טושו״ע יו״ד סרפ״ו סכ״ב. ב״ח לטור שם. ש״ך שם."],["48","48","ראה בכורות י, א. רש״י ד״ה חלה (ביצה כז, ב)."],["49","49","קרח יח, ח. זבחים צא, א (וש״נ)."],["50","50","והא דהיכל פטור ממזוזה, ה״ז מפני שהוא קודש (יומא יא, ב. רמב״ם הל׳ מזוזה פ״ו ה״ו). וגם לפמ״ש בחת״ס (כנ״ל הערה 13) שתלוי רק בענין דירה (של הדיוט) — יש לחלק בין שם „דירה“ לענין חיוב מזוזה, לשם „דירה“ גבי מעקה (שענינו השמירה שלא „יפול הנופל“). ולהעיר מסמ״ע חו״מ שם סק״ב. וי״ל שלכן צריך ריבוי מיוחד לחייבו במעקה — „בית לרבות היכל“ — כי לולא זה הו״א דאין זה בכלל „עשויין לדירה“."],["51","51","להעיר ממחז״ל בנוגע לגג ביהכנ״ס ובתי העיר (שבת יא, רע״א)."],["52","52","של״ה חלק תושב״כ סוף פרשתנו. וראה אוה״ת להה״מ פרשתנו עה״פ. ועוד."],["53","53","ראה דרושים עה״פ ראשית גוים עמלק."]]],[1300241158,"מען קען מיינען, אז די באווארעניש פון א מעקה איז נויטיק נאר אין די ענינים פון „בית של חול“, וואס זיין „גג“ (גבהות וגאוה) איז פשוט׳ע גאוה, היפך הקדושה:\nבשעת עס רעדט זיך אבער וועגן מקדש, וואס איז כולו קודש — איז דאך אויך דער גג המקדש אן עבודה דקדושה: „ויגבה לבו בדרכי ה׳“⁵⁴, וכמחז״ל⁵⁵ אז א „ת״ח צריך שיהא בו אחד משמונה שבשמינית“ — וואס דארף מען דא באווארענען — שזהו ענין המעקה?\nאיז די הוראה, אז אפילו דער גג המקדש דארף האבן א מעקה; און נאכמער: אין מקדש גופא איז די מעקה געווען אויפן גג ההיכל, און אויך פון דעם קודש הקדשים⁵⁶.\nווארום אפילו ווען מ׳האלט שוין בתכלית העלי׳, מוז מען זיין געווארנט און געצאמט דורך דעם הרגש הביטול; ואדרבה — „כלים הנגמרים בטהרה צריכין טבילה לקודש“⁵⁷: אפילו בשעת מ׳האלט ביי א דרגא וואס גיט אן ארט צו מיינען אז מ׳איז שוין א „פארטיקע“ כלי, אזא וואס איז נגמר געווארן בטהרה — דארף מען דאן ערשט⁵⁸ האבן „טבילה — אותיות ביטול⁵⁹ — לקודש“.\nז. מעקה כפשוטה איז דאך ניט (אזוי) אויף פארהיטן זיך, נאר (בעיקר) צו בא־ווארענען אז א צווייטער זאל ניט פאלן פון „גגך“.\nועד״ז איז אין ענין המעקה ברוחניות: די „מעקה לגגך“ איז ענינה ניט נאר צו אויסהיטן זיך אליין פון א נפילה רוחנית, נאר אויך צוליב א צווייטן אידן, אז „גגך“ — דיין גבהות וגאוה — זאל ניט גורם זיין א נפילה רוחנית ביי א צווייטן.\nבשעת א איד פארנעמט זיך מיט הפצת היהדות און מקרב זיין אידן לאביהם שבשמים —\nוואס דאס איז אויך נכלל⁶⁰ אין „כי תבנה בית חדש“ (לויט פנימיות הענין), אז א איד זאל זיך ניט באגנוגענען מיט עבודת עצמו, נאר ער דארף „אויפ־בויען“ א בית לה׳, אויפשטעלן א גאנצן שלימות׳דיקן „בית“, א סביבה וואס זאל זיין דורכגענומען מיט אידישקייט⁶¹ —\nאון דערביי האט ער גאוה, איז עס ניט נאר א חסרון אין זיין עבודה (פרטית), נאר עס קען גורם זיין א נפילה ביים צווייטן אויף וועמען ער דארף משפיע זיין. בשעת ער איז משפיע אויף דעם זולת מיט דברים היוצאים מן הלב, און קיין אייגענע פניות כו׳, איז מען בטוח אז די דברים וועלן אויך זיין נכנסים אל הלב און פועל זיין פעולתם:\nאויב אבער אין זיינע רייד איז דאָ אן אריינמישונג פון ישות וגאוה, איז לבד זאת וואס דאס איז א שטערונג אין דער השפעה והצלחה פון זיינע רייד צו מקרב זיין דעם זולת, איז עס עלול צו",[["54","54","דה״ב יז, ו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370411\" data-slug=\"torah-or\" data-id=\"3901370411\">תו״א צא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370533\" data-slug=\"torah-or\" data-id=\"3901370533\">קיט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380370\" data-slug=\"likkutei-torah\" data-id=\"4001380370\">לקו״ת במדבר טו, ג</a>. ועוד."],["55","55","סוטה ה, א. וראה תו״א שם."],["56","56","כמובן ממקומות שנסמנו בהערה 3."],["57","57","משנה חגיגה כ, ב. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940039\" data-slug=\"or-hatorah-hb\" data-id=\"8159940039\">אוה״ת ויקרא (כרך ב</a>) דרושים לפסח ע׳ תנה."],["58","58","להעיר מתו״א שם (קכ, א) דשמינית שבשמינית צ״ל רק בתחלת העבודה אבל אח״כ צ״ל בביטול לגמרי. וראה לקוטי לוי״צ אגרות ע׳ שה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221162\" data-slug=\"likkutei-sichot\" data-id=\"1300221162\">לקו״ש חכ״ב ע׳ 162</a> הערה 32."],["59","59","אלא שנתחלף הוי״ו בה״א (סידור עם דא״ח כוונת המקוה בסופה — קנט, סע״ד)."],["60","60","גם בפשטות: הכנסת אורחים, יהי ביתך בית ועד לחכמים (אבות פ״א, מ״ד)."],["61","61","ראה בארוכה בזה — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191223\" data-slug=\"likkutei-sichot\" data-id=\"1300191223\">לקו״ש חי״ט ע׳ 210</a>, 212."]]],[1300241159,"גורם זיין דעם היפך דערפון — די גאוה אין זיינע רייד קענען נאך מרחק זיין דעם שומע, ר״ל.\nועוד זאת באווארנט דער פסוק — „כי יפול הנופל ממנו“, וכפי׳ חז״ל⁶² „ראוי זה ליפול מששת ימי בראשית . . אלא שמגלגלין זכות על ידי זכאי וחובה על ידי חייב“:\nא איד קען טענה׳ן, אז די נפילה פון צווייטן איז ניט זיין שולד, נאר ווייל יענער איז „ראוי . . ליפול“, אדער נאך מער — „נופל“ כפשוטו, ער איז שוין א נופל⁶³:\nווען דער צווייטער וואלט געווען אן איש ישר הולך, וואלט ער מבחין געווען צווישן די אמת׳קייט פון זיינע רייד (וואס זיינען ווערטער פון תורה) און די ישות כו׳ (של האדם) וואס איז אין זיי אריינגעמישט, ע״ד מחז״ל⁶⁴ „תוכו אכל קליפתו זרק“⁶⁵:\nנאר ווייל יענער איז שוין א נופל, דעריבער, ווען ער דערהערט אן ענין פון ישות כו׳ פועל׳ט עס אויף אים א ירידה יתירה — היינט וואס איז ער שולדיק אין דעם, אז ער זאל דארפן בא־ווארענען זיין „גג“, אז דער וואס איז שוין א „נופל“ זאל ניט האבן נאך א גרעסערע נפילה?\nזאגט מען אים, אז ניט קוקנדיק וואס יענער איז א נופל, ליגט אבער אויף אים א חיוב צו פארהיטן, אז פון „גגך“ — פון דיין גג — זאל ניט ארויסקומען אויך די\nנפילה פון א נופל⁶⁶; דו דארפסט ניט זיין פון די וואס אויף זיי ווערט געזאגט „מגלגלין . . חובה על ידי חייב“ — דער גורם צום צווייטנס נפילה.\nח. אויף דעם קען מען האבן א טענה: וויבאלד ער ווייס אז ער האט ישות, איז צו וואס זאל ער זיך אריינ־לאזן אין א ספק — צי ער וועט יע קענען אדער ניט קענען מאכן א „מעקה“ כדבעי, וואס זאל באווארענען (זיינע און) דעם צווייטנס נפילה — ער וועט אינגאנצן ניט פארנעמען זיך מיט „בנין הבית“, ובפרט — מיט אויפבויען און מקרב זיין א צווייטן אידן!\nאיז דער פסוק מקדים און אלס א ברכה⁶⁷ „כי תבנה בית חדש“: א איד דארף בויען א בית לה׳ דורך אויפ־שטעלן ארום זיך א סביבה פון אידיש־קייט, כנ״ל: און ער קען זיך ניט פארלאזן אויף אנדערע, נאר עס דארף זיין „בית חדש“: פאר יעדן אידן איז צוגעטיילט געווארן א חלק בעולם⁶⁸ וואס ער דארף מברר זיין און ער דארף אין עם מחדש זיין — דערפון מאכן א דירה לו ית׳. ער קען זיך ניט פארלאזן אויף דער עבודה פון אלע פריערדיקע דורות, אדער אויף דער עבודה פון אנדערע אידן שבדורו — נאר עס ליגט אויף אים א חיוב גברא צו אויפבויען זיין חלק בעולם, וואס דאס איז זיין חידוש (און ניט א צווייטנס).\nאון דערפאר, ווען ער טרעפט א צווייטן אידן — וואס דאס גופא איז",[["62","62","שבת לב, א. פרש״י עה״פ."],["63","63","ראה פענח רזא כאן: הנפל חסר ו׳ . . לשון עבר. צרור המור כאן."],["64","64","חגיגה טו, ב."],["65","65","וע״ד קבל את האמת ממי שאמרו (פיה״מ להרמב״ם הקדמה לאבות. רמ״א בהקדמתו למחיר יין. ועוד)."],["66","66","כמו מעקה כפשוטו, דאף שראוי ליפול משי״ב, „עונש גדול למי שמסבב“ (בחיי כאן. וראה אלשיך כאן. מו״נ ח״ג פ״כ). ולהעיר מאגה״ק ר״ס כה (קלה, ב)."],["67","67","תנחומא הובא בפרש״י עה״פ."],["68","68","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז (מח, א</a>)."]]],[1300241160,"(בהשגחה פרטית, ובמילא) א הוכחה אז יענעם׳ס בירור איז פארבונדן מיט אים — מוז ער זיך פארנעמען מיט אים.\nאויב אפילו דער צווייטער איז א „נופל“, און ביי עם איז דאָ „גג“ וואס קען גורם זיין א (תוספת) נפילה ביים צווייטן — איז צי דערפאר וואס ביי עם איז דא ישות וגאוה, דארף פעלן ביי א צווייטן, ביי דעם וואס זיין תיקון איז פארבונדן מיט עם? מאך א מעקה און פארצאם דיין ישות! ולא אתה בן חורין להבטל ממנה — פון פארנעמען זיך מיט א צווייטן אידן.\nוכידוע דער סיפור פון חסידים בשם פון מיטעלן רבי׳ן:\nדער מיטעלער רבי האט געמאכט א תקנה אז די חסידים וואס פלעגן קומען קיין ליובאוויטש זאלן אויף זייער וועג צוריק אהיים חזר׳ן חסידות אין די שטעטלעך וואס זיי גייען פארביי. האט איינער א יונגערמאן א חסיד — וואס פלעגט חזר׳ן חסידות בטוב טעם — זיך פארקלאגט פארן מיטעלן רבי׳ן, אז ביים חזר׳ן חסידות דערפילט ער א רגש גאוה, וויל ער אויפהערן צו חזר׳ן חסידות. האט אים דער מיטעלער רבי געענטפערט: „א ציבעלע⁶⁹ זאל פון דיר ווערן, אבער חסידות זאלסטו חזר׳ן“!\nט. ע״פ כל הנ״ל וועט מען אויך פארשטיין דעם חילוק צווישן ביהכנ״ס כו׳ און בית המקדש:\nדער ענין פון בית הכנסת ובית המדרש איז — עבודת התפלה ולימוד התורה, וואס דאס איז די עבודה רוחנית פון דעם מענטשן אין זיך און מיט זיך: משא״כ ביהמ״ק דריקט אויס כללות\nעבודת האדם⁷⁰ — ניט נאר די עבודה מיט זיך, נאר אויך (ואדרבה — בעיקר) די עבודה פון „דירה בתחתונים“, צו מאכן פון ענינים גשמיים און וועלט בכלל א דירה לו ית׳.\nוואס דערפאר איז איינע פון די עבודות עיקריות אין מקדש — די עבודת הקרבנות⁷¹, מעלה זיין די בהמה וכו׳ גשמית לה׳, און עס איז דאָ אכילת כהנים ואכילת בעלים, וואס איז אן ענין פון עבודת הבירורים.\nועד״ז איז כללות ענין המקדש צו משפיע זיין אויף דער וועלט ארום, וואס דערפאר זיינען די חלונות המקדש געווען „שקופים אטומים“ כדי אז „אורה“ זאל לייכטן און באלייכטן דעם חוץ און זיין אן עדות „לכל באי עולם שהשכינה שורה בישראל“⁷².\nאון וויבאלד אז דער תפקיד עיקרי פון מעקה איז צו באווארענען דעם „יפול הנופל ממנו“ — א צווייטן וואס איז אין א דרגא פון „נופל“, ועד״ז ביי זיך, ווען מ׳איז פארנומען מיט דער עבודה וואס איז פארבונדן מיט יורד זיין פון דער אייגענער מדריגה און פארנעמען זיך מיט בירור העולם („תבנה בית חדש“)⁷³ —\nדעריבער מוז א ביהכנ״ס וביהמ״ד, ביי וועלכע דער מענטש איז אויס־",[["69","69","להעיר שטעמו בפע״ע מר, אבל מתבל המאכל."],["70","70","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161293\" data-slug=\"likkutei-sichot\" data-id=\"1300161293\">לקו״ש חט״ז (ע׳ 293</a>) לענין ג׳ תרומות המשכן, שבהן נרמזו ג׳ סוגי עבודה דתורה עבודה וגמ״ח. וראה ע׳ 297."],["71","71","ויתרה מזה ברמב״ם הל׳ ביהב״ח בתחלתו: מ״ע לעשות בית לד׳ מוכן להיות מקריבין בו הקרבנות וחוגגין אליו כו׳. — ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161492\" data-slug=\"likkutei-sichot\" data-id=\"1300161492\">לקו״ש שם ע׳ 479</a> ובהנסמן שם."],["72","72","מנחות פו, ב."],["73","73","ראה בארוכה בזה — לקו״ש חי״ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191223\" data-slug=\"likkutei-sichot\" data-id=\"1300191223\">שם (ע׳ 210</a> ואילך)."]]],[1300241161,"געטאן פון עניני העולם, ניט האבן קיין מעקה.\nמשא״כ ביהמ״ק וואס טוט אויף אין גשמיות העולם — און אין עבודה רוחנית איז דאס די עבודה פון בויען א בית לה׳, מאכן פון דער סביבה א דירה לו ית׳ — ביי דעם פאדערט זיך די בא־ווארעניש פון מעקה⁷⁴.\nאעפ״כ איז דער תכלית השלימות פארבונדן מיט בית המקדש דוקא, ווייל דורך דער עבודה דוקא פירט זיך אויס די כוונת הבריאה, אז ס׳וועט „תבנה בית חדש“ — מען שטעלט אויף א דירה לו ית׳ בתחתונים,\nאון דורך דעם איז מען אויך זוכה צום בנין בית המקדש השלישי, במהרה בימינו ממש.\n(משיחת ש״פ מטות תשמ״א)",[["74","74","להעיר מבעה״ט, צרור המור ואלשיך כאן — שמפרשים „כי תבנה בית חדש“ על הביהמ״ק. ע״ש."]]],[1300241162,"<h3>תצא ג</h3>\nא. בשייכות צום פסוק¹ „לא תחרוש בשור ובחמור יחדיו”, שטייט אין משנה (מס׳ בבא קמא²): „אחד שור ואחד כל בהמה . . א״כ למה נאמר שור או חמור אלא שדבר הכתוב בהוה”, און די גמרא³ איז מסביר אז „כלאים דחרישה יליף שור שור משבת”⁴ (דכתיב⁵ שורך וחמורך וכל בהמתך, רש״י).\nבפרטי הדין געפינט מען א מחלוקת הראשונים:\nדער רמב״ם פסק׳נט⁶ „אחד שור וחמור ואחד כל שני מינין שאחד טמא ואחד טהור . . לוקה מן התורה” (און פירט אויס, „אבל מדברי סופרים שני מינין שהן כלאים בהרבעה (ד.ה. יעדע צוויי מינים (טהורים אדער טמאים)) אסורים לחרוש בהם כאחד ולמשכן ולהנהיגם”):\nדער רא״ש שרייבט אויף דעם⁷ „ואין דבריו נראין”, און ער פסק׳נט, אז אפילו אויב שניהם טהורים אדער שניהם טמאים, איז מען אויך עובר מן התורה.\nאון יסוד המחלוקת איז אין דעם פירוש פון דער משנה אין כלאים⁸:\nדי משנה זאגט⁹ „כלאי בהמה מותרים לגדל ולקיים ואינם אסורים אלא מלהרביע . . (און די משנה שלאח״ז איז ממשיך) בהמה עם בהמה וחי׳ עם חי׳ . . טמאה¹⁰ עם טמאה וטהורה עם טהורה טמאה עם טהורה וטהורה עם טמאה אסורין לחרוש כו׳”.\nלערנט דער רא״ש, אז „מתניתין (די צווייטע משנה) כוללת יחד טמאה עם טמאה טהורה עם טהורה טהורה עם טמאה וטמאה עם טהורה”, ד.ה. אז דער איסור פון „כלאים דחרישה”¹¹ איז אויך דא ביי טמאה עם טמאה און טהורה עם טהורה.\nדער רמב״ם אבער לערנט (אין פירוש המשניות), אז די ערשטע עטליכע פאלן (פון דער צווייטער משנה) קומען בהמשך צו איסור הרבעה פון דער ער־שטער משנה, און בלויז די פאלן „טמאה עם טהורה וטהורה עם טמאה” באציען זיך צום אויספיר פון „אסורין לחרוש כו׳”.\nאון דער פשט לויטן רמב״ם איז — ובפרט לויט זיין גירסא במשנה זו¹² אז זי הייבט זיך אן „במה דברים אמורים” (אז זיי זיינען אסורים נאר „מלהרביע”) „בהמה עם בהמה כו׳, אבל טמאה עם טהורה . . אסורין (אויך) לחרוש כו׳”.",[["1","1","פרשתנו כב, יו״ד."],["2","2","ספ״ה (נד, ב)."],["3","3","שם."],["4","4","וכן הובא ברא״ש ב״ק שם ובהלכות קטנות הלכות כלאים ס״ה. רדב״ז על הרמב״ם הל׳ כלאים פ״ט ה״ח בתחלתו. אבל ראה תוי״ט ב״ק שם. וראה לקמן הערה 30."],["5","5","ואתחנן ה, יד."],["6","6","הל׳ כלאים פ״ט ה״ח. וראה פיה״מ ב״ק שם. כלאים פ״ח מ״ב. סהמ״צ מל״ת ריח."],["7","7","בהל׳ קטנות שם. הובא בכס״מ לרמב״ם שם. ב״י לטור יו״ד סרצ״ז ד״ה כל העושה."],["8","8","ראה רדב״ז לרמב״ם שם ובפירושי ר׳ חיים פלטיאל עה״ת כאן (ירושלים תשמ״א)."],["9","9","פ״ח מ״א־ב."],["10","10","במשניות דהרמב״ם (קאפח — משא״כ בפיה״מ שלפנינו) מכאן ואילך — הסדר מהופך וטהורה קודם, וצ״ע."],["11","11","ל׳ הגמ׳ ב״ק שם."],["12","12","ובמלאכת שלמה (כלאים שם) ובברכ״י (יו״ד סי׳ רצז ס״ד) הובאה ג״כ גירסא זו, ושם גם הגי׳ במשניות „אבל טמאה עם טהורה כו׳”. וכ״ה בכמה כת״י דמשניות — ראה משניות זרעים עם שינוי נוסחאות (ירושלים, תשל״ב). וש״נ."]]],[1300241163,"ויש לומר, אז אויך סברא ישנה בדבר און די סיבת המחלוקת איז ניט (נאר) מצד פירוש המשנה, נאר מצד הסברא, ואדרבה — מצד זייער מחלוקת בסברא קומט ארויס די מחלוקת אין פירוש המשנה (וקביעות הגירסא במשנה).\nב. לכאורה וואלט מען געקענט לערנען, אז די מחלוקת באשטייט אין דעם פירוש פון דעם כלל „דבר הכתוב בהוה” וואס די משנה זאגט אין ב״ק (אויך) בנוגע צו כלאי בהמה:\nלויטן רא״ש, ווען מ׳זאגט „דבר הכתוב בהוה”, מיינט עס לגמרי, נאר דערפאר וואס עס איז „הווה”. ד.ה. מ׳קען גארניט ממעט זיין, שולל זיין דערפון וואס תורה זאגט „בשור ובחמור”, דער איסור איז חל אויף אלע בע״ח.\nדאקעגן לדעת הרמב״ם, איז כאטש אז מ׳זאגט „דבר הכתוב בהוה”, איז ניט מסתבר צו זאגן אז ס׳איז ניטא קיין שום לימוד פון דעם וואס דער פסוק איז מפרט און זאגט ניט סתם „כלאים” וכיו״ב. דעריבער זאגט דער רמב״ם, אז מ׳לערנט דערפון אפי׳¹³ בנוגע דעם סוג כללי, אז עס מוז זיין אחד טהור ואחד טמא.\n[און הגם אז בנוגע די אנדערע זאכן אין דער משנה אין ב״ק (ווי „נפילת הבור” און „תשלומי כפל” וכיו״ב) האלטן אלע אז דאס מיינט כל בהמה וחי׳ ועוף, און דאס וואס תורה ברענגט שור וחמור איז בלויז מצד „דבר הכתוב בהוה”, איז אבער כלאים אנדערש:\nביי „נפילת הבור” וכיו״ב, איז דער (עיקר ה)ענין — תשלומים פאר נזק וכיו״ב פון דעם בעה״ב¹⁴ איז ניטא קיין סברא צו מחלק זיין צווישן סוגי בע״ח וואס מ׳האט מזיק געווען¹⁵:\nמשא״כ ביי כלאים (דחרישה), וואו דער תוכן האיסור איז דער חיבור פון די צוויי מינים יחדיו, און תורה איז מדייק צו שרייבן (ניט „בהמתך” סתם, ווי ביי כלאים דהרבעה¹⁶, נאר) „בשור ובחמור” — לערנט מען דערפון, אז דאס איז נאר במין טהור וטמא].\nאבער כד דייקת קען מען אזוי ניט לערנען, ווייל ס׳איז היפך המשמעות הפשוטה פון „דבר הכתוב בהוה”, צו זאגן אז עס איז דא א דיוק.\nונוסף על זה: דער רמב״ם איז מפרש די משנה אין ב״ק, בנוגע צו כלאים דחרישה¹⁷ אז דאס מיינט כל שני מיני בהמות (אויך טהור וטהור און טמא וטמא), נאר ער לייגט צו „וזה מדרבנן אבל מן התורה אינו אסור . . אלא בהמה טהורה וטמאה בלבד דומיא דשור וחמור”; במילא איז מובן, אז אויך לדעת הרמב״ם גייט דער כלל „דבר הכתוב בהוה” אין משנה אויף אלע מינים¹⁸. קען",[["13","13","ראה לשונו בפיה״מ כלאים וב״ק שם. רדב״ז שם בתחלתו."],["14","14","ראה בגמרא ב״ק שם „כל דאית לי׳ בעלים”. וכיו״ב. וראה ב״י לטור חו״מ ר״ס שפט ד״ה ומ״ש רבינו."],["15","15","ושאני זה דלמדין (ב״ק כח, ב. וש״נ) „שור ולא אדם חמור ולא כלים” כפרש״י שם (נד, א) „שאינו מין בהמה”. וראה פרש״י שם נג, סע״ב ד״ה שור. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171138\" data-slug=\"likkutei-sichot\" data-id=\"1300171138\">לקו״ש חי״ז ע׳ 138</a>."],["16","16","קדושים יט, יט."],["17","17","וצ״ע ברדב״ז לרמב״ם שם דכ׳ „והך דפ׳ הפרה נמי בכלאים דהרבעה היא ולא בכלאים דהנהגה דומיא דשור וחמור”. ואולי מדייק בלשון הרמב״ם בפיה״מ (ב״ק) „אלא מאמרו לכלאים שהוא רומז למה שאמר לא תחרוש כו׳”, ואינו מפרש בכלל כלאים דהרבעה, לפי שזהו הפי׳ הפשוט במשנה. אבל ראה פיה״מ כלאים שם. וצ״ע."],["18","18","וכן מוכח גם בפיה״מ כלאים שם (בסופו). וצ״ע כיצד יפרש הלשון „דבר הכתוב בהוה” על ענין"]]],[1300241164,"מען ניט תולה זיין די הסברה פון שיטת הרמב״ם אין דעם פירוש פון „דבר הכתוב בהוה”¹⁹.\nג. אין דעם טעם האיסור פון כלאים דחרישה געפינט מען דעות שונות:\nיש אומרים²⁰, אז דער איסור איז „משורש איסור הרבעת הבהמה כל־אים”²¹, ווייל „דרך כל עובד אדמתו להביא צמדו ברפת אחת וירכיב אותן”²².\nויש אומרים²³, אז „מטעמי מצוה זו ענין צער בעלי חיים”.\nועפ״ז אפשר לומר, אז אין דעם בא־שטייט די מחלוקת פון רמב״ם מיטן רא״ש:\nלדעת הרא״ש איז דאס „משורש איסור הרבעת בהמה”, ווייל סו״ס ברענגט די חרישה יחדיו צו הרבעה; ובמילא איז דער איסור גילטיק ביי אלע צוויי מינים צוזאמען, פונקט ווי ביי כלאים דהרבעה.\nאבער לדעת הרמב״ם איז דאס מצד צער בע״ח —\nאון דעריבער איז דער איסור (מה״ת) נאר ביי טהורה עם טמאה, בדוגמת שור וחמור, ווייל דוקא דעמולט איז דא דער־ביי דער טעם „שזה מעלה גרה וזה לא יגר וחושב שהלה אוכל ויש לו צער בע״ח”²⁴; אדער, ווי דער חינוך איז מסביר, אז דער טעם פון דעם צער איז „שיש למיני הבהמה והעופות דאגה גדולה לשכון עם שאינן מינן וכל שכן לעשות עמהם מלאכה”, און דער עיקר צער איז „בשני מינין שהם כגון שור וחמור שהאחד טהור והשני טמא שטבעם רחוק מאד זה מזה”.\nעס איז אבער שווער צו לערנען אז דער גאנצער איסור פון כלאים דחרישה איז נאר משום צעב״ח, וויבאלד אז אין תורה שטייט דער פסוק „לא תחרוש גו׳” צווישן די פסוקים פון כלאים²⁵ (כלאי הכרם און כלאי בגדים)²⁶, און אויך אין משנה²⁷ זיינען די דינים (פון כלאים דחרישה) אין מס׳ כלאים און בחדא מחתא מיט „כלאים דהרבעה”¹¹.\nובפרט אז דער רמב״ם אליין איז מבאר אין מו״נ²⁸, אז דער טעם פון כלאים דחרישה איז „כי אם יקבץ בין",[["","","שהוא מדרבנן. וכ״כ במו״נ ח״ג פמ״ט. וי״ל שהוא ע״ד אסמכתא. וראה לקמן הערה 29."],["19","19","ועוד: הרי בגמ׳ (ב״ק שם) ילפינן מכתובים „שור שור משבת” „בהמתך בהמתך משבת”. וראה הנסמן לעיל הערה 4. וראה אנציקלופדי׳ תלמודית ערך דבר הכתוב בהוה. ב״ח חו״מ שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171131\" data-slug=\"likkutei-sichot\" data-id=\"1300171131\">לקו״ש שם ע׳ 131</a> וע׳ 138."],["20","20","רמב״ן ובחיי כאן ובקדושים יט, יט. מו״נ שם. פענח רזא כאן. חינוך מצוה תקנ."],["21","21","ל׳ החינוך שם."],["22","22","ל׳ הרמב״ן שם ושם. ולהעיר דעפ״ז מצינו עוד מצוה דאורייתא מטעם סייג — ראה לקח טוב (להר״י ענגל) כלל ח."],["23","23","חינוך שם. בעה״ת ובעה״ט ופענח רזא ופי׳ א׳ בחזקוני כאן. ועוד. וראה פי׳ ר׳ חיים פלטיאל שם. וראה ראב״ע כאן (ופי׳ הג׳ בחזקוני). אבל ראה מ״ש עליו הבחיי."],["24","24","ל׳ הפענח רזא שם. ועד״ז הוא בבעה״ת ובעה״ט וחזקוני שם. ואף שגם במינין טמאין יש מעלי גרה (הגמל וכו׳), י״ל, דכיון שע״ד הרגיל הוא בטהורים דוקא, לכן כל האיסור נאמר מלכתחלה בטהור וטמא. וע״ד (ולא ממש) שמבאר במו״נ (ח״ג פל״ד) שהתורה על הרוב תדבר כו׳. ועצ״ע."],["25","25","ראה בחיי כאן."],["26","26","אבל י״ל שנאמר בתורה בסמיכות אף שאינו מאותו הטעם כיון שהפעולה יש בה דמיון לכלאים. וראה ראב״ע כאן וחזקוני כאן: ונסמכה כאן לפי שדבר לעיל בענין זריעה, ובשביל הזריעה סמך כאן שעטנז."],["27","27","וכן ביד החזקה להרמב״ם (כנ״ל)."],["28","28","שם. ובחינוך שם: שרש המצוה כתב הרמב״ם שהוא משורש איסור הרבעת הבהמה כלאים כי דרך כו׳ (ומביא הלשון כברמב״ן פרשתנו כאן וקדושים שם)."]]],[1300241165,"שניהם פעמים ירכיב אחד מהם על חבירו”²⁹.\nד. ויש לומר, אז זייער מחלוקת איז צי דער ענין פון כלאים דחרישה איז א חלק פון כלאים דהרבעה, אדער דאס איז א דין בפ״ע²⁹*:\nדער רא״ש האלט אז כלאים דחרישה איז דער זעלבער ענין ווי כלאים דהרבעה, און דער רמב״ם האלט אז עס איז א ענין בפני עצמו³⁰.\nאון הסברת הפלוגתא (צי כלאים דחרישה איז דער זעלבער ענין ווי כלאים דהרבעה): כלאים איז תוכנו — „עירוב”, „תערובת”³¹:\nלדעת הרמב״ם איז דער איסור כלאים דהרבעה פארבונדן מיט א תערובת וועלכע איז ניכר וגלוי — אלס תוצאה פון פעולת ההרבעה ווערט נוצר א ולד מיט א מראה מיוחד ותכונות גופו וכו׳ א מין חדש וועלכער קומט פון הרכבת שני מינין דוקא³²; משא״כ ביי כלאים דחרישה איז דער ענין התערובת ניט משפיע וניכר אין דער חרישה וכו׳.\nאון דערפאר איז לדעת הרמב״ם — זייענדיק כל אחד אן ענין בפ״ע — א חילוק צווישן כלאים דהרבעה (אז זיי זיינען ביי אלע שני מינין), און כלאים דחרישה (דוקא מין טהור ומין טמא).\nאבער דער רא״ש האלט, אז ביי ביידן, סיי ביי כלאים דהרבעה סיי ביי כלאים דחרישה, איז דער איסור די פעולה פון מחבר זיין צוויי מינים — ובמילא איז ביי ביידן דער זעלבער דין.\nה. דער ביאור הנ״ל איז אבער ניט אינגאנצן גלאטיק לדעת הרמב״ם:",[["29","29","ואף שאין הכרח שיתאים טעם המצוה במו״נ שם עם שיטתו להלכה בספר היד (ובסהמ״צ ופיה״מ), ובפרט בנדו״ד שבמו״נ שם מפורש „והראי׳ ע״ז היות הדין הזה כולל זולת שור וחמור אחד שור וחמור ואחד כל שני מינין אלא שדבר הכתוב בהוה” (ועד״ז הוא בהעתקת קאפח), דלא כדעתו בהלכה (ודוחק לומר שבמו״נ כתב הטעם והדין כפי שהוא מדרבנן, ומה״ת הוא מטעם צער בע״ח כנ״ל). — מ״מ באם דעתו להלכה ביד מיוסדת בטעם האיסור, מסתבר שמתאים למ״ש במו״נ (ששם ביאר טעמי המצות) — משא״כ לפי הביאורים דלקמן ס״ד וה׳ (שאין יסודם בטעמי המצוה). 29*) בהבא לקמן ראה גם לקו״ש חל״ד ע׳ 125־6."],["30","30","להעיר שבתויו״ט ב״ק שם פליג על דעת הרע״ב שם, דכלאים דהנהגה ילפינן שור שור משבת, וס״ל דלמסקנת הגמ׳ כלאים מכלאים ילפינן ולא צריכא קרא לחודא כו׳ דלמסקנא כלאים חד שמא ואין צריך אלא לאגמורי בחד והוא הדין לאידך דמשום הכי מתניתין נמי לא תנו אלא כלאים חדא וכללא לתרתי כו׳. והרי דעת הרע״ב שם היא כדעת הרמב״ם דמה״ת אינו חייב אלא בשני מינים שאחד טמא ואחד טהור (וראה רש״ש לתויו״ט שם). ובתויו״ט כלאים שם מ״ב, אף שהביא גם דעת הרמב״ם, מ״מ הביא ראי׳ לדעת הרא״ש. וראה קול הרמ״ז לתויו״ט ב״ק שם. *) אבל ראה חמדת ישראל על סהמ״צ להרמב״ם מל״ת ריח, דמדייק מל׳ הרמב״ם „אמנם מן התורה אינו חייב מלקות כו׳” דמשמע דס״ל להרמב״ם דכל שני מינין אסורים מן התורה רק מלקות אינו חייב מה״ת אלא בכלאים דטומאה וטהרה. ולהעיר, דלשון הרמב״ם בהל׳ כלאים שם הוא „אבל מדברי סופרים”, וידועה דעת הרמב״ם (סהמ״צ שורש ב׳. פיהמ״ש כלים פי״ז מי״ב) שכל דבר הנלמד באחת מי״ג מדות נק׳ דברי סופרים, אף שלכמה מפרשים גם לדעתו הם מן התורה אלא שלא נמנו במנין המצות (מפרשי סהמ״צ שם (מג״א ומרגניתא טבא), מ״מ וכ״מ הל׳ אישות פ״א ה״ב. ועוד). *) ולהעיר, דבפיה״מ ב״ק שם: אלא מאמרו"],["31","31","ת״א ותיב״ע עה״פ פרשתנו כב, ט. קדושים יט, יט. ועוד."],["32","32","ראה בחיי פרשתנו עה״פ. רמב״ן קדושים יט, יט. לכלאים שהוא רומז למה שאמר ית׳ לא תחרוש בשור ובחמור. אבל בפרש״י במשנה ב״ק שם ד״ה לכלאים כתב (בפשטות) „להרבעה”, ומסיים „וכן לענין כלאים דהנהגה”. ובגמרא שם מקדים „כלאים דחרישה” ל„כלאים דהרבעה”. וראה לעיל הערה 17. ואכ״מ."]]],[1300241166,"פון דעם וואס דער רמב״ם פסק׳נט אז א) „מותר להכניס שני מינין לסהר אחד ואם ראה אותם רובעים זה את זה אינו זקוק להפרישן”³³, ב) „מי שעבר והרכיב בהמתו הרי הנולד מהם מותר בהנ־אה”³⁴, ג) דער איסור מה״ת איז דוקא ווען ער טוט די מעשה בידיו³⁵ — איז משמע, אז בא כלאים דהרבעה איז דער גדר האיסור ניט פארבונדן דערמיט וואס דערפון ווערן נולד תולדות אין וועלכע ס׳איז ניכר וגלוי דער ענין ההרכבה, נאר די עצם מעשה ההרכבה (ההרבעה) איז אסור³⁶.\nועפי״ז איז כלאים דחרישה אין גדר פון כלאים דהרבעה, ס׳איז „משם אחד”, ווי ס׳איז משמע אויך דערפון וואס דער רמב״ם איז זיי כולל אין איין פרק (אין הלכות כלאים³⁷) — ווארום ביי ביידן איז דער זעלבער גדר האיסור — די פעולת החיבור.\nויש לומר טעם החילוק ביניהם:\nדער תוכן פון איסור כלאים איז, וואס מ׳איז מחבר צוויי זאכן וועלכע זיינען בניגוד זה לזה, דורך דער פעולת האדם ווערט עס א חפצא פון כלאים³⁸;\nאבער דער אופן העירוב שלהם, איז ניט גלייך אין אלע פאלן, ס׳איז תלוי אין אופן החיבור:\nביי הרבעה, וואו דער חיבור איז בתכלית ולשון הכתוב³⁹ והיו לבשר אחד, ווערט בא יעדערע צוויי מינים א חפצא של כלאים — תערובות, ווייל דער חיבור פון יעדן מין האט דער אויבערשטער איינגעשטעלט דוקא „למינהו”: אבער ביי כלאים דחרישה, וויבאלד אז זייער חיבור איז נאר אן ענין וואס איז מחוץ להם, זיינען זיי ניט כלאים, סיידן די מלאכה וכו׳ ווערט גע־טאן מיט צוויי סוגים⁴⁰ פון טהור וטמא, וועלכע זיינען הפכים אויך בענינים שמחוץ להם (בנוגע לאכילת האדם וכו׳)⁴¹ — דעמולט ווערט עס א תערו־בות⁴² — כלאים⁴³.\nו. דער ביאור הפלוגתא בפנימיות הענינים:\nמ׳געפינט אין חסידות⁴⁴ צוויי ביאורי האיסור פון „לא תחרוש בשור ובחמור יחדיו”:\nא) „ענין הלאו דלא תחרוש בשור",[["33","33","הל׳ כלאים פ״ט ה״ב."],["34","34","שם ה״ג."],["35","35","שם ה״א. ועד״ז בסהמ״צ מל״ת ריז."],["36","36","וכ״מ במו״נ שם בטעם איסור כלאי בהמה: „ומאסה התורה שישפיל איש מישראל מעלתו לזה המעשה כו׳”, עיי״ש."],["37","37","בפ״ט שם. ולהעיר מפיה״מ להרמב״ם כלאים שם (הובא בכס״מ לרמב״ם שם): אבל בהמה טמאה עם טהורה יש בה תוספת על איסור ההרבעה והוא שהם אסורים לחרוש כו׳."],["38","38","להעיר מצפע״נ מהד״ת עו, סע״ד ואילך."],["39","39","בראשית ב, כד."],["40","40","ועפ״ז אולי יש לבאר טעם הדעות (ראה שעה״מ לרמב״ם הל׳ כלאים שם ה״ז קרוב לסופו. ועוד. וכ״כ בפי׳ ר׳ חיים פלטיאל שם) דלדעת הרמב״ם בהמה וחי׳ אפילו שניהם טהורים לוקה מן התורה, כיון דהוי שני שמות (שני סוגים), עיי״ש."],["41","41","ולהעיר מלשון החינוך שם (הובא לעיל ס״ג) שטהור וטמא „טבעם רחוק מאד זה מזה”. וראה בארוכה במפרשי התורה בטעם מאכלות אסורות."],["42","42","להעיר מדעת ולשון הרמב״ם הי״א שם ב„בהמת פסוהמ״ק . . עשאה הכתוב כשני גופין מפני שהיתה קודש ונעשית כקדש וכחול מעורבין זה בזה ונמצאת בהמה זו כבהמה טמאה עם הטהורה המעורבין כאחד כו׳”. וראה בארוכה בנו״כ שם."],["43","43","להעיר מרשב״ם קדושים יט, יט."],["44","44","בהבא לקמן ראה אוה״ת נ״ך ע׳ קלב ואילך. פרשתנו ע׳ תתקסא. ד״ה לא תחרוש תרכ״ז. ד״ה לא תלבש שעטנז תרע״ח. לקוטי לוי״צ משפטים ע׳ פט. ובהנסמן בכהנ״ל."]]],[1300241167,"ובחמור יחדיו היינו להרחיק קליפת החמור שלא תקבל מבחי׳ הקדושה”⁴⁵.\nב) דער איסור איז ווייל „שור” איז בחי׳ גבורות און „חמור” איז בחי׳ חסדים — און „אסור לערבם יחד”⁴⁶.\nואלו ואלו דברי אלקים חיים⁴⁷, ויש לומר, אז די צוויי ביאורים זיינען בהתאם צו דער פלוגתא פון רמב״ם מיטן רא״ש:\nלויט שיטת הרמב״ם, אז דער לאו פון „לא תחרוש” איז דוקא ביי מין טהור עם מין טמא, איז דער טעם האיסור „קליפה” זאל ניט מקבל זיין פון קדושה [וואַרום א מין טהור איז שרשו פון ק״נ וואס קען נתעלה ווערן לקדושה, און א מין טמא איז שרשו פון גקה״ט⁴⁸; איז בשעת מען טוט א מלאכה מיט א מין טהור צוזאמען מיט א מין טמא — קען דער מין טמא „מקבל זיין” פון דעם מין טהור].\nלויט שיטת הרא״ש, אז דער איסור איז גילטיק ביי אלע מינים, אפילו טהור עם טהור און טמא עם טמא, איז דער טעם האיסור ווייל עס טאר ניט זיין דער עירוב פון מדות וואס דער אוי־בערשטער האט זיי באשאפן — הפכיות.\nז. ע״פ הנ״ל יומתק נאך אן ענין: מובן אז א מצוה, קדושה, תוספת אור — קען מאכן שלום צווישן הפכים, ע״ד מש״נ עושה שלום במרומיו מיכאל שר של מים וגבריאל שר של אש ואין מכבין זה את זה⁴⁹, אבער — ניט ח״ו (תוספת יניקה) קבלה בקליפה, וואס דערפאר איז ציצית, בגדי כהונה וכו׳ — מתיר נאר כלאי שעטנז — וואס צמר ופשתים זיי־נען היפך זמ״ז, אבער ביידע היתר,\nאון דאמאלס קען ווערן נאכמער — א יתרון, בדוגמת בגדי כהונה „לכבוד ולתפארת” דוקא דורך צמר ופשתים יחדיו⁵⁰.\n(משיחת ש״פ תצא תשמ״א)",[["45","45","סה״מ תרכ״ז ע׳ שעז. וראה זח״ג פו, ב. ת״ז תי״ד (ל, א)."],["46","46","לקולוי״צ שם. וראה אוה״ת שם."],["47","47","עירובין יג, ב."],["48","48","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ״ו</a> ופ״ז."],["49","49","כ״ה באגה״ק סי״ב. וראה תנחומא ויגש, ו. דב״ר פ״ה, יוד. ספר הבהיר (הובא בזח״א רסג, א). ועוד. וראה אגה״ק שם. אוה״ת נ״ך שם."],["50","50","ולהעיר דתפארת הוא דוקא בחיבור חו״ג וכו׳ (אגה״ק שם)."]]],[1300241168,"<h3>תצא ד</h3>\nא. מ'האט שוין פיל מאל גערעדט, אז רש\"י בפירושו על התורה פארענטפערט יעדע שאלה וואס קען זיך שטעלן אין לימוד פשוטו של מקרא, און דארט וואו רש\"י געפינט ניט קיין ביאור (לויטן דרך הפשט) אין א פסוק (אדער א ווארט) — זאגט ער „לא ידעתי\" וכיו\"ב¹.\nאון דערפאר, ווען מען קומט צו א פסוק וואו עס איז לכאורה דא א שוועריקייט און רש\"י שטעלט זיך ניט אויף דעם, איז דערפון גופא א הוכחה, אז ע\"ד הפשט איז עס מלכתחילה קיין שאלה ניט; אדער, אז די שאלה ווערט פארענטפערט לויט א פירוש רש\"י לפני זה.\nדארף מען לפ\"ז האבן א ביאור בפרשתנו, וואו די תורה זאגט² „כי יהי' ריב בין אנשים ונגשו אל המשפט ושפטום והצדיקו את הצדיק והרשיעו את הרשע. והי' אם בן הכות הרשע והפילו גו'\" — וואס די ווערטער „והצדיקו את הצדיק והרשיעו את הרשע\" זיינען לכאורה איבעריק³ (ס'איז דאך א מילתא דפשיטא אז „והצדיקו את הצדיק והרשיעו את הרשע\") — עס האט געדארפט שטיין „כי יהי' ריב גו' ושפטום והי' אם בן הכות הרשע גו'\"! — פארוואס באוארנט ניט רש\"י דעם יתור לשון?\nבנוגע די ווערטער „והרשיעו את הרשע\" וואלט מען געקענט איינלערנען (בדוחק עכ\"פ), אז זיי זיינען א הקדמה און אריינפיר צו „והי' אם בן הכות הרשע\". ד.ה. דער פסוק זאגט: „כי יהי' ריב גו' והרשיעו את הרשע (איז אויב ער איז א רשע וועמען עס קומט מלקות⁴ —) והי' אם בן הכות הרשע — (איז) והפילו גו'\":\nאבער [נוסף לזה, וואס דאס איז א דוחק גדול: סוף סוף איז איבעריק צו זאגן „והרשיעו את הרשע\", ווייל פון „והי' אם בן הכות הרשע\" וויס מען במילא אז דא איז געווען „והרשיעו את הרשע\"; ואדרבה: די ווערטער „והרשיעו את הרשע\" גיבן א מקום לטעות (ווי רש\"י⁵ זאגט) אז „(יכול) כל המתחייבין בדין לוקין (ת\"ל כו')\"]\nעס בלייבט דאך ניט מובן: די ווערטער „והצדיקו גו'\" — (לפשוטו של מקרא) צוליב וואס זיי שטייען?\nאון מען קען ניט זאגן (בפשוטו של מקרא) אז דא איז (נאך⁶) א ציווי ומ\"ע אז מען זאל דן זיין א דין אמת⁷ (ע\"ד ווי",[["1","1","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">ע\"ד</a> פרש\"י תולדות כח, ה. ובכ\"מ (נסמנו בלקו\"ש ח\"ה ע' 1 בשוה\"ג)."],["2","2","כה, א־ב."],["3","3","ראה פרש\"י בפרשתנו לפני זה כב, ח. — וצע\"ק לעיל (כד, יט) „קצירך\" מאי קמ\"ל. בספרי עה\"פ מפרשו „פרט לשקצרוהו גוים\". אבל רש\"י לא הביאו כי בפשש\"מ ידעינן זה מ„בשדך\" (אבל ראה סוטה מה, א בשדך „לרבות שכחת קמה\"). ובדוחק (?) י\"ל דתרווייהו בעינן (קציר שלך ושדה שלך) ובדלקמן (כד, כ־כא) כי תחבוט זיתך (וראה ספרי שם) כי תבצור כרמך — אין הדין כן (אף שהוא היפך הסברא), או דילפינן מכאן — ואכ\"מ — ורש\"י אינו כותב כהנ\"ל בפירוש, כי ה\"ז פשטות הלשון."],["4","4","ראה פרש\"י כאן ד\"ה והרשיעו."],["5","5","שבהערה הקודמת."],["6","6","נוסף על הציווי (מ\"ע) — דברים א, טז. ר\"פ שופטים."],["7","7","כפירוש הרלב\"ג עה\"פ."]]],[1300241169,"מען געפינט כמה לאווין בענין פון לא תטה משפט⁸) — ווייל פון דער אריכות הלשון אין פסוק („כי יהי' ריב גו' ונגשו גו' ושפטום\") איז משמע, אז די תורה איז דא אויסן א נייעם ענין.\nב. אין ספרי⁹ איז פאראן א מ\"ד וואס לערנט אפ פון די ווערטער „והצדיקו את הצדיק\" — „צדקהו כדי שלא ילקה\", און ווי מפרשים¹⁰ זיינען דאס מפרש אז מען דארף פותח זיין בזכות — אז צום אלעם ערשטן דארף מען זוכן אויפן בעל דין א זכות „כדי שלא ילקה\" און ערשט דערנאך — א זאך פון רשעות — ע\"ד ווי בא דיני נפשות וואס דער דין איז אז „פותחין בזכות\"¹¹.\nאבער מען קען ניט זאגן אז רש\"י נעמט אן דעם פירוש, ווייל אויב אזוי האט עס רש\"י געדארפט זאגן בפירוש, וויבאלד ס'איז ניט בגדר אז א „בן חמש למקרא\" וועט זיך אליין כאפן אויף דעם פירוש (ובמכש\"כ דערפון וואס דער ספרי איז עס מפרש).\nובפרט אז דער פירוש איז ניט אזוי גלאטיק אין לשון הכתוב: די צוויי ענינים אין פסוק — „והצדיקו את הצדיק והרשיעו את הרשע\" — ריידן בפשטות וועגן באזונדערע מענטשן (די צוויי בעלי ריב, וואס איינער איז א צדיק און דער צווייטער — א רשע); משא\"כ לפירוש הנ\"ל רעדט דער גאנצער פסוק וועגן דעם זעלבן מענטש: פריער דארף מען אויף אים זוכן א זכות — והצדיקו (את הצדיק), און אויב מען קען ניט געפינען, איז דאן — והרשיעו (את הרשע).\n[ועאכו\"כ אז מען קען ניט זאגן אז רש\"י נעמט אן בפשוטו של מקרא ווי די דרשה אין גמרא¹², אז דער פסוק רעדט וועגן א פאל וואס „עדים זוממין\" „הרשיעו את הצדיק\" און דערנאך „אתו עדים אחרינו והצדיקו את הצדיק דמעיקרא ושוינהו להני רשעים\" (איז זייער דין — „(והי' אם) בן הכות הרשע\", אז זיי זיינען חייב מלקות); וביותר איז מופרך צו זאגן אז דאס איז אזוי פשוט אז רש\"י דארף עס גארניט זאגן בפירוש!]\nג. ויש לומר, אז דאס וואס רש\"י דארף ניט באוארענען די שאלה (צוליב וואס שטייט „והצדיקו את הצדיק והרשיעו את הרשע\"), איז ווייל דאס איז מובן פון פרש\"י אויף התחלת הכתוב „כי יהי' ריב\" — „סופם להיות נגשים אל המשפט, אמור מעתה אין שלום יוצא מתוך מריבה, מי גרם ללוט לפרוש מן הצדיק הוי אומר זו מריבה\".\nשטעלט זיך אין דעם די שאלה (ווי מפרשים פרעגן¹³): וואס איז דא דער חסרון אז „סופם להיות נגשים אל המשפט\"? ואדרבה: דורך זייער „נגשים אל המשפט\" וועט ביי זיי ווערן שלום¹⁴, וכמש\"נ¹⁵ „ושפטו את העם גו' וגם כל העם הזה על מקומו יבוא בשלום\"¹⁶.",[["8","8","משפטים כג, ו (וראה שם, ב ובפרש\"י שם בפי' „כפשוטו\". שם, ג ובפרש\"י). שופטים טז, יט. פרשתנו כד, יז (וראה רש\"י שם). וראה דברים א, יז."],["9","9","פרשתנו עה\"פ."],["10","10","ספרי דבי רב ופי' הב' בתולדות אדם לספרי."],["11","11","סנהדרין רפ\"ד (לב, א — במשנה. שם, ב ואילך). פרש\"י נשא ה, יט. וראה מסעי (לה, כד־כה) ושפטו העדה גו' והצילו העדה גו'."],["12","12","מכות ב, ב. וש\"נ (וכפרש\"י מכות שם שבא לתרץ „ל\"ל והצדיקו כו'\") — הובא גם ברמב\"ן כאן."],["13","13","גו\"א. ועד\"ז במשכיל לדוד (וספרי דבי רב לספרי). וראה הערה 16 ובשוה\"ג שם."],["14","14","משכיל לדוד (וספרי דבי רב)."],["15","15","יתרו יח, כב־כג. — כן הובא במשכיל לדוד (וספרי דבי רב), אבל בפרש\"י יתרו שם ד\"ה „כל העם\" קאי על „אהרן כו' הנלוים עתה עמך\". אלא שמ\"מ זה שמשפט מביא שלום הו\"ע המובן בסברא ובפשטות."],["16","16","ראה גם גו\"א כאן: לא יוכלו להתפשר יחד מעצמם כ\"א ע\"י דין . . הריב . . לא תוכל להשקיט"]]],[1300241170,"די תמי' איז נאך גרעסער: דער מקור פון דעם פרש\"י איז פון ספרי, אבער דארט איז דער לשון: „אין שלום יוצא מתוך מריבה . . מי גרם לזה ללקות הוי אומר זו מריבה\" (ד.ה. אז די מריבה איז גורם אז איינער זאל לוקה זיין); רש\"י איז אבער משנה פון ספרי, און אנשטאט „גרם לזה ללקות\" זאגט ער „סופם להיות נגשים אל המשפט\"!\nאיז דער ביאור בזה:\nרש\"י בפירושו קומט פארענטפערן (אויך¹⁷) וואס דער פסוק נוצט דא דעם לשון ריב. מען געפינט בכמה מקומות, אז א סכסוך צווישן צוויי מענטשן (וואס ווערט געבראכט פאר א שופט) ווערט באצייכנט אין תורה מיטן ווארט „דבר\"¹⁸, ע\"ד: „כי¹⁹ יהי' להם דבר בא אלי ושפטתי בין איש ובין רעהו\", „מי²⁰ בעל דברים יגש אליהם\". משא\"כ דער לשון „ריב\" ווערט גענוצט (ע\"פ רוב²¹) בשייכות מיט א קריגעריי וועלכע די בעלי ריב ברענגען ניט למשפט, כמו: ויהי²² ריב בין רועי מקנה אברם גו', ויריבו²³ רועי גרר גו', וכי²⁴ יריבון אנשים והכה איש גו'²⁵.\nלפ\"ז וואלט מער געפאסט אז דא זאל שטיין „כי יהי' דבר\" [און ווי מ'זעט, אז אונקלוס²⁶ איז מתרגם דעם ווארט „ריב\" פון אונזער פסוק²⁷ — ניט „מצותא\" (ווי ברוב המקומות²⁸) — נאר „דין\"²⁹]. פארוואס־זשע נוצט דער פסוק דא־דוקא דעם ווארט „ריב\" און ניט „דבר\"?\nאיז רש\"י מפרש: „כי יהי' ריב — סופם להיות נגשים אל המשפט אמור",[["","","אותו כי אם ע\"י משפט — היינו, דע\"י משפט יתפשרו וישלימו. במשכיל לדוד (וספרי דבי רב) תי' ד„ר\"ל סופם להיות נגשים אל המשפט שיתבע זה ויביא עדים שהכהו ויתחייב הלה מלקות כו' (וראה גם רמב\"ן כאן „ויתכן כו'\") סופם לבא לידי קטטה ולחבול זב\"ז\" (ע\"ד פרש\"י לקמן כה, יא). אבל צע\"ג, שהרי לא נרמז זה כלל בלשון רש\"י „נגשים אל המשפט\", ובפרט שמשנה מלשון הספרי „מי גרם לזה ללקות\" (כדלקמן בפנים) וגם מפירושו לקמן שם. וראה לקמן הערה 30."],["17","17","נוסף על השאלה „כי יהי' ריב ל\"ל, לכתוב כי יגשו אנשים למשפט\" (גו\"א. ועד\"ז בר\"א\"ם. באר מים חיים (לאחי המהר\"ל). ועוד)."],["18","18","בהבא לקמן — ע\"ד החילוק בין „דבר\" ל„ריב\" — ראה בארוכה מלבי\"ם כאן."],["19","19","יתרו יח, טז. וראה שם, יט (וברש\"י שם). שם, כב. כו."],["20","20","משפטים כד, יד (וראה רש\"י שם)."],["21","21","כי במקומות אחדים — גם לפני פרשתנו — נאמר כן גם בנוגע לבעלי דינים: משפטים כג, ב־ג. שם, ו. וכן בפ' שופטים יז, ח. יט, יז. כא, ה."],["22","22","לך יג, ז. — ובזה קאי רש\"י בפרשתנו כאן."],["23","23","תולדות כו, כ."],["24","24","משפטים כא, יח."],["25","25","ראה גם לך שם, ח. תולדות שם, כא־כב. ויצא לא, לו. בשלח יז, ב. שם, ז. ועוד."],["26","26","משא\"כ בתיב\"ע כאן שמתרגם „תיגרא\"."],["27","27","וכן במקומות שבהערה 21 (אלא שבשופטים (יז, ח) מתרגם ריבות — פלוגתי דינא)."],["28","28","ראה ת\"א במקומות שבהערות 22־25."],["29","29","כתרגומו תיבת „דבר\" ביתרו יח, טז. משפטים כד, יד. *) בגו\"א שם מבאר, שזוהי כוונת רש\"י להדגיש גודל חסרון הריב, ד„סוף שיהי' גדול\" שרק ע\"י משפט אפשר להשקיטו. אבל מלשון רש\"י „סופם להיות נגשים אל המשפט\" משמע ש„נגשים אל המשפט\" גופא הו\"ע של חסרון (ועוד גרוע מהריב) וכהלשון „סופם . .\" בכ\"מ (בענין של חסרון), ולדוגמא בפרש\"י פרשתנו: כא, יא. כב, יד. כה, יא. נוסף שלפ\"ז הראי' מלוט אינה דוגמא מתאימה לנדו\"ד ש„נגשים אל המשפט\" (ומתבטל הריב). *) בכמה דפוסים „פלגתא\". וכן הובא בפי' נתינה לגר ביאור על תרגום אונקלוס (מהר\"ן אדלר). וכן הוא בחומש נתינה לגר. אבל בספר כתר תורה הנק' תאג' (ירושלים תרנ\"ה), ועוד הוא „פלוגת\" כבפנים."]]],[1300241171,"מעתה אין שלום יוצא מתוך מריבה\" — דא רעדט זיך וועגן א סכסוך אין אן אופן פון ריב, און פון דעם איז „אין שלום יוצא\", אפילו ניט דורך „משפט\"³⁰:\nבכלל, ווען צוויי מענטשן האבן צווישן זיך א סכסוך וואס איז ניט בגדר מריבה, קען דער סכסוך אויסגעגליכן ווערן און ברענגט שלום — אדער זיי קומען דורך צווישן זיך אליין, אדער ב\"ד געפינט א פשרה; און אפילו אין א פאל ווען ב\"ד איז מחליט אז איין צד איז אינגאנצן גערעכט, איז וויבאלד זיי האבן ניט קיין „ריב\" צווישן זיך און זיי זוכן דעם אמת, וועט זיי אויך דער פסק דין צוברענגען צו שלום.\nבשעת אבער עס איז דא א ריב — אז דער סכסוך ווערט פארוואנדלט אין א קריגעריי, קען דאן קיין שלום ניט ווערן. זיי וועלן קומען למשפט און דער ב\"ד וועט ארויסגעבן א פסק דין חתוך, ווער איז גערעכט און ווער איז אומגערעכט, אבער אויך נאכן פסק דין איז „אין שלום יוצא\"³¹.\nאון אויף דעם ברענגט רש\"י א ראי' ודוגמא פון לוט — „מי גרם ללוט לפרוש מן הצדיק הוי אומר זו מריבה\": דלכאורה — דער ריב דארט איז דאך געווען (ניט צווישן לוט ו(אברהם) הצדיק, נאר) בלויז צווישן רועי אברהם ורועי לוט. אברהם ולוט מצד עצמם זיינען געווען „אנשים אחים\"³². וויבאלד\nאבער אז דערביי האט זיך געשאפן א „ריב\", האבן זיי ניט געקענט בלייבן בשלום אין איין ארט, און לוט האט געמוזט פורש זיין „מן הצדיק\".\nד. עפ\"ז ווערט פארענטפערט בדרך ממילא פארוואס דער פסוק זאגט „והצדיקו את הצדיק והרשיעו את הרשע\" — ווייל לויט פרש\"י, איז דאס די כוונה פון פסוק³³, אז „כי יהי' ריב\", איז „אין שלום יוצא\" — עס וועט קיין שלום ניט ווערן, אפילו דורכן משפט, ווייל דא איז דער משפט אין אן אופן פון „והצדיקו את הצדיק והרשיעו את הרשע\":\nדא רעדט זיך ניט וועגן בעלי דינים וואס זוכן דעם אמת ובמילא — א משפט וועלכער ברענגט שלום צווישן זיי, נאר — איינער איז א צדיק און דער צווייטער א רשע, און דער צוועק פונעם פסק דין איז בלויז צו אויסגעפינען און מצדיק זיין דעם צדיק והרשיעו את הרשע.\nה. ויש להוסיף עוד, אז דער פסוק באוארנט דא נאך אן ענין:\nמען קען מיינען אז וויבאלד דאס איז א „ריב\", אז זיי פירן א מחלוקת, אז איינער פון זיי, אדער זיי ביידע זיינען בעלי מחלוקת (רשעים³⁴) — דארף מען זיי ניט משפט'ען אין זייער דין ודברים, נאר מעניש זיין זיי פאר מחלוקת און",[["30","30","ולכן משנה רש\"י מלשון הספרי „גרם לזה ללקות\" — כי כאן הכוונה להמחלוקת ולא מה שאחד ילקה [משא\"כ בפרש\"י לקמן כה, יא שכוונתו כבספרי שם. ועפ\"ז מתורץ בפשטות תרתי ל\"ל — כי הם ב' ענינים שונים, וא\"צ לדחוק כתי' המשכיל לדוד לקמן שם]."],["31","31","להעיר גם מפי' תולדות אדם לספרי כאן."],["32","32","לך שם, ח. וראה רש\"י שם."],["33","33","ע\"פ המבואר בפנים מתורצת ג\"כ קושיית הרמב\"ן כאן — מה ענין המלקות בריב בין שני אנשים — כי ע\"ד הפשט פסוק זה הו\"ע לעצמו, ואינו הקדמה לפסוק שלאח\"ז „והי' אם בן הכות הרשע גו'\" (ומה שפרש\"י בד\"ה „והרשיעו „יכול כל המתחייבין בדין לוקין כו'\" — הוא לימוד נוסף מצד סמיכות הפסוקים. ואכ\"מ)."],["34","34","להעיר מאבות פ\"א מי\"ח: בעלי הדין כו' כרשעים."]]],[1300241172,"דערנאך וועט מען זען: ביטול המחלוקת קען ברענגען צו שלום, מודה זיין על האמת א.ז.וו. — זאגט תורה: „כי יהי' ריב גו' ושפטום\": ניט קוקנדיק אויף זייער „ריב\" ליגט א חיוב אויף ב\"ד צו משפט'ן זיי, זיך אריינלייגן אין דעם סכסוך, פאנאנדערקלייבן זיך אין די פרטי הדבר און ארויסגעבן א פסק־דין.\nאויך נאכדעם — איז דא אן ארט צו דענקען, אז ווייבאלד זיי פירן זיך צווישן זיך א ריב, איז ניט מעגליך אז איינער זאל זיין אינגאנצן גערעכט, אריינגייענדיק אין מחלוקת וועלן סו\"ס ביידע מגזם זיין אין זייערע טענות וכו'³⁵; ובמילא קומט מען לידי מסקנא, אז ווען דער שופט איז איינעם פון זיי מצדיק (כפשוטו ש\"מ — אינגאנצן), איז דאס א פס\"ד בטעות —\nאיז די תורה ממשיך: „והצדיקו את הצדיק והרשיעו את הרשע\": עס קען טאקע זיין אז אין דעם פרט פון „ריב\" זיינען ביידע שולדיק, אבער בנוגע דעם עצם דין איז „והצדיקו את הצדיק והרשיעו את הרשע\": אין דעם זיינען די שופטים גערעכט אז איינער איז אינגאנצן גערעכט, און דער צווייטער — אינגאנצן אומגערעכט.\nוי\"ל — אז (ע\"ד לימוד הגמרא) דערביי באוארנט מען נאכמער — „והצדיקו את הצדיק, דמעיקרא\"³⁶: בשעת א ב\"ד צדק איז איינעם מצדיק לגמרי, וועט מען זען אז בנוגע דעם „ריב\" ומחלוקת, איז ער אויך א צדיק, איז אינגאנצן ניט שולדיק אין דעם³⁷; דער „ריב\" איז געוואָרן מצד דעם רשע, און געבליבן דעם רשע'ס³⁸ אבער ער איז א צדיק — „והצדיקו את הצדיק דמעיקרא\".\n(משיחת ש\"פ תצא תשמ\"א)",[["35","35","ע\"ד שמות (ב, יג): שני גו' נצים ויאמר לרשע למה תכה רעך ופרש\"י רשע כמותך — דעפ\"ז (בפנים) מובן בפשש\"מ — מנ\"ל דהוא רשע."],["36","36","ל' הגמרא — מכות שם."],["37","37","עיין פרש\"י יתרו יח, כא ד\"ה שונאי בצע. ואכ\"מ."],["38","38","להעיר מאבות (פ\"ה, מי\"ז): מחלוקת קורח וכל עדתו."]]],[1300241173,"<h3>תבא</h3>\nא. אויף דעם פסוק<sup data-n=\"1\">1</sup> „וה' האמירך היום להיות לו לעם סגולה כאשר דבר לך\" שטעלט זיך רש\"י אויף די ווערטער „כאשר דבר לך\" און איז מפרש: „והייתם לי סגולה\"<sup data-n=\"2\">2</sup>. דערנאך שטעלט זיך רש\"י אין צווייטן פסוק אויף די ווערטער „ולהיותך עם קדוש כאשר דבר\" און איז מפרש: „והייתם3 לי קדושים\"<sup data-n=\"4\">4</sup>.\nדארף מען פארשטיין: אויב רש\"י דארף ניט מעתיק זיין פון פסוק וואס דער „דבר\" איז (ווייל דאס שטייט דאך אין פסוק מפורש: „להיות לו לעם סגולה\")5, נאר — וואו מען געפינט דעם „דבר\" פריער — פארוואס איז ער עס מעתיק ביים צווייטן מאל6? און אויב ס'איז יע נויטיק צו מעתיק זיין אויך וואס דער „דבר\" איז — האט ער דאס גע־דארפט מעתיק זיין אויך ביים ערשטן מאל7?\nב. אויך דארף מען פארשטיין וואס רש\"י טייטשט (אין צווייטן דיבור) אז „כאשר דבר\" מיינט „והייתם לי קדושים\" פון פ' קדושים:\nנאך „והייתם לי סגולה\" וואס רש\"י בריינגט (פון פ' יתרו), איז ער ממשיך דארט8: „ואתם תהיו לי ממלכת כהנים וגוי קדוש\" — איז פארוואס לערנט רש\"י אז דער „כאשר דבר\" (אין צווייטן פסוק) מיינט אן אנדער דיבור פון דעם אויבערשטן („והייתם לי קדושים\"), ניט דעם וואס שטייט צוזאמען מיט „והייתם לי סגולה\" — וואס אזוי לערנען טאקע כמה מפרשי התורה9?\nנאך מער: לויט די מפרשים איז גלאט דער המשך דא אין פסוק10: אויף די ווערטער „ואתם תהיו לי ממלכת כהנים\" וואס שטייט אין פ' יתרו, טייטשט רש\"י „שרים\" — עפ\"ז קומט במילא אויס, אז די אלע פרטים דא אין די פסוקים",[["1","1","כו, יח."],["2","2","יתרו יט, ה."],["3","3","קדושים כ, כו."],["4","4","כמה מפרשים מגיהים במכילתא (בא יב, כה) וביל\"ש (שם רמז רז בתחלתו) ע\"פ פרש\"י כאן — ראה מכילתא הוצאת האראוויטץ (וש\"נ). ואכ\"מ."],["5","5","בדפוס ראשון וכת\"י רש\"י (שתח\"י) ליתא בפרש\"י כו, יז הסיום „ומצאתי להם עד כו'\", והתיבות דפרש\"י יז „להיות לו לעם סגולה\" — נסמכים לריש ד\"ה זה „כאשר דבר לך\" ומתורץ הנ\"ל."],["6","6","וכ\"ה גם בדפוס ראשון ושני, וכת\"י רש\"י (שתח\"י)."],["7","7","ואין לומר, עכ\"פ בדוחק גדול — שהעתיק רש\"י גם „ולהיותך עם קדוש\" להקל על הלומד שידע איזה „כאשר דבר\" מפרש, ולא נטעה שמפרש עוה\"פ „כאשר דבר\" שבפסוק שלפנ\"ז — שהרי מפירושו „והייתם לי קדושים\", פשוט שקאי על „כאשר דבר\" שבפסוק יט (נוסף ע\"ז שלזה די שיעתיק רק תיבות ה' אלקיך שלפנ\"ז). ועד\"ז מובן גם שדוחק לומר שהעתיק רש\"י „ולהיותך עם קדוש\" כיון שבפסוק זה ישנם ב' ענינים „ולתתך עליון גו' ולהיותך עם קדוש\", ומעתיק „ולהיותך עם קדוש\", להדגיש דתיבות „כאשר דבר\" קאי רק על „ולהיותך עם קדוש\" (משא\"כ בפסוק יח שלפני כאשר דבר לך נאמר רק ענין אחד „להיות לו לעם סגולה\"), שהרי זה מובן מפירושו „והייתם לי קדושים\" (נוסף ע\"ז שלזה די שיכתוב: „ולהיותך גו' כאשר דבר\")."],["8","8","שם יט, ו."],["9","9","אלשיך, ש\"ך (עה\"ת) וספורנו כאן. אוה\"ח בסופו (פסוק יח). ועוד. וכ\"ה במדרש הגדול כאן: היכן דבר, ואתם תהיו לי ממלכת כהנים וגוי קדוש."],["10","10","ראה גם אלשיך. ספורנו. ועוד. *) בדפוס שני הגירסא בפרש\"י: . . להיות לו לעם סגולה כאשר דבר לך והייתם לי סגולה ומצאתי להם עד כו'."]]],[1300241174,"„להיות לו לעם סגולה ולתתך עליון על כל הגוים, ולהיותך עם קדוש\" זיינען בהתאם צו די דריי פרטים אין דעם „דבר\" פון אויבערשטן דארטן בפ' יתרו: להיות לו לעם סגולה — והייתם לי סגולה מכל העמים; ולתתך עליון על כל הגוים — ואתם תהיו לי ממלכת כהנים (שרים); און „ולהיותך עם קדוש\" — „וגוי קדוש\".\nג. לכאורה יש לומר, אז דער טעם וואס רש\"י ברענגט ניט דעם פסוק „וגוי קדוש\" אויף „ולהיותך עם קדוש גו' כאשר דבר\", איז ווייל דעמאלט איז דאך דאס דער זעלבער „כאשר דבר\", און דער פסוק וואלט דא ביי „ולהיותך עם קדוש\" ניט געדארפט איבער'חזר'ן נאכאמאל „כאשר דבר\".\nס'איז אבער א דוחק, ווייבאלד ס'איז דא א הפסק „ולשמור כל מצותיו\".\nועוד — לויט דעם איז דער פסוק דורש ביאור (און רש\"י האט עס געדארפט באווארענען): פארוואס מיינט דער פסוק א צווייטן דיבור, און דער־פאר חזר'ט ער איבער נאכאמאל „כאשר דבר\", און ניט דעם „גוי קדוש\" בפ' יתרו, וואס קומט בהמשך צו „והייתם לי סגולה\"?\nאויך דארפן פארשטיין:\nדער פסוק וואס רש\"י ברענגט שטייט בסיום פ' קדושים — און מען געפינט שוין פריער דעם לשון: „קדושים תהיו\" (בר\"פ קדושים) און נאך פריער „והתקדשתם והייתם קדושים\" (בס\"פ שמיני<sup data-n=\"11\">11</sup>. פארוואס ברענגט רש\"י דעם שפעטערדיקן פסוק12?\nס'איז שווער צו פארענטפערן אז ווי־באלד אין דעם פסוק (בפרשתנו) שטייט „ולהיותך עם קדוש לה' אלקיך\", דער־בער ברענגט ער א פסוק וואו עס איז אויך מפורש „והייתם לי קדושים\", משא\"כ די אנדערע פסוקים הנ\"ל וואו דער לשון איז „קדושים\" סתם, און ס'איז ניט מודגש אז די קדושה איז „לי\" —\nווייל לפ\"ז וואלט רש\"י געדארפט מעתיק זיין פון פסוק דא אויך די ווערטער „לה' אלקיך\".\nווייבאלד רש\"י איז מעתיק בלויז „ולהיותך עם קדוש כאשר דבר\" (און לאזט אויס די ווערטער („לה' אלקיך\") וועלכע שטייען צווישן זיי — און ער איז אפילו זיי ניט מרמז מיט „וגו'\"<sup data-n=\"13\">13</sup> — איז מוכח, אז דער „כאשר דבר\" באציט זיך צום „ולהיותך עם קדוש\" און איז דער־ביי ניט אויסן צו מדגיש זיין דעם פרט פון „לה' אלקיך\".\nד. וי\"ל הביאור בזה:\nבהשקפה ראשונה איז דא אין פסוק ניט גלאט: „ולהיותך עם קדוש גו'\" איז בתוכנו די זעלבע זאך ווי „להיות לו לעם סגולה\", זיי זיינען מתאר ווי דער „עם ישראל\" איז אויסגעטיילט פון אלע פעלקער: „עם סגולה\" — „עם קדוש\" —\nהאבן זיי געדארפט שטיין צוזאמען גלייך איינער נאכן צווייטן14:\nפון דעם וואס „ולהיותך עם קדוש\" שטייט אין א צווייטן פסוק, ובסיומו —",[["11","11","יא, מד."],["12","12","בכמה כת\"י רש\"י (שתח\"י) „והייתם קדושים\". אבל בדפוסים ושאר כת\"י (שתח\"י) הלשון „והייתם לי קדושים\"."],["13","13","בכמה דפוסים (חדשים) נתוספה תיבת „וגו'\" לאחרי „ולהיותך עם קדוש\". אבל ליתא בדפוסים הראשונים וכת\"י רש\"י (שתח\"י)."],["14","14","להעיר מואתחנן (ז, ו) ראה (יד, ב) שבאים זה אחר זה: כי עם קדוש אתה . . לעם סגולה מכל העמים."]]],[1300241175,"נאכדעם ווי ער איז מפסיק מיט „ולשמור כל מצותיו\", וואס רעדט וועגן דער פעולה פון אידן מפני הציווי<sup data-n=\"15\">15</sup> (און ניט אן ענין של תואר ומעלה ביחס צו כל הגוים)16, איז מובן אז „עם סגולה\" און „עם קדוש\" דא — זיינען צוויי גאר באזונדערע ענינים:\nובמילא קען מען ניט לערנען אז „ולהיותך עם קדוש גו' כאשר דבר\" מיינט דעם „גוי קדוש\" וואס שטייט בפ' יתרו, ווארום דארטן איז דאס אן ענין וואס קומט בהמשך ותוכן אחד מיט „והייתם לי סגולה מכל העמים\".\nה. אין וואס באשטייט דער חילוק צווישן „ולהיותך עם קדוש\" און „והייתם לי סגולה מכל העמים\" — נעמט עס רש\"י ארויס פון דעם וואס אין ערשטן פסוק שטייט „כאשר דבר לך\", און בא „ולהיותך עם קדוש\" שטייט „כאשר דבר\" (בלי דעם ווארט „לך\").\nדי הסברה בזה: רש\"י האט שוין מפרש געווען פריער אין פ' ויצא17: „דברתי לך — לצרכך ועליך מה שהבטחתי לאברהם על זרעו, לך הבטחתי וכו' וכן כל לי ולך ולו ולהם הסמוכים אצל דבור משמשים לשון על\"18.\nדערפון איז מובן בנדו\"ד, אז דער פירוש „כאשר דבר לך\" מיינט ניט „אזוי ווי ער האט גערעדט צו דיר\", צו אידן [ובפרט אז לפ\"ז קען מען פרעגן: מאי קמ\"ל? כל התורה איז געזאגט געווארן צו אידן!], נאר „לצרכך ועליך\", „ווי ער האט גערעדט וועגן דיר\" — א צוזאג, א הבטחה פאר דיר, „אויף דיר\".\nאון דאס איז דער המשך הכתוב: „וה' האמירך היום להיות לו לעם סגולה\", וואס מיינט אז „הוא הפרישך אליו מעמי הארץ להיות לו לעם סגולה\"19, איז דער אויפטו געווען „כאשר דבר לך\" — ווי דער אויבערשטער האט דאס מבטיח געווען, געזאגט וועגן אידן20.\nאון דעריבער איז רש\"י מפרש אז „כאשר דבר לך\" מיינט דער דיבור „והייתם לי סגולה\", וואס דארטן איז גע־ווען דער „דבר\" וועגן אידן21.\nאין צווייטן פסוק „ולהיותך עם קדוש גו' כאשר דבר\" וואס שטייט ניט „לך\", איז מובן, אז „כאשר דבר\" מיינט ניט דעם דיבור פון דעם אויבערשטן וועגן אידן, א הבטחה וועגן דעם וואס וועט זיין מיט דיר, נאר כפשוטו, ווי ער האט",[["15","15","ראה רמב\"ן עה\"פ. ספורנו. אוה\"ח. ועוד."],["16","16","וגם, „ולתתך עליון על כל הגוים אשר עשה\" אין זה תואר ומעלה של ישראל גופא כעם סגולה ועם קדוש."],["17","17","כח, טו."],["18","18","ולפנ\"ז בפ' ח\"ש (כד, ז): ואשר דבר לי, לצרכי כמו אשר דבר עלי וכן כל לי ולו ולהם הסמוכים אצל דבור מפורשים בלשון על. ע\"ש. וכ\"כ בשמות (ד, טז): ודבר הוא לך, בשבילך ידבר אל העם, וזה יוכיח על כל לך ולי ולו ולכם ולהם הסמוכים לדבור שכולם לשון על הם. וכן בפר' רש\"י קרח יז, ה."],["19","19","לשון רש\"י עה\"פ כו, יז."],["20","20","ומ\"ש הרא\"ם (ח\"ש שם) שבכ\"מ (שמהן מקשה הרמב\"ן שם על פרש\"י) שנאמר לי לך ב„דבר\" שצ\"ל פי' לך (לא עליך), „פירושם מלשון אמירה\" — הרי היפך פשטות לשון רש\"י בכל מקומות הנ\"ל, „וכן כל לי ולך כו' הסמוכים אצל דבור כו'\" (וראה באר יצחק ח\"ש שם. ועוד)."],["21","21","והא דלא כתב רש\"י הלשון „והיכן דבר\"* כמ\"ש בכ\"מ (ואתחנן ו, יט. עקב יא, כה. ראה טו, ו. ועוד) — וכלשון המכילתא ויל\"ש בא שם — י\"ל שכתב כן רק כאשר המקום בו דבר (לראשונה) אינו בדיוק כהלשון שאומר „כאשר דבר\", או כשהדבור הי' אח\"כ (כבפ' ראה שם). ועוד י\"ל. *) כ\"ה ברוב הדפוסים וכת\"י רש\"י (שתח\"י). ובדפוס ראשון דרש\"י א' „והיכן דבר\"."]]],[1300241176,"(גערעדט און) אנגעזאגט (ובמילא — צו אידן)22, וואס דאס מיינט א ציווי אויף א פעולה פון אידן.\nולכן איז פארשטאנדיק, אז דאס מיינט ניט דעם דיבור „ואתם תהיו לי ממלכת כהנים וגוי קדוש\", וואס איז אזוי ווי דער דיבור „והייתם לי סגולה\" — „לצרכך ועליך\", א דיבור פון אויבערשטן וועגן (זיין פעולה מיט אידן)*22; נאר א דיבור פון דעם אויבערשטנ'ס א ציווי אויף „ולהיותך עם קדוש\".\nדעריבער זאגט רש\"י אז דאס מיינט דעם פסוק „והייתם לי קדושים\", וואס דאס איז דעם אויבערשטנ'ס א ציווי אז אידן זאלן זיין קדושים23.\nומהאי טעמא איז רש\"י מעתיק דא אויך התחלת הלשון „ולהיותך (עם קדוש)\" — ניט ווי עס שטייט פריער „להיות לו לעם סגולה\" — ווייל אויך פון דעם שינוי הלשון (להיותך — צו זיין, מיט א הדגשה אויף דער קדושה מצד די אידן) פארשטייט מען אז דאס זיין אן עם קדוש איז ניט דוקא א פעולה מצד דעם אויבערשטן (ווי אין פריערדיקן פסוק), נאר דער תוכן פון די אידנ'ס פעולה מפני הציווי.\nו. עס איז אבער די שאלה, כנ\"ל: א ציווי אויף קדושה געפינט מען שוין פריער „קדושים תהיו\" און נאך פריער „והתקדשתם והייתם קדושים\"?\nדעריבער איז רש\"י מעתיק בפירוש (ניט — מרמז דורך „גו'\") פון פסוק אויך „(ולהיותך) עם קדוש\": די פסוקים דא זיינען אויסן ארויסצוברענגען די אויסגעטיילטקייט פון אידן אלס „עם\", ווי התחלת הכתוב שלפנ\"ז „וה' האמירך היום (והוא הפרישך אליו מעמי הארץ) להיות לו לעם סגולה\". און אויך דער ציווי אויף קדושה בפרשתנו איז ניט אויף יעדער אידן אלס יחיד, נאר אויף דעם גאנצן עם, זיי זאלן זיין א „עם קדוש\".\nאון דעריבער איז אויף דעם מתאים זאגן אז דאס איז דער דבור „והייתם לי קדושים\" פון ס\"פ קדושים, וואס דארטן איז דער ציווי (אויך) אויף אזא קדושה וואס טיילט זיי אפ אלס אן עם פון אלע אומות, ווי דער פסוק איז ממשיך „והייתם לי קדושים כי קדוש אני ה' ואבדיל אתכם מן העמים להיות לי\".\nמשא\"כ דער פסוק בס\"פ שמיני „והתקדשתם והייתם קדושים\"24, ועד\"ז „קדושים תהיו\" בר\"פ קדושים, וואס דארטן איז ניט מודגש אז דאס זיינען ציוויים אויף דער קדושה פון כלל עם ישראל והבדלתם פון אלע אומות, נאר ציוויים צו יעדער אידן אלס יחיד, אזוי ווי די אנדערע ציוויי התורה.\nז. מען דארף נאך אבער פארשטיין (בפנימיות הענינים): אין הכי נמי אז",[["22","22","ואף את\"ל כפי המובן ממפרשים הנ\"ל לפרש\"י, שבכלל „אין בתנאי המדבר שיהי' לו מקבל זולתו כמו האומר\" (ל' הרא\"ם שם), ולפ\"ז אין נפק\"מ אם נאמר לי „לו לך\" או לא — שאני בנדו\"ד, שמשנה בפסוק א' לגבי פסוק שלפנ\"ז (משמיט „לך\"), י\"ל ש„כאשר דבר\" קרוב ללשון „ציווי\". ולהעיר שבכלל אמירה היא רכה ל' תחנונים ודיבור בכל מקום ל' קשה (פרש\"י בהעלותך יב, א. וראה פרש\"י יתרו יט, ג). *22) אלא שביתרו שם מקדים הסיבה „ועתה אם שמוע תשמעו בקולי ושמרתם את בריתי\" להבטחת ה' „והייתם לי סגולה גו'\"."],["23","23","להעיר מבעה\"ט כאן סוף פסוק יט."],["24","24","נוסף לזה דע\"פ פרש\"י שם „והייתם קדושים לפי שאני אקדש אתכם למעלה ולעולם הבא\" משמע קצת ד„והייתם קדושים\" אינו ציווי על פעולת ישראל."]]],[1300241177,"„ולהיותך עם קדוש\" איז בנוגע דער קדושה וועלכע איז דער תוכן פון אידנ'ס פעולה, מפני הציווי, ניט ווי „להיות לו לעם סגולה\" וואס ווערט אויפגעטאן דורך דעם אויבערשטן, וואס איז אבער די שייכות פון „ולהיותך עם קדוש\" צום ענין פון „ולתתך עליון על כל הגוים\" וואס איז אין זעלבן פסוק בהתחלתו?\nולכאורה איז „ולהיותך עם קדוש\" מער שייך צו „ולשמור כל מצותיו\" (וואס שטייט גאר אין פריערדיקן פסוק) היות אז דארט רעדט זיך וועגן דער מעלה פון אידן אין זייער אויספירן25 די ציוויים „לשמור כל מצותיו\", בעת אז „ולתתך עליון וגו'\" איז א חשיבות ומעלה וואס ווערט געגעבן פון דעם אויבערשטן (בדומה צו „להיות לו לעם סגולה\")26.\nוועט מען דאס פארשטיין בהקדים דאס וואס אין דער היינטיקער27 הפטורה28 ווערן ארויסגעבראכט באריכות די יעודים פון לעת\"ל — „והלכו גוים לאורך ומלכים לנגה זרחך . . בניך מרחוק יבאו ובנתיך על צד תאמנה וגו'\" ועוד — אז די אומות העולם וועלן באדינען און טאן אלץ לטובתם פון די אידן, ביז, ווי ער פירט אויס אין פסוק, אז „הגוי והממלכה אשר לא יעבדוך יאבדו והגוים חרב יחרבו\"29.\nדארף מען פארשטיין: בשלמא בנוגע די שבע מצות בני נח, וואס גוים זיינען אויף זיי נצטווה געווארן און זיינען זיי ניט מקיים, קומט זיי דערפאר דער עונש מיתה30; מען געפינט אבער ניט לכאורה קיין חיוב וציווי אז גוים דארפן באדינען די אידן, ובפרט אז פאר ניט מקיים זיין דאס זאל זיי קומען דער עונש — „יאבדו\", „יחרבו\".\nח. דער ביאור בזה: מ'האט גערעדט כמה פעמים31, אז די גאנצע בריאה, אויך אומות העולם, זיינען ניט קיין תכלית ומציאות פאר זיך, נאר בלויז אלס אמצעי צוליב אידן, כמחז\"ל32 „בראשית — בשביל ישראל שנקראו ראשית\", וואס זיי זיינען די מטרה ותכלית פון בריאת העולם ומלואה, און לעת\"ל, ווען עס וועט נתגלה ווערן די אמיתית המציאות פון יעדן נברא, וועט זיך דעמאלט אויספירן און אנזען בגלוי דער תכלית צוליב וועלכן די וועלט, כולל אומות העולם, זיינען באשאפן גע־וואָרן — בשביל ישראל.",[["25","25","או שהובדלו בזה שנצטוו „לשמור כל מצותיו\" (ראה רמב\"ן, ספורנו ואוה\"ח)."],["26","26","בראב\"ע כאן, ש„ולתתך עליון\" „זה הוא שכר האמירה\", והוא לפי פירוש רבי יהודה הלוי שהביא בפסוק שלפנ\"ז דהאמרת והאמירך מגזרת ויאמר, ולכן בשכר זה שישראל אומרים להיות לו לעם סגולה ולשמור כל מצותיו בא השכר בפסוק יט, ולתתך עליון. ולפירושו נמצא לכאורה, דגם „ולהיותך עם קדוש\" הוא שכר האמירה. אבל לפרש\"י שהוא לשון הפרשה והבדלה, בב' הפסוקים מדובר במעלת ישראל בזה שהפרישם מעמי הארץ, אלא שמפרט בזה כמה פרטים."],["27","27","דהפטורה הוא „מענינה של פרשה\" (טושו\"ע (אדה\"ז) אורח ר\"ס רפד). ואף שזהו דוקא „מבראשית עד י\"ז בתמוז (שאז) מפטירין מענין הפרשיות דומה בדומה ומשם ואילך לפי הזמן ולפי המאורע כו'\" (טוא\"ח סתכ\"ח קרוב לסופו מפסיקתא. ועד\"ז בשו\"ע ורמ\"א שם ס\"ח. וראה תוס' מגילה לא, ריש ע\"ב. רמב\"ם הל' תפלה פי\"ג הי\"ט) — כבר נתבאר כמ\"פ, דמכיון שכל עניני התורה הם בתכלית הדיוק, מובן שהם שייכים גם להפרשיות (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091061\" data-slug=\"likkutei-sichot\" data-id=\"1300091061\">לקו\"ש ח\"ט ע' 61</a>. ושם גם הרמז בלשון הטור סתכ\"ח שם)."],["28","28","ישעי' ס, ג-ד."],["29","29","שם, יב."],["30","30","ראה סנהדרין נח, ב. רמב\"ם הל' מלכים ספ\"ט. רמב\"ן עה\"ת וישלח לד, יג."],["31","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051171\" data-slug=\"likkutei-sichot\" data-id=\"1300051171\">לקו\"ש ח\"ה ע' 159</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091150\" data-slug=\"likkutei-sichot\" data-id=\"1300091150\">ח\"ט ע' 150</a>. ועוד."],["32","32","פרש\"י ר\"פ בראשית. וראה ויק\"ר פל\"ו, ד."]]],[1300241178,"דעריבער איז דאס מכריח, אז „הגוי והממלכה אשר לא יעבדוך\", אז די וואס פירן ניט דורך מטרת בריאתם (אלס אן אמצעי) — „יאבדו\", זיי פארלירן זייער מציאות בדרך ממילא.\n[וי\"ל אז דאס איז דער טעם פארוואס א בן נח קומט מיתה פאר עובר זיין אויף יעדער איינער פון די ז' מצות ב\"נ — ניט ווי די עונשים וואס זיינען ביי אידן וועלכע זיינען פארשידן לויט דער פאר־שידנקייט פון די מצות: די ז' מצות פון בני נח איז ענינם — סיבת מציאות פון ב\"נ, וכ\"ז — בשביל ישראל ובשביל התורה; און בשעת זיי פירן ניט דורך כוונת בריאתם, פארלירן זיי בדרך ממילא די סיבה און דעם יסוד פון זייער קיום31].\nאון דאס איז דער פירוש פנימי פון „ולתתך עליון על כל הגוים אשר עשה\", ווי עס שטייט אין ש\"ך על התורה: „כאילו לא עשאום אלא בשבילך כמו שאמר בן עזאי לא נבראו כולם אלא לשמשני כו'\"33.\nד. ה. אז דער ענין פון „ולתתך עליון על כל הגוים\" איז דער אויספירן בפועל די מטרה פון זייער באשאפן ווערן, וואס דאס איז א מעין פונעם גילוי דלעתיד, כנ\"ל.\nעפ\"ז קומט אויס, אז דער תוכן פון די צוויי פסוקים הנ\"ל בפרשתנו ברענגט ארויס דעם יתרון ומעלה אין דער מציאות פון אידן לגבי דער מציאות פון אומות העולם — „והוא הפרישך אליו מעמי הארץ להיות לו לעם סגולה\", אז די אידן זיינען אויסגעטיילט פון די „עמי הארץ\" דערמיט וואס זייער מטרה\nותכלית איז אין זייער מציאות עצמה, זיי זיינען ניט ווי אן אמצעי צו א צווייטער מציאות, וכדלקמן.\nט. דער ביאור בזה: דער טייטש פון „(וה' האמירך היום) להיות לו לעם סגולה\" איז (ווי רש\"י טייטשט אויף „והייתם לי סגולה\"34, וואס ער ברענגט דא), „אוצר חביב כמו וסגולת מלכים35 כלי יקר ואבנים טובות שהמלכים גונזים אותם כך אתם תהיו לי סגולה משאר אומות\" —\nאון ווייבאלד אז דאס איז א משל וואס תורה גיט אויף אידן איז מובן, אז ער איז בתכלית הדיוק.\nדארף מען פארשטיין: וואס איז די תועלת פון די „כלי יקר ואבנים טובות\" בשעת „גונזים אותם\", זיי זיינען בא־האלטן און פארבארגן?\nווען מען נעמט, לדוגמא, אבנים טובות און מ'איז זיי קובע אין דעם טבעת המלך אדער אין כתר המלך, גיבן זיי צו, כמובן, אין דעם הוד והדרת המלך36: משא\"כ ווען זיי זיינען בא־האלטן, אוצר גנוז פון עיני רואים — טוען זיי לכאורה גאר ניט אויף, קיינער האט ניט קיין תועלת והנאה פון זייער טייערקייט און פון זייער יופי.\nנאר ווען מ'נעמט זיי ארויס פון אוצר גנוז — צוליבן צורך גדול פון ניצוח המלחמה, ווי דער רבי זאגט אין דעם המשך ההילולא37, אז צוליב ניצוח",[["33","33","במשנה וברייתא בסוף קידושין לפנינו „והלא (והם) לא נבראו אלא לשמשני\". והוא מאמר ר\"ש בן אלעזר. וכ\"ה ביל\"ש ירמי' רמז רעו."],["34","34","בפ' יתרו שם."],["35","35","קהלת ב, ח."],["36","36","להעיר מהל' במשל אדה\"ז (התמים ח\"ב ע' מט [עב]) באבן יקרה שהיתה (רק) בכתר המלך (שלא נמצא אפילו באוצר המלך) ש„היא נזר העטרה המכתירה\"."],["37","37","באתי לגני ה'שי\"ת פי\"א. וראה שם פי\"ז. פי\"ט."]]],[1300241179,"המנגד איז דער מלך „מבזבז כל סגולות האוצרות דהון יקר הנאסף והנקבץ במשך כמה שנים מדור אחר דור ואשר מעולם לא השתמש מזה לשום דבר, וכמוס וחתום מעין כל רואה\" — איז דא א תועלת פון זיי\nאון אויך דעמאלס ווערט עס אנגערופן „בזבוז\", מ'איז מבזבז זיי צוליב נצחון המלחמה ניט א רגיל'דיקער נוצען זיי, נאר א יוצא מן הכלל לגמרי.\nיו\"ד. די הסברה בזה: דאס וואס די אוצרות בלייבן גנוז, כמוס וחתום מעין כל רואה — איז ווייל די אוצרות זיינען נוגע (ובערך פון) דעם מלך אליין, אין זיין עצם מציאות ווי ער איז פאר זיך.\nעס זיינען פאראן אוצרות המלך וואס תפקידם איז, אז מיט זיי ווערן דורכגע־פירט עניני המלכות — דורך אויסגעבן זיי אויף צרכי המדינה וכיו\"ב38, אדער דאס וואס מ'איז זיי קובע אין כתר המלך (וכיו\"ב) כדי צו מוסיף זיין אין הוד והדרת המלך, וואס דאס איז אן ענין עיקרי אין הנהגת המלכות — „מלך ביפיו תחזינה עיניך\"39.\nאבער די אוצרות הגנוזים של המלך, איז (ניט כדי צו דורכפירן אן ענין של מלוכה, נאר עס איז) פארבונדן מיט דעם מלך אליין. זיין עצם מציאות אלס מלך איז פארבונדן דערמיט וואס ער האט אוצרות גנוזים פון אבנים טובות ומרגליות מיט וועלכע ער איז זיך משתעשע און האט דערפון תענוג40,\nוואס דאס איז מוסיף אין זיין אמת'דיקע רוממות (התנשאות עצמית)41.\nאון דאס איז אויך וואס אידן זיינען „לי סגולה\" — אן „אוצר חביב\"42: די עצם מציאות פון א אידן איז העכער אפילו פון דעם וואס דורך זיי ווערט נתגלה מלכותו ית' בעולם (דורך עבודתם בתומ\"צ), זייער תכלית איז — דער עצם פאראנענקייט זיי'רע43: אידן זיינען איין זאך, כביכול, מיט עצמותו ומהותו ית', און דער אויבערשטער איז זיך „משתעשע\" מיט אידן (ווי א מלך וואס האט תענוג פון זיינע אוצרות הגנוזים און נאך מער).\nקומט אויס, אז דער חילוק פון אידן און אנדערע אומות איז אין זייער עצם בריאה (באשאף): די מציאות פון אומות העולם איז ניט צוליב זיי אליין, נאר צוליב (א צווייטער זאך — צו) אויס־פירן דעם תפקיד וואס איז זיי צוגע־טיילט געווארן; משא\"כ אידן, איז דער תכלית פון זייער באשאף איז זייער עצם פאראנענקייט44 (נאך איידער זיי פירן",[["38","38","ראה רמב\"ם הל' מלכים פ\"ג ה\"ד."],["39","39","ישעי' לג, יז. רמב\"ם שם פ\"ב ה\"ה."],["40","40","וצ\"ע ברמב\"ם פ\"ג שם: ולא ירבה לו כסף וזהב להניח בגנזיו ולהתגאות בו או להתנאות בו כו' ואם הרבה לוקה. ואולי י\"ל שלכן הוסיף הרמב\"ם „להתגאות בו או להתנאות בו\", שהאיסור הוא שאין ענין בשביל שלימות המלוכה והרוממות שלו, כ\"א להתגאות (או „להתנאות בו\") כלפי העם. ולהעיר מר\"ן סנהדרין כא, ב: „דמאי דאסר רחמנא על המלך שלא ירבה לו כסף וזהב היינו שלא יבקש מס גדול כדי להתעשר אלא כדי שכר חיילותיו אבל אם הקנה לו מן השמים ממון הרבה לא קאי בלאו\"."],["41","41","ראה המשך תער\"ב בתחלתו (ספ\"א)."],["42","42","להעיר מאוה\"ת יתרו (ע' תתד ואילך). ד\"ה ואתם תהיו לי תר\"ס — בביאור ג' הענינים דבפסוקים שם. ושם (ע' תתז) ד„סגולה\" „זהו מעלתה מצד מהותה ועצמותה כו'\", „הוא מצד נשי' בעצמך\" (סד\"ה ואתם תהיו לי שם). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181030\" data-slug=\"likkutei-sichot\" data-id=\"1300181030\">לקו\"ש חי\"ח ע' 21</a> ואילך. ואכ\"מ."],["43","43","ראה המשך תרס\"ה ע' תע ואילך. סה\"מ תשי\"א ס\"ע 109 ואילך — בביאור החילוק בין נשמות ומלאכים. ובסה\"מ תשי\"א שם (ע' 110) „דבעצם ענין ירידת הנשמות והיותן למטה הנה מאיר אור פנימי בעולם\"."],["44","44","ואי\"ז סתירה לזה דאני נבראתי לשמש את קוני (משנה סוף קידושין), כי אמתית מציאות בנ\"י היא למעלה מעולם הבריאה („נבראתי\") ואפילו דעולם האצילות („קוני\") ואדרבא במי נמלך (בנוגע"]]],[1300241180,"דורך תפקידם בעולם)45.\nאון דאס מיינט „וה' האמירך היום — הפרישך אליו מעמי הארץ — להיות לו לעם סגולה\", אז אידן זיינען אינגאנצן אויסגעטיילט פון עמי הארץ46, ווייל זיי זיינען אן „עם סגולה\", אן „אוצר חביב\" כנ\"ל.\nיא. דערמיט וועט מען אויך פאר־שטיין די שייכות פון די פסוקים צו ראש השנה [וכידוע47 אז „את ה' האמרת היום גו' וה' האמירך היום\" מיינט דעם טאג פון ר\"ה]:\n„את ה' האמרת היום\" איז דאס וואס אידן זיינען ממליך48 דעם אויבערשטן בר\"ה — „אמרו לפני .. מלכיות כדי שתמליכוני עליכם\"49, און „וה' האמירך היום\" איז דאס וואס דער אויבערשטער נעמט אן די הכתרה פון אידן50, וואס דאס ווערט נמשך און אויפגעטאן אין דער בריאה וסדר השתלשלות, ע\"ד ווי בתחלת הבריאה וואס „במי נמלך בנש־מותיהן של צדיקים\"51.\nולכאורה, פון דעם גופא וואס אידן זיינען ממליך דעם אויבערשטן איז מובן אז זיי זיינען דא איידער זיי זיינען אים ממליך; ועד\"ז בתחלת הבריאה: פון דעם וואס מ'זאגט „במי נמלך בנשמותיהן של צדיקים\" איז מובן אז זיי זיינען דא פאר דער המלכה — אין וואס באשטייט דאן זייער תפקיד?\nדאס איז דער פירוש פון „עם סגולה\" — אן „אוצר חביב\" וואס מ'איז גונז; ד. ה. אז די אמת'ע מציאות פון אידן איז דאס וואס זיי זיינען „נעלמה מעיני כל חי\" און „שעשועים לפניו\", ווי זיי זיינען איין זאך כביכול מיט עצמותו ית' — און זיינען בדוגמת עצמותו ומהותו ית', וואס אויף אים איז דאך ניט שייך צו זאגן אז ער איז ח\"ו צוליב וועלכן ס'איז ענין.\nאון ווי דער מגיד52 זאגט אף „אף קודם שנבראו ישראל הי' נחקק צורתם במחשבה, כמ\"ש רז\"ל53 ישראל עלו במחשבה\".\nיב. און דאס איז דער חילוק צווישן די צוויי פסוקים „וה' האמירך גו' להיות לו לעם סגולה גו'\" און „ולתתך עליון גו'\":",[["","","להתהוות אבי\"ע) בנשמותיהן של צדיקים, אלא שבירידתה לבריאה (אתה בראת) — הו\"ז לשמש את קוני. ועד\"ז הוא בברה\"ע שהוא מפני שנתאווה להיות לו דירה בתחתונים ולמטה מזה — בכל עולם לפי דרגתו (ראה המשך תרס\"ז ע' תמו). אבל גם בהיות בנ\"י בעוה\"ז הגשמי יש בכאו\"א עצם נשמתו („נשמה שנתת בי\"). — וראה לקו\"ש ח\"ה ע' 246. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061247\" data-slug=\"likkutei-sichot\" data-id=\"1300061247\">ח\"ו ע' 236</a> ובהערות שם. — והל' שם צריך תיקון. ואכ\"מ."],["45","45","וגם השלמת הכוונה דדירה בתחתונים שע\"י נשמות ישראל, אין זה שתפקידם הוא לפעול דבר שמחוץ להם, כי זה „שתכלית הבריאה הי' בשביל להיות לו ית' דירה בתחתונים (ו)היינו לשכון שכינתו בישראל\" (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370341\" data-slug=\"torah-or\" data-id=\"3901370341\">תו\"א עו, ד</a>. וראה המשך תרס\"ז ס\"ע תסח ואילך. ועוד), והיינו שיתגלה גם במציאותם למטה שרשם בעצמותו, שישראל וקוב\"ה כולא חד (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151490\" data-slug=\"likkutei-sichot\" data-id=\"1300151490\">לקו\"ש חט\"ו ע' 477</a> ואילך. וש\"נ)."],["46","46","ומ\"ש רש\"י „מעמי הארץ\" (דמשמע מזה שיש איזו שייכות ביניהם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091169\" data-slug=\"likkutei-sichot\" data-id=\"1300091169\">לקו\"ש ח\"ט ע' 169</a>) — היינו כמו שפירש רש\"י לעיל בפ' יתרו שם עה\"פ „והייתם לי סגולה מכל העמים\", דזהו רק כדי ש„תהא חבתכם נכרת\", אבל (אין להם שום חשיבות וערך לבנ\"י כי) „הם בעיני ולפני לכלום\"."],["47","47","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450600\" data-slug=\"or-hatorah-hb\" data-id=\"8316450600\">אוה\"ת פרשתנו ע' תתרסט</a>. בהוספות (לאחרי פ' ברכה) ס\"ע א'תתקטז ואילך. ועוד. וראה לקמן ע' 191."],["48","48","ראה תרגום ירושלמי כאן פסוק יח: ומימרא דה' אמליך עליכון כו' (הובא בפי' בעלי התוס' כאן. ועוד)."],["49","49","ר\"ה טז, א. לד, ב."],["50","50","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450590\" data-slug=\"or-hatorah-hb\" data-id=\"8316450590\">אוה\"ת</a> פרשתנו שם. שם ס\"ע תתרנט ואילך. ס\"ע תתרעה ואילך."],["51","51","כן הובא בכמה מקומות. וראה ב\"ר פ\"ח, ז. רות רבה פ\"ב, ג."],["52","52","אור\"ת ב, ג. וראה המשך תער\"ב ח\"ב ס\"ע תתקב ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151500\" data-slug=\"likkutei-sichot\" data-id=\"1300151500\">לקו\"ש חט\"ו ע' 487</a>."],["53","53","ב\"ר בתחלתה."]]],[1300241181,"אין דעם ערשטן פסוק רעדט זיך וועגן דער מעלה פון אידן מיט וועל־כער זיי זיינען אינגאנצן אויסגעטיילט פון אומות העולם: „לעם סגולה\" — „אוצר חביב\", אז אידן זיינען „גנוז\" בעצמותו ית', זיי זיינען כולא חד מיט קוב\"ה.\nאון מצד דעם קומט ארויס, אז זייער עבודה איז אין אופן פון „ולשמור כל מצותיו\": דאס וואס אידן היטן תרי\"ג מצות — ניט נאר ז' מצות ווי בני נח — איז ניט נאר א חילוק אין כמות, אז אידן פירן דורך מער מצות (ותפקידים) ווי ב\"נ, נאר דאס איז אן אנדער איכות אין „ולשמור\":\nביי אומות העולם, וועלכע זיינען באשאפן געווארן צוליב א תפקיד, איז זייער שמירת המצות מיט א מדידה והגבלה — וויפל ציוויים (ותפקידים) זיי איז מלכתחילה צוגעטיילט געווארן:\nביי אידן אבער, וואס זיי זיינען איין זאך כביכול, מיט עצמותו ומהותו ית' (כנ\"ל), איז ביי זיי דער ענין פון „ולשמור כל מצותיו\" — אן קיין מדידה והגבלה; ווייבאלד אז „הוא ורצונו אחד\"54, איז וואס פאר א מצוה (רצון) עס זאל נאר זיין, איז אידן, וועלכע זיינען איין זאך מיט עצמות, זיינען מסור ונתון אויף דורכצופירן דעם רצון.\nאון אין צווייטן פסוק — „ולתתך עליון גו'\" — ברענגט זיך ארויס די מעלה פון אידן אויך ווי זיי (ווערן נבדל ממקורם און) קומען אראפ למטה אין וועלט, אז אויך דעמאלט זיינען זיי „עליון על כל הגוים\": זיי זיינען דער תכלית פון דער גאנצער בריאה, און\nאלע נבראים (כולל „כל הגוים\") זיינען צוליב זיי, כנ\"ל.\nוואס דאס איז אזא יתרון ומעלה פון אידן וועלכע איז בערך אז גוים זאלן קענען משיג זיין און דערהערן ווי עם ישראל איז „עליון על כל הגוים\", וואס דערפאר זיינען זיי מהלל ומשבח די אידן (זיי זיינען, ווי דער פסוק איז מסיים, „לתהלה ולשם ולתפארת\")55.\nאון דאס דריקט זיך אויס בגלוי דורך „ולהיותך עם קדוש לה\"א כאשר דבר\" — „והייתם לי קדושים\", אז אויך אין ענינים גשמיים פון אידן, אין וועלכע זיי זיינען בחיצוניות גלייך צו אוה\"ע56, זיינען זיי באמת אן עם קדוש לה\"א, ווי ס'איז מודגש אין דעם המשך הכתוב וואס רש\"י ברענגט דא אראפ „(והייתם לי קדושים גו') ואבדיל אתכם מן העמים להיות לי\".\nאון דאס ווערט נאכמער ארויס־געבראכט אין פירוש רש\"י דארטן: „מנין שלא יאמר אדם נפשי קצה בבשר חזיר כו' אבל יאמר אפשי ומה אעשה ואבי שבשמים גזר עלי ת\"ל ואבדיל אתכם מן העמים להיות לי שתהא הבדלתכם מהם לשמי פורש מן העבירה ומקבל עליו עול מלכות שמים\". ד. ה. א איד האט כאילו די זעלבע אפשריות ווי א ניט־איד57, און אעפ\"כ איז ער פורש ומקבל עליו עול מלכות שמים.\nיג. פון כהנ\"ל קען מען ארויס־נעמען א הוראה מיוחדת אין גודל הזהירות והזריזות פון אהבת ישראל און אויף וויפל מ'דארף זיין איבערגעגעבן",[["54","54","דכל המצות מתייחסים אל העצמות — ראה בארוכה ס' השיחות תורת שלום ס\"ע 190 ואילך."],["55","55","ראה ש\"ך עה\"ת כאן: לתהלה שיהללום כל גוים כמו שהם מהללים להקב\"ה . . וכן יהיו לשם שיכירו כולם ששם יהודי הוא שמו של הקב\"ה כו'."],["56","56","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט סע\"ב</a> ואילך)."],["57","57","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310013\" data-slug=\"tanya\" data-id=\"3401310013\">תניא רפ\"ח</a>."]]],[1300241182,"צו טאן מיט א צווייטן אידן — ווארום אט די מעלה פון „להיות לו לעם סגולה\" איז דא בא יעדער אידן.\nאון וועלכן מצב א איד געפינט זיך בכחותיו הגלוים, איז ער אלעמאל מצד עצם מציאותו לגמרי מופרש מעמי הארץ, זיינדיק „נצר מטעי מעשה ידי להתפאר\" פון דעם אויבערשטן (ווי מ'זאגט בסיום ההפטורה<sup data-n=\"58\">58</sup>;\nוואס דערפאר איז יעדער איד א מציאות נצחית (כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"59\">59</sup> און א מציאות פון „(עלה ב)מחשבה\" וואס איז לעצמו (ניט ווי כל הבריאה60 וואס בדבר ה' שמים נעשו61, וואס ענין הדיבור איז בשביל הזולת)62; נאר מען דארף די מעלה עצמית ארויס־ברענגען מן ההעלם אל הגילוי.\nובפרט אין דער וואך וואס מ'לייענט בתורה פ' תבא און די הפטורה הנ\"ל, ובמיוחד ווען דער טאג פון ח\"י אלול — דער יום הולדת פון די „שני המאורות הגדולים\"63, פון דעם בעש\"ט און דעם אלטן רבי'ן — פאלט אויס (ווי די קביעות פון שנה זו) אין דער וואך פון פ' תבא, וואס פון די יסודות העיקריים פון תורת החסידות פון בעש\"ט און אלטן רבי'ן איז — אהבת ישראל64,\nהאט מען א באזונדערע נתינת כח צו פועל'ן אויף א אידן, יעדער אידן, אז זיין מעלה עצמית פון „וה' האמירך היום להיות לו לעם סגולה\" זאל ביי אים נתגלה ווערן אין דעם אופן פון „לשמור כל מצותיו\" בפועל; און אויך ארויס־ברענגען ביי אים בגלוי דעם ענין פון „ולתתך עליון על כל הגוים אשר עשה\" ביז „ולהיותך עם קדוש לה' אלקיך\", צו זיין לגמרי העכער און מובדל פון יעדן ענין פון גוי'אישקייט, כולל דעם „גוי אשר בקרבך\"65;\nאון דורך דעם טוט מען אויף ביתר שאת דעם ענין פון „תמליכוני עליכם\", אז עס ווערט ניכר לעין כל ווי „ה' אלקי ישראל מלך\", אז אויך גוים זען אז אידן זיינען אן עם סגולה,\nאון פון דעם — צום קיום היעוד אין נבואת ישעי' בהפטורת פרשתנו, ביז צום סיום: „אני ה' בעתה אחישנה\" — במהרה בימינו ממש.\n(משיחת ש\"פ תבוא תש\"מ)",[["58","58","ישעי' שם, כא."],["59","59","סנהדרין ר\"פ חלק."],["60","60","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. אגה\"ת פ\"ד. ובכ\"מ."],["61","61","תהלים לג, ו."],["62","62","וראה המשך תרס\"ז — ד\"ה בשעה שהקדימו תרס\"ז ואילך."],["63","63","לשון כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע (ס' השיחות תש\"ג ע' 141)."],["64","64","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091156\" data-slug=\"likkutei-sichot\" data-id=\"1300091156\">לקו\"ש ח\"ט ע' 156</a> ואילך (ושם, שזהו תוכן התחלת סדרה זו — מצות ביכורים). קונטרס אהבת ישראל."],["65","65","לקו\"ת פרשתנו מב, ב."]]],[1300241183,"<h3>תבא ב</h3>\nא. אין מפרשי התורה1 איז מבואר, אז די ענינים פון היפך הברכה אין דער „תוכחה\" שבפרשתנו, זיינען ניט בלויז תוכחות און וואַרענונגען, וואס וועלן קומען „אם לא תשמעו בקול ה״א גו׳\"2, נאר דאס זיינען עניני נבואה וועלכע זיינען מקויים געווארן, ובלשון האבר־בנאל3: „ראוי שנדע שהקללות שנזכרו בפרשה הזאת לא באו על דרך איום וגזום להפחיד לבב האנשים, אבל באו ברוח אלקין קדישין להגיד מה שיהי׳ באחריתם כי הנה כולם נתקיימו כו׳\".\nדי פסוקים פון פרשת התוכחה רעדן בכלל וועגן דעם עונש הגלות — „והפיצך ה׳ בכל העמים גו׳\"4, און מפרשים זיינען מבאר בפרטיות ווי די אלע ענינים פון היפך הברכה זיינען מקויים געווארן נאכן חורבן בית שני (גלות הרביעי)5, אדער אויך נאכן חורבן בית ראשון (גלות בבל וכו׳)6.\nעס איז מובן, אז די כוונה ותכלית פון די יסורי הגלות וכו׳ פון דער תוכחה איז ניט7 צוליב, ח״ו, נקמה אין אידן אדער סתם צוליב מעניש זיין זיי, נאר דאס איז לטובתם8, ובלשון רש״י9: „והקללות והיסורין מקיימין אתכם ומציבים אתכם לפניו\"10.\nדארף מען פארשטיין: די גמרא11 זאגט, אז „ארבעה מתחרט עליהן הקב״ה שבראם12 ואלו הן גלות כשדים וישמעאלים13 ויצר הרע\"14. פון דעם איז משמע, אז גלות איז ניט קיין טובה פאר אידן — וואָרום אויב גלות וואלט מיט זיך געבראכט א תועלת טובה, וואס לולא דעם גלות וואלט מען ניט געהאט",[["1","1","ראה רמב״ן פרשתנו כח, מב. אברבנאל כח, טו ואילך. עקידה פרשתנו שער צח. ועוד."],["2","2","פרשתנו כח, טו."],["3","3","שם בתחלתו."],["4","4","כח, סד ואילך. וכן שם לו ואילך."],["5","5","לדעת הרמב״ן (פרשתנו שם. בחוקותי כו, טז) שהתוכחה שבפ׳ בחוקותי מתייחסת לימי חורבן בית ראשון, והתוכחה שבפרשתנו לימי חורבן בית שני, „על זמן גלותנו היום ביד החי׳ הרביעית\" (רמב״ן פרשתנו שם), „לגלותנו היום שאנו מפוזרים מסוף העולם ועד סופו\" (ל׳ הרמב״ן בחוקותי שם בפי׳ הכתוב (פרשתנו שם) והפיצך ה׳ בכל העמים), עיי״ש בארוכה."],["6","6","ראה בארוכה אברבנאל ועקידה שם. ומפרטים בפרטיות גלות בנ״י כל משך הזמן."],["7","7","ולהעיר מברכות (ה, סע״א. וש״נ): שלש מתנות טובות נתן הקב״ה לישראל וכולן לא נתנן אלא ע״י יסורין כו׳. וראה שם בהסוגיא לפנ״ז."],["8","8","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231098\" data-slug=\"likkutei-sichot\" data-id=\"1300231098\">לקו״ש חכ״ג ע׳ 98</a> ואילך שכ״ה גם ע״ד הפשט."],["9","9","נצבים כט, יב."],["10","10","וראה ברכות שם: נאמר ברית במלח . . ונאמר ברית ביסורין דכתיב (פרשתנו כח, סט) אלה דברי הברית מה ברית כו׳ ממתקת כו׳ אף ברית האמור ביסורין יסורין ממרקין כו׳. וכיו״ב בכ״מ."],["11","11","סוכה נב, ב."],["12","12","כ״ה הגירסא בש״ס. ובע״י: ארבעה הקב״ה מתחרט עליהם על שבראם. ובדק״ס „הקב״ה בכל יום שבראם\"."],["13","13","להעיר שכשדים הוא (בעיקר) גלות בבל כידוע (ראה יומא י, א), וישמעאלים בימי גלות הרביעי (ראה רמב״ן הובא ברקנטי (בחוקותי שם): אויבך ושונאך רמז לשני האומות. ופי׳ בלבוש שם: ר״ל עשו וישמעאל)."],["14","14","כ״ה הסדר בש״ס לפנינו, ובע״י: כשדים ויצה״ר ישמעאל וגלות. ובדק״ס הביא ב׳ גירסאות: (כשדים וישמעאלים ו)יצה״ר וגלות: גלות ויצה״ר. וכ״ה גירסת הר״ח בסוכה שם (כשדים וישמעאלים גלות ויצה״ר). ונראה שכ״ה גם גירסת רש״י בסוכה שם, כדמוכח מסדר הפי׳ בפרש״י. וכן מפורש במהרש״ל שם. ומסיים: וכן מצאתי בספרים מדויקים. וראה לקמן בפנים ס״ה."]]],[1300241184,"די תועלת טובה, פארוואס איז מען זיך „מתחרט\" על זה?\nאין ירושלמי15 געפינט מען טאקע, אז עס ווערן גערעכנט בלויז „שלשה דברים\", און „גלות\" ווערט ניט דערמאנט,\nאבער עס איז זייער שווער צו זאגן אז משום קושיא הנ״ל דערמאנט ניט דער ירושלמי גלות, און אז אין דעם איז א מחלוקת צווישן דעם בבלי מיטן ירושלמי — צי דער ענין הגלות האט אין זיך א תועלת טובה אדער ניט —\nוואָרום די שאלה הנ״ל איז ניט נאר בנוגע גלות, נאר אויך בנוגע די אנדערע דריי פרטים „כשדים ישמעאלים ויצה״ר\".\nוביותר — ווייל אז „כל מה שברא הקב״ה בעולמו לא בראו אלא לכבודו\"16, אלץ וואס דער אויבערשטער האט באשאפן — כולל אויך „כשדים ישמעאלים ויצה״ר\", זיינען „לכבודו\" ובמילא לתכלית טובה, היינט ווי איז שייך צו זאגן אויך בנוגע די דריי ענינים (אין ירושלמי) אז הקב״ה מתחרט עליהם (בלשון הירושלמי „תהא שבראן\")?\nב. וי״ל ובהקדים דעם כלל אז אפושי מחלוקת לא מפשינן — אויב ס׳איז נאר דא אן אפשריות איינצולערנען (אפילו בדוחק) אז דאס איז ניט קיין פלוגתא17. ולפי״ז איז מסתבר בנדו״ד, איינלערנען אז ס׳איז ניטא קיין מחלוקת צווישן דעם בבלי מיט׳ן ירושלמי, צי דער אויבערשטער איז מתחרט אויך אויף גלות18:\nגלות איז ניט א זאך וואס קומט מצד עצמו, נאר — אלס מסובב פון יצה״ר: אז מ׳לאזט זיך איינריידן פון יצה״ר און מ׳פאלט דורך אין חטאים בריינגט עס גלות: מפני חטאינו גלינו.\nועפ״ז איז אויך לדעת הירושלמי, וויבאלד אז דער אויבערשטער איז „תהא\" אויף יצה״ר, איז אין דעם נכלל דער ענין הגלות, וועלכער איז א תוצאה פון יצה״ר:\nאון ווייל דער ירושלמי רעדט ענינים מער בכללות לגבי בבלי — איז אזוי אויך בנדו״ד — טיילט ער ניט אויס דעם מסובב (גלות) — און דערמאנט נאר די סיבה (יצה״ר).\nמשא״כ בבלי, וואס רעדט בפרטיות, איז מונה יצה״ר בפ״ע און גלות בפני עצמה.\nאון דאס איז פארבונדן מיט׳ן כללות־דיקן חילוק צווישן דעם דרך הלימוד פון תלמוד בבלי און דעם תלמוד ירושלמי:\nבכו״כ ענינים — רעדן זיי זיך אין תלמוד ירושלמי בקיצור ובכללות, און זיי ווערן נתבאר בפרטיות יותר ובאריכות אין תלמוד בבלי19.\nובפשטות איז דער טעם פון דעם חילוק — לימוד הגמרא שבבבל האט זיך געצויגן א לענגערע צייט נאך חתימת תלמוד ירושלמי — דער חיבור וחתימה פון תלמוד בבלי איז געווען „אחר שחיבר ר׳ יוחנן הגמרא ירושלמית בכמו מאה שנה\"20,",[["15","15","תענית פ״ג סה״ד."],["16","16","אבות ספ״ו. הובא בכ״מ גם על היצה״ר — ראה לדוגמא של״ה סח, א (מזוו״ב (קסב, א) ופרדס (שער התמורות פ״ג))."],["17","17","תד״ה והאמר — יומא פז, ב. יד מלאכי כללי שני התלמודים סי׳ יוד. שד״ח (כ״ט) כללי הפוסקים ס״ב אות א. דרכי שלום (בשד״ח קה״ת) כללי הש״ס אות ל׳ סרנ״ז."],["18","18","וכמ״ש במראה הפנים לירושלמי שם. ועוד"],["19","19","ראה חינוך בהקדמתו סוף קטע הא׳."],["20","20","ל׳ הרמב״ם בהקדמתו לספר היד."]]],[1300241185,"אזוי אז תלמוד בבלי איז אין גדר פון „בתראי\" לגבי תלמוד ירושלמי, וואס דאס איז איינער פון די טעמים21 פארוואס הלכה כבבלי לגבי ירושלמי — ווייל די חכמים פון תלמוד בבלי, זייענדיק „בתראי\", האבן געוואוסט וואס עס שטייט אין ירושלמי, וואס חתימתו איז געווען פריער, כנ״ל, איז דאך א כלל אז הלכה כבתראי.\nאון דער חילוק צווישן קדמאי און בתראי באשטייט אויך אין דעם, וואס די בתראי זיינען מער מפרט ומפרש ווי די קדמאי22; וכשם ווי מ׳געפינט דעם אונטערשייד צווישן לשון המשנה (וואס איז א „דיבור קצר וכולל ענינים רבים\"<sup data-n=\"23\">23</sup> און לשון הגמרא אין א שפעטערדיקן זמן24, עד״ז איז דער חילוק אין גמרא גופא צווישן דעם (פריערדיקן) תלמוד ירושלמי און דעם (שפעטערדיקן) תלמוד בבלי, ומהאי טעמא זאגט דער ירושלמי נאר ג׳ דברים (— בכללות) און דער בבלי רעכנט ד׳ דברים (— בפרטיות)25.\nג. מ׳קען אבער פרעגן אויפן עצם כלל:\nדי גמרא זאגט אין מס׳ תענית26: „א״ר יוחנן ג׳ מפתחות בידו של הקב״ה שלא נמסרו ביד שליח ואלו הן מפתח של גשמים ומפתח של חי׳ ומפתח של תחיית המתים\", און „במערבא אמרי אף מפתח של פרנסה\".\nזעט מען דא, אז אדרבה — אין מערבא, אין א״י, איז מען מפרט ומוסיף א פערטן ענין (פרנסה), בעת אז אין בבלי איז מען כולל ומקצר — וואָרום פרנסה איז ניט קיין באזונדער ענין, נאר א פרט המסובב פון גשמים, ווי די גמרא פירט דארט אויס „ור׳ יוחנן מאי טעמא לא קחשיב להא, אמר לך גשמים היינו פרנסה\", פרנסה איז א תוצאה פון גשמים „שזרעים ופירות גדלים מהם לפרנסת העולם\"27.\nוהתירוץ פשוט: דער כלל הנ״ל (סעיף ב׳) בנוגע תלמוד בבלי ותלמוד ירושלמי, איז ווייל בבלי איז בתראי (אין זמן) לגבי ירושלמי: די דעה הנ״ל (במס׳ תענית) פון „מערבא\" איז אבער ניט געזאגט געווארן אין א זמן קדום לגבי „אמר ר״י\", נאר אדרבא „אמרי אף\", (אין דעם זעלבן זמן נאר) שפעטער28.\nולהעיר — דער מרא דשמעתתא אין בבלי וועלכער זאגט „ג׳ מפתחות כו׳\", איז ר׳ יוחנן וואס „חיבר הגמרא ירושלמית\" — וואס לפי״ז איז עס בסדר: די מימרא פון ר׳ יוחנן איז (על דרך תלמוד ירושלמי) — קדמאי (קיצור וכלל) און דערנאך במערבא אמרי אף — בתראי לגבי ר״י — און דערפאר מער בפרטיות וכו׳29.",[["21","21","ריי״ף סוף עירובין. ועוד. וראה אנציק׳ תלמודית ערך הלכה ע׳ רנ ואילך."],["22","22","ראה ספרי הכללים (יד מלאכי כללי הרמב״ם אות כד ועוד) — ע״פ ב״י לטויו״ד סר״א ד״ה ומ״ש ואף אם תטבול: דבתראה הוא . . הוה לי׳ לפרש. ובכ״מ. וראה בהנסמן לקמן הערה 55."],["23","23","הרמב״ם בהקדמתו לפירוש המשניות ד״ה אחר כן ראה להסתפק."],["24","24","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201087\" data-slug=\"likkutei-sichot\" data-id=\"1300201087\">לקו״ש ח״כ ע׳ 87</a> ואילך."],["25","25","להעיר שבירושלמי בעל המאמר הוא רבי פנחס בן יאיר — תנא, ובבבלי בעל המאמר הוא — אמורא (אמר רב חנא בר אחא אמרי בי רב). אמנם מזה שבירושלמי גופא אינו מוסיף „גלות\", משמע ששייך לא רק להחילוק דתנאים ואמוראים — בתראי דאמוראי לגבי תנאי, כ״א (גם) לבתראי דבבלי לגבי ירושלמי."],["26","26","ב, א ואילך."],["27","27","לשון (פי׳ המיוחס לרש״י בע״י תענית שם. וכ״ה בהגהות הב״ח לרש״י בש״ס שם."],["28","28","ראה סנהדרין יז, ב: אמרי׳ במערבא רבי ירמי׳. וראה תוד״ה נראין (קדושין מו, רע״א)."],["29","29","דברי הגמרא הנ״ל נתבארו בארוכה בלקו״ש תבא תנש״א."]]],[1300241186,"ד. מ׳דארף אבער פארשטיין בעצם הענין בנדו״ד:\nוויבאלד אז ס׳איז דא חרטה און די שלילה פון העיקר והסיבה (יצה״ר) האט לכאורה קיין ארט ניט צו מפרט זיין דעם מסובב (גלות), וואס איז שוין מושלל בדרך ממילא דורך דער חרטה אויף זיין סיבה30.\nלכאורה וואלט מען געקענט דאס מבאר זיין דורך באווארענען נאך א שאלה — ניט גלאטקייט עכ״פ: ווי פאסט אריין גלות צווישן די זאכן וואס הקב״ה „מתחרט שבראם\"? — גלות איז דאך ניט קיין בריאה וואס דער אויבערשטער האט באשאפן ווי א מציאות פאר זיך, אזוי ווי יצה״ר און די איבעריקע, נאר איר גאנצע מציאות איז אפהענגיק און פארבונדן מיט הנהגת האדם (ווען דער יצה״ר רעדט זיי איין צו טאן עבירות און זיי זיינען דערנאך ניט חוזר בתשובה), קומט אויס אז די גאנצע מציאות פון גלות איז תלוי אין דער הנהגה של בנ״י.\nומשום זה וואלט מען לכאורה געדארפט זאגן, אז חרטה אויף דער בריאה פון גלות מיינט ניט — אויף בריאת העונש סתם אויף זייערע חטאים, נאר דאס וואס דער אויבערשטער האט באשאפן (א דבר חדש) לעונש — גלות, עס זיינען דאך „הרבה דרכים למקום\" ווי אזוי צו מעניש זיין פאר חטאים ועוונות, און ווי מ׳געפינט אין דער תוכחה גופא כמה עונשים ויסורים ר״ל, וואס קומען אויף העדר קיום התורה ומצות31.\nה. ועפ״ז י״ל אז דאס איז דער פירוש פון „ארבעה מתחרט עליהן הקב״ה שבראם\" (אין בבלי) וואו גלות ווערט גערעכנט באזונדער, וואָרום אע״פ אז גלות איז א מסובב פון יצה״ר (ער קומט אלס עונש אויף חטאים וואס סיבתם איז דער יצה״ר): אבער גלות איז ניט דבר המוכרח דורך (הסתת) היצה״ר, נאר ס׳איז א בריאה וחידוש בפ״ע32 וואס דער אויבערשטער האט באשאפן אלס נאך אן עונש, און אויף דעם איז די חרטה בפ״ע.\nועפ״ז ווערט אויך פארענטפערט וואס דער בבלי איז מקדים (לגירסת הש״ס) גלות פאר יצה״ר14 — אע״פ אז בפועל קומט גלות נאך דעם ווי דער יצה״ר איז פועל פעולתו — להדגיש, אז דאס וואס הקב״ה מתחרט אויף גלות, מיינט ניט (בלויז) אויף דעם גלות בפועל (אלס עונש פאר חטאים נאך דער שליטת היצה״ר, נאר בעיקר) אויף דעם עצם בריאה פון גלות (אלס עונש), כנ״ל33.\nו. עפ״ז קומט אבער לכאורה אויס אז דער הפרש צווישן בבלי און ירושלמי איז (ניט נאר אין אופן הלימוד — בכלל אדער בפרטיות, נאר) אן ענין של פלוגתא: לדעת הירושלמי איז די חרטה בלויז אויף גלות בפועל — ווייל דאס איז נכלל אין דער חרטה („תהא\") אויפן",[["30","30","ראה חדושי אגדות מהרש״א סוכה שם, דמפרש הראי׳ ע״ז שמתחרט על יצה״ר מהכתוב (מיכה ד, ו) אשר הרעותי . . דכתיב ברישא דקרא והנדחה אקבצה ואמר דלכך אקבצם מהגלות כי אני מתחרט על שבראתי יצה״ר שעל ידו באו לגלות."],["31","31","להעיר ממרז״ל (שמו״ר פנ״א, ז. ועד״ז בב״ר פמ״ד, כא. וש״נ) „במה אתה מבקש שישתעבדו בניך בגיהנם או בגליות\"."],["32","32","להעיר ממה שנתבאר (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181412\" data-slug=\"likkutei-sichot\" data-id=\"1300181412\">לקו״ש חי״ח ע׳ 403</a> ואילך) במאמר הגמרא (כתובות קי, סע״ב), ובדעת הרמב״ם (הלכות מלכים פ״ה הי״ב) „כשם שאסור לצאת מהארץ לחו״ל כך אסור לצאת מבבל לשאר הארצות כו׳\", שהקב״ה בחר בבבל כהמקום לזמן הגלות ע״ד בחירת א״י לזמן הגאולה, עיי״ש בארוכה."],["33","33","וי״ל ע״ד שתשובה קדמה לעולם (פסחים נד, א. תנא דבי אליהו רבה פל״א. ב״ר פ״א, ד. ועוד)."]]],[1300241187,"יצה״ר, אבער ניט אויף עצם הבריאה פון גלות (וויבאלד דער ירושלמי ברענגט ניט גלות), משא״כ לדעת הבבלי, וכנ״ל.\nאויך איז נאך אלץ ניט מוסבר דער סדר הענינים שבבבלי: ס׳איז דא א טעם, כנ״ל, פארוואס ער איז מקדים גלות פאר יצה״ר — עס איז אבער ניט מובן פארוואס מוז מען שטעלן גלות אלס ערשטן פון אלע ד׳ דברים34 (און אזוי אויך אין די ראיות פון די פסוקים).\nז. וי״ל הביאור בכל זה:\nדער בבלי און דער ירושלמי טיילן זיך פאנאנדער ניט בלויז אין מספר הדברים (אין בבלי ווערן גערעכנט פיר זאכן און אין ירושלמי — דריי), נאר ס׳איז דא אויך א חילוק ביניהם אין לשון ובמילא אויך אין ענין ותוכן:\nדער לשון הבבלי איז: „ארבעה מתחרט עליהן הקב״ה שבראם כו׳\", און דער לשון הירושלמי איז „שלשה ברא הקב״ה ותהא שבראן\":\nד.ה. אין בבלי איז עס געבראכט אלס איין ענין: דער אויבערשטער האט „חרטה\" (וואס ער האט זיי באשאפן): און אין ירושלמי זיינען מודגש צוויי ענינים: א) דאס וואס „בראם הקב״ה\", און ב) דאס וואס „תהא שבראן\".\nאון דאס איז א חילוק בתוכן: מובן ופשוט, אז חרטה למעלה איז ניט כפשוטה, ח״ו, אז ער איז משנה דעתו ומתחרט ח״ו אויף א זאך וואס ער האט געטאן35, נאר מיט דעם ווערט ארויסגעבראכט אז עס איז דא אן ענין שלילי בזה: לאידך, איז מובן, אז דערמיט וואס מ׳זאגט אז דאס איז א זאך וואס „ברא הקב״ה\"36 איז מען מדגיש דעם צד הטוב שבזה.\nקומט אויס, אז אין בבלי רעדט זיך נאר וועגן דעם צד השלילי, וועגן דעם היפך הטוב, וואס איז דא אין די פיר ענינים, און אין ירושלמי איז צוזאמען מיט דעם אויך מודגש דער צד הטוב שבהן.\nאט דער ענין (ווי יעדער ענין) וואס שטייט אין תורה (אין תורה שבכתב צי אין תורה שבע״פ), איז דאס ניט (נאר) געזאגט געווארן סתם צו דערציילן דעם אויבערשטנ׳ס הנהגה און יחס (וכ״ש — שלילי) צו די נבראים וואס ער האט באשאפן, נאר עס איז (נוגע צו וויסן די מציאות פון די נבראים בכדי ארויסנעמען פון דעם) א הוראה37 אין עבודת האדם לקונו.\nאון אין דעם באשטייט דער אונטערשייד צי ס׳ווערט בלויז געזאגט אז „ארבעה מתחרט עליהן הקב״ה שבראם\", אדער מ׳איז מקדים אז „שלשה ברא הקב״ה\":\n„מתחרט עליהן\" ותו לא — ברענגט ארויס אז די ד׳ דברים זיינען ניט קיין אמת׳ע מציאות, אז זיי וועלן סו״ס בטל ווערן, ווייל „מתחרט\" — איז זיי ניט דער רצון פנימי פון אויבערשטן.\nאבער בשעת מען זאגט אלס הקדמה להענין „ברא הקב״ה\", איז דאס מדגיש אז אין זיי איז פאראן די בריאה — ובמילא דער רצון — ה׳, ובמילא האבן זיי אין זיך אן ענין פון נצחיות (מצד דעם ניצוץ אלקי שבהם) ווי ביי אלע ענינים וואס „ברא הקב״ה\"; נאר צוזא־",[["34","34","והרי לכמה גירסאות בא גלות אחר כשדים וישמעאלים ולפני יצה״ר (כנ״ל הערה 14)."],["35","35","ענין הנחמה וחרטה אצל הקב״ה ע״ד הפשט — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151027\" data-slug=\"likkutei-sichot\" data-id=\"1300151027\">לקו״ש חט״ו ע׳ 27</a> ואילך. וש״נ."],["36","36","ובפרט ע״פ הנ״ל (ס״א) שכל מה שברא הקב״ה בעולמו לא בראו אלא לכבודו."],["37","37","דתורה מלשון הוראה (זח״ג נג, ב)."]]],[1300241188,"מען דערמיט איז מען מוסיף אז זיי אנטהאלטן אין זיך אויך א צד שלילי,\nואדרבא — דער ענין אין זיי איז ניט קיין מציאות אמתית און וועט בטל ווערן.\nח. עפ״ז איז מובן דער טעם השינוי צווישן בבלי און ירושלמי:\nאין ירושלמי רעדט זיך וועגן דברים וואס האבן אין זיך א נצחיות, ווייל דער אויבערשטער האט זיי באשאפן („ברא הקב״ה\"), און דערפאר וועלן זיי האבן א קיום אויך לעת״ל, ס׳איז נאר וואס דער צד הלא־טוב שבהם, דער ענין שלילי וועט בטל ווערן — „ותהא שבראן\".\nאון דעריבער איז דער ירושלמי משמיט דעם פרט פון גלות, היות אז גלות בפועל איז כולו אן ענין שלילי און וועט אינגאנצן בטל ווערן לעת״ל: און ער רעכנט נאר ג׳ דברים: „כשדים וישמעאלים ויצה״ר\", ווייל אויך לעת״ל וועלן זיין אוה״ע: זיי וועלן אבער דאן זיין אין אן אופן וואס זיי וועלן נאר ניט מזיק זיין אידן ח״ו, נאר אדרבא, זיי וועלן נתהפך ווערן לטוב, און וועלן נאך ארויסהעלפן די אידן, כמ״ש38 „ועמדו זרים ורעו צאנכם\", וכמ״ש39 „אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה׳ לעבדו שכם אחד\",\nאון אזוי איז אויך בנוגע יצה״ר, אז לעת״ל, וועט בטל ווערן דער ענין הרע פון יצה״ר, אבער זיין כח וחיות וועט נתהפך ווערן לטוב און וועט זיין לעת״ל.\nוע״ד ווי ס׳געווען קודם החטא — שמש גדול40. —ועוד יותר, בדוגמת היתרון שבא ע״י תשובה.\nד.ה. דאס איז ניט (נאר) צוליב דער תועלת ומעלה אין יצה״ר וואס דורך (מתגבר זיין זיך אויף) אים קומט א אידן צו א העכערע מעלה ומדריגה (וואָרום כעין זה איז אויך דא אין גלות), נאר צוליב דעם וואס דער יצה״ר עצמו וועט זיין קיים לעת״ל ווייל ער וועט נתהפך ווערן לטוב41, און ע״ד ווי עס שטייט אין ירושלמי42 בנוגע צו אאע״ה „ומצאת את לבבו נאמן לפניך\"43, אז אברהם אבינו „עשה יצר הרע טוב\"44. ועד״ז בא יעדן אידן בנוגע לפועל ולפי שעה: בכל לבבך — בשני יצריך45.\nאין בבלי אבער איז ער מדגיש דעם ענין השלילי שבהם — „מתחרט עליהן\" — וואס וועט סו״ס בטל ווערן, ד.ה. ער רעדט וועגן דעם לא־טוב שבהם וואס וועט בטל ווערן:\nדעריבער איז דער בבלי מוסיף אויך דעם פערטן פרט, גלות, און מהאי טעמא גופא שטעלט ער אים אלס ערשטן — ווייל דער ענין השלילה וביטול איז ביי גלות באופן יותר מוחלט ווי ביי די אנדערע פרטים: אע״פ אז גלות ברענגט אידן צו א העכערע מעלה ושלימות (וואס לולי הגלות וואלטן זיי ניט געקענט דערגרייכן צו אזא גילוי פון כח המס״נ וכו׳, כמבואר בכ״מ<sup data-n=\"46\">46</sup> — איז",[["38","38","ישעי׳ סא, ה."],["39","39","צפני׳ ג, ט. רמב״ם ספי״א מהל׳ מלכים."],["40","40","סנהדרין נט, ב."],["41","41","ראה בהנסמן בהערה 16. ד״ה חייב אדם לברך תרל״ח פל״א (ושם הובא גם מאמר הגמ׳ שבסוכה — ראה לקמן הערה 48). ובכ״מ."],["42","42","ברכות פ״ט, ה״ה."],["43","43","נחמי׳ ט, ח."],["44","44","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא</a> פ״ט-יו״ד. פכ״ז (לד, סע״א ואילך). ובכ״מ."],["45","45","ואתחנן ו, ה. ברכות נד, א. ספרי ופרש״י שם."],["46","46","ראה בארוכה ספר המאמרים אידיש בתחלתו. ד״ה אין הקב״ה בא בטרוניא תרפ״ה (סה״מ קונטרסים (ח״ג) ע׳ קיט ואילך). ד״ה אני ישנה תש״ט. ובכ״מ."]]],[1300241189,"דאס אבער א תועלת וואס קומט אלס תוצאה פון גלות, אבער דער גלות גופא, די מציאות הגלות וועט אינגאנצן בטל ווערן לעת״ל עס איז א גאולה נצחית שאין אחרי׳ גלות47.\nאון מיט דער הקדמת הגלות איז דער בבלי בא ללמד אויף די איבעריקע ג׳ דברים48, אז דא רעדט זיך ניט וועגן ענין הטוב שבהם, דאס וואס „הקב״ה בראם\" (וואס מצד דעם האבן זיי אין זיך אן ענין של נצחיות), נאר וועגן דעם חלק השלילי שבהם49, דאס וואס האט ניט קיין מציאות אמיתית און וועט אינגאנצן בטל ווערן50.\nט. וי״ל אז אויך דער ביאור איז פארבונדן מיטן כללות׳דיקן חילוק וואס מ׳געפינט בכ״מ צווישן שיטת בבלי און שיטת הירושלמי:\nשוין גערעדט כמה פעמים51 אז לשיטת הבבלי רעכנט מען זיך בעיקר מיט׳ן מצב ווי ער איז בהווה, און לשיטת הירושלמי קוקט מען (בעיקר) אויפן מצב שבעתיד (און דאס איז מכריע און גובר אויפן מצב שבהוה).\nאון דערמיט איז אויך פארבונדן דער חילוק הנ״ל, צי מ׳רעדט בלויז וועגן „מתחרט עליהן\" וואס ברענגט ארויס דעם ביטול (פון דעם צד השלילי) שלהם, אדער מ׳רעדט אויך (ובהדגשה) וועגן דעם צד הטוב שבהם, דאס וואס „ברא הקב״ה\", וואס דערפאר וועלן זיי",[["47","47","ראה מכילתא בשלח טו, א. שמו״ר פכ״ג יא (וביפ״ת שם). תוד״ה ונאמר פסחים קטז, ב."],["48","48","להעיר מהלשון בד״ה חייב אדם לברך שם: והן אמת שארז״ל כו׳ ארבעה הקב״ה מתחרט כו׳ (ראה הערה 12) ואחד מהן הוא היצה״ר כו׳, מאמר זה צריך פירוש, אבל עכ״פ נראה שנברא כדי לבחון בו האדם כו׳, ולאח״ז מבאר „או שאדרבא עי״ז יהי׳ בירור כו׳ יצה״ר לאחר הבירור\"."],["49","49","ומתאים לכללות המשך הסוגיא שלפנ״ז בבבלי שם, שמתחיל (נב, רע״א) „ומה לעת״ל . . שאין יצה״ר שולט בהם (כדאמר קרא (יחזקאל לו, כו) והסירותי את לב האבן — פרש״י שם) . . יצה״ר שנהרג . . לעת״ל . . ליצה״ר ושחוטו כו׳\" ומאריך בהגמרא בפרטיות בהרעה שהיצה״ר גורם להאדם וכו׳ עיי״ש בארוכה, משא״כ בירושלמי תענית שם. [ולהעיר שבירושלמי שם לפני מאמר זה אי׳ ש„אילולי שאמרו ישראל בהר הכרמל (מ״א יח, לט) ה׳ הוא האלקים ה׳ הוא האלקים לא ירדה האש כו׳\" (ראה קה״ע שם), והרי ה׳ הוא האלקים ב״פ דאליהו ענינו — אתהפכא ועבודת התשובה כידוע (ראה אוה״ת מ״א שם)]. ועפ״ז י״ל שהחילוק בין דעת הבבלי והירושלמי הוא לא רק שבבבלי מדובר רק בחלק השלילי* שבהם, ובירושלמי הוא גם בצד הטוב, אלא שלדעת הבבלי „כשדים וישמעאלים ויצה״ר\" יתבטלו לגמרי לעת״ל בדוגמת הגלות (כי אף שבנוגע לכללות האומות נאמר „אז אהפוך אל עמים גו׳\" כנ״ל, האומות שכל כולם רע ע״ד עמלק שאחריתו עדי אובד (בלק כד, כ. ונתבאר בד״ה ראשית גוים עמלק תר״פ. ד״ה זכור תרצ״ד (בסה״מ קונטרסים ח״ב). ובכ״מ. וראה ס׳ הליקוטים (צ״צ) ע׳ עמלק. וש״נ) יתבטלו כהיצה״ר), ולדעת הירושלמי גם ג׳ אלו יתהפכו לטוב כנ״ל. או י״ל (כדי שלא לאפושי במחלוקת, ובפרט במציאות), דגם לדעת הבבלי יהי׳ אנשי כשדים וישמעאלים קיימים לעת״ל, אבל לא יהיו קיימים בתור אומות, ועצ״ע. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231172\" data-slug=\"likkutei-sichot\" data-id=\"1300231172\">לקו״ש חכ״ג ע׳ 172</a> ואילך."],["50","50","וי״ל דהחילוק בין הבבלי והירושלמי הוא גם (בסגנון תורת החסידות) חילוק באופן הגילוי דאחדות הוי׳, אין עוד מלבדו, שע״י הקליפות „כשדים כו׳ יצה״ר\" (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051079\" data-slug=\"likkutei-sichot\" data-id=\"1300051079\">לקו״ש ח״ה ע׳ 67</a>, וש״נ): בבבלי (בחי׳ או״ח מלמטה למעלה — ראה בהנסמן לקמן הערה 54) מבואר שהרע אין לו שום מציאות, בחי׳ „העדר\", ובמילא אינו בסתירה לאחדות הוי׳, וזהו שמתחרטים עליהם, שסו״ס מתבטלים: ובירושלמי (בחי׳ אור ישר מלמעלה למטה — ראה בהערה שם) מבואר שגילוי האחדות הוא (לא רק בזה שכאשר מתבטל חלק הרע נראה דאין עוד מלבדו, כ״א שהגלוי הוא) בהם גופא שהם עצמם (מצד הנצוצי קדושה שבהם) נהפכים לטוב. וראה לקו״ש חט״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161426\" data-slug=\"likkutei-sichot\" data-id=\"1300161426\">ע׳ 413</a> ואילך. ואכ״מ."],["51","51","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041337\" data-slug=\"likkutei-sichot\" data-id=\"1300041337\">לקו״ש ח״ד ע׳ 1338</a>, <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151466\" data-slug=\"likkutei-sichot\" data-id=\"1300151466\">חט״ו ע׳ 453</a> ואילך. וש״נ. לקמן ע׳ 243. *) אבל מה שנתבאר בלקו״ש חכ״ג (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231100\" data-slug=\"likkutei-sichot\" data-id=\"1300231100\">שם ע׳ 100</a>) בפי׳ ענין „וישחטם\", אי״ז ביטול המציאות, עיי״ש."]]],[1300241190,"לעת״ל נתהפך ווערן לטוב:\nאז ענין וואס וועט בטל ווערן לעתיד איז ניט קיין מציאות אמיתית אויך בשעת קיומו בהווה [וואס דערפאר געפינט מען אז נהרות וואס ווערן אויסגעטריקנט איינמאל אין זיבן יאר ווערן אנגערופן „נהרות המכזבין\" (און זיי זיינען פסול לקידוש מי חטאת, ווייל זיי זיינען ניט קיין „מים חיים\")52, ויבאלד אז זיי וועלן זיכער נפסק ווערן בעתיד, נאך שבע שנים, ווערן זיי אויך ברגע הראשון פון זייער קיום ניט גערעכנט אלס א מציאות אמיתית].\nקומט אויס, אז דער העדר המציאות שבהם איז זייער מציאות ומצב־בהווה (איידער זיי ווערן בטל), משא״כ דער צד הטוב, דאס וואס זיי וועלן נתהפך ווערן לטוב איז א חידוש, היפך טבע מציאותן בזה״ז, וועט זיך ערשט אויפטאן לעת״ל — א מצב שבעתיד.\nאון דערפאר איז דער בבלי מדגיש דעם צד השלילי פון די ד׳ דברים, ווייל ער גייט לשיטתו אז מ׳רעכנט זיך מיטן הווה.\nיוד. און דאס אלץ איז עולה בקנה אחד מיטן חילוק כללי צווישן בבלי און ירושלמי:\nוועגן תלמוד בבלי ווערט געזאגט: „במחשכים הושבני . . זה תלמודה של בבל\"53, אז אין „בבל\" איז א מצב פון העלם והסתר, וואו מ׳דארף מברר זיין דעם אור מן החושך; און ירושלמי איז בחי׳ אור [און ווי ס׳איז מבואר בכ״מ54, איז דאס גופא דער טעם וואס אין ירושלמי רעדן זיך די ענינים בקיצור ובכללות, אן ריבוי פלפולים ושקו״ט, און אין תלמוד בבלי רעדן זיי זיך בפרטיות ובאריכות השקו״ט וקושיות וכו׳: וע״ד דוגמא55, בשעת מען געפינט זיך אין אן ארט וואו עס איז ליכטיג, דערזעט מען גלייך די זאך וואס מען זוכט, משא״כ בשעת מען געפינט זיך בחושך, דארף מען טאפן און זוכן וכו׳ און ס׳נעמט אריכות זמן ביז מ׳געפינט וואס מ׳זוכט — און אזוי איז דאס אויך אין זוכן בירור סברא, דין וכו׳ דורך שכל]56.\nאון דעריבער, ווען ס׳איז א מצב פון אור — תלמוד ירושלמי, באלייכט דאס און מען זעט בקלות (לפ״ע) די פנימיות און דעם אמת פון דער זאך וואס דאס איז ווי זי וועט זיין (לעת״ל) לנצח, וואס דעמאלט וועט עס נתהפך ווערן לטוב, עס וועט נתגלה ווערן דאס וואס „ברא הקב״ה\":\nבשעת אבער ס׳איז אין מצב פון במחשכים בשכל האדם דארפן האבן אופן הלימוד פון תלמוד בבלי — מען זעט ניט פנימיות הענינים, דאס וואס וועט ארויסקומען לאחר זמן, נאר ווי דער מצב בהווה, דעם ענין השלילי בזה און אין עם דארפן הארעווען (אין א דבר חשוך היפך הטוב, וואס איז ניט קיין אמת׳ע מציאות) ביז צו אויסגעפינען אז ער איז ניט א מציאות אמתי וכו׳.\nיא. די הוראה וואס מ׳נעמט ארויס פון כל הנ״ל:\nלכל לראש דארף מען שטענדיק וויסן און געדענקען אז דער ענין הגלות איז",[["52","52","פרה פ״ח מ״ט."],["53","53","סנהדרין כד, א."],["54","54","ראה שערי אורה ד״ה בכ״ה בכסלו פנ״ד ואילך. המשך תרס״ו ד״ה ויתן לך. סה״מ תש״ח ע׳ 121 ואילך."],["55","55","ראה מכ׳ הנדפס לקמן בהוספות (ע׳ 367) לענין החילוק דראשונים ואחרונים."],["56","56","במקומות שבהערה 54 מבואר מעלת תלמוד בבלי בזה שדוקא ע״י העלמות וקושיות באים לאור האמת לאמיתתו, אבל הו״ז ע״י יתרון האור מן החושך. ועצ״ע."]]],[1300241191,"פון די זאכן וואס דער אויבערשטער איז „מתחרט\" אויף זיי: גלות איז ניט דער אמת׳ער מעמד ומצב וואס דער אויבערשטער וויל, ח״ו, אז אידן זאלן זיך דארט געפינען. און מען זאגט דאס אידן ווייל ביי זיי דארף זיין „ניט־צופרידנקייט\" מיט גלות: גלות איז אן עונש (מפני חטאינו). ווען א איד פילט, ר״ל, אנדערש און זאגט אז דאס איז א פאסיקער מצב פאר אידן, זאגט ער היפך פון דעם רצון ה׳, וואס הקב״ה מתחרט — און די חרטה איז בכל יום — אפילו בתשעה באב וכיו״ב — און ס׳איז פארשטאנדיק די גרויסע פינסטערניש פון זיין גלות בתוך גלות.\nלאידך אבער, טאר דאס ניט זיין אין אן אופן אז מ׳זאל אריינפאלן אין א מרה שחורה ח״ו, און מען דארף ניט נתפעל ווערן פארן גלות, וויסנדיק אז דאס איז ניט קיין אמת׳ע מציאות, אז ער וועט סו״ס, בקרוב ממש, בטל ווערן. ובפרט אז מען האלט שוין בעיקבתא דמשיחא און עס פאדערט זיך מ׳זאל מער מזרז זיין — אחישנה — פון דעם קץ הגלות דורך מוסיף זיין אין נר מצוה ותורה אור, און דערמיט פארטרייבן נאך שנעלער די פינסטערקייט פון גלות.\nועד״ז קען מען דערפון אויך ארויסלערנען די הוראה ווי אזוי מען דארף פירן זיך מיט אוה״ע (כשדים וישמעאלים): מען דארף פאר זיי ניט נתפעל ווערן, זיי האבן ניט קיין תוקף ומציאות בנוגע זייער התנגדות צו אידישקייט, און דערפאר דארף מען אויך בזמן הגלות בכל עניני יהדות „ריידן\" צו זיי מיטן תוקף המתאים57,\nועד״ז ווי דערציילט אין גמרא58 וועגן דעם אופן ווי גביהה בן פסיסא האט מיט זיי גערעדט.\nאון דאס ברייגנט אז נאך בזמן הגלות ווערט די הנהגה פון אוה״ע באופן פון „והיו מלכים אומניך ושרותיהם מניקותיך\"59, און ווי עס איז שוין געווען בפועל כמה פעמים — ביז א מעשה רב בפועל, וואס דער אויבערשטער האט עס אריינגעשטעלט אין תורה60 — עס זאל זיין א הוראה פון תורת חיים, הוראה בחיים:\nאמר רב אשי א״ל הונא בר נתן זימנא חדא הוה קאימנא קמי׳ דאיזגדר מלכא (מלך פרס הי׳, רש״י) והוה מדלי לי המיינאי ותייתיה ניהלי׳ (זיין גארטל איז געווען אנגעטאן צו הויך, איז „הפשילו (המלך) למטה כדי לנאותו\", רש״י) ואמר לי ממלכת כהנים וגוי קדוש כתיב בכו (וצריכין אתם לנהוג בתפארת של כהנים, דכתיב בהו לא יחגרו ביזע — רש״י) כי אתאי קמי׳ דאמימר א״ל אקיים בך והיו מלכים אומניך — אז א איד פירט זיך אז מ׳זעט אז ער געהערט צו ממלכת כהנים וגוי קדוש — זאגן כל מלכי׳ ארץ אז ער דארף זיין בתפארת61, און זיי קומען פון זיך אליין העלפן אין דעם און טאן אין דעם, און עס ווערט מפורסם בכל קצווי תבל\nוהתורה היא נצחית, און אלס א ליכטיגער וועגווייזער און הוראה62 פאר יעדער אידען, וועלכער איז דאך שטאלץ",[["57","57","ראה דברי כ״ק מו״ח אדמו״ר ג׳ תמוז, תרפ״ז (נדפס בלקו״ד ח״ד תרצב, א. סה״מ תרפ״ז ע׳ קצו. ועוד)."],["58","58","סנהדרין צא, א."],["59","59","ישעי׳ מט, כג."],["60","60","זבחים יט, רע״א."],["61","61","ראה רש״י שם."],["62","62","עפ״ז יומתק מה שלא הפשיל הונא עצמו את אבנטו — כי הוא ע״ד מחז״ל (סנה׳ פב, סע״א) שנעלמה הלכה ממשה בכדי שפנחס יבוא ויטול את הראוי לו (תנחומא בלק כ)."]]],[1300241192,"מיט תורה מורשה קהלת יעקב, ופשיטא אז ער בוקט זיך ניט פאר גוי׳שקייט און פאר גוים\nוביחד מיט דער עבודה פון משנה זיין און מהפך זיין דעם יצה״ר, ביז צו דער מדרי׳ פון „בכל לבבך בשני יצריך\"45, אז שוין איצט בזמן פון „ערב שבת\" איז מען טועם מכל תבשיל ותבשיל63 וואס וועט זיין לעת״ל.\nאון דאס איז מזרז דעם יעוד קץ שם (השם) לחושך64, ביטול הגלות, און עס קומט „מיד\" די גאולה האמיתית והשלימה ע״י משיח צדקנו.\n(משיחות ש״פ חוקת וש״פ בלק ה׳תשמ״א)",[["63","63","מג״א או״ח סר״נ סוסק״א. שו״ע אדה״ז שם ס״ה (מפע״ח שי״ח רפ״ג. שעה״כ ענין טבילת ע״ש)."],["64","64","איוב כה, ג. ונתבאר בשערי אורה ש׳ הפורים ד״ה יביאו לבוש מלכות פצ״ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480286\" data-slug=\"or-hatorah-hb\" data-id=\"8316480286\">אוה״ת מקץ (כרך ה</a>) תתקעד, ב. ד״ה ראשית גוים עמלק תר״פ."]]],[1300241193,"בתור הקדמה צו הבא לקמן:\nמובן ופשוט, אז ברוב הענינים ככולם, איז דא כללות הענין און זיין תוכן ונקודה פנימית, און זיינע פרטים ופרטי פרטים,\nובמיוחד אין אזא ענין עקרי ווי ח״י אלול,\nולכל לראש — אויך בהתבוננות אין א פרט, קומט דער זכרון עכ״פ פון זיין תוכן ונקודה הפנימית ביז צו אראפבריינגען דאס אין א „בכן״ ובמעשה, וואס המעשה הוא העיקר\nאזוי אויך בענין ח״י אלול — וואס לקמן* קומט א שקו״ט בתורת הבעש״ט וועלכע איז געזאגט געווארן אין איינעם פון די ח״י אלול׳ס,\nאיז דאס לאחר ווי ישים לנגד עיניו ויתבונן אין דער נקודה הפנימית שבזה, וועלכע דריקט זיך אויס ב„שמו אשר יקראו לו בלה״ק״א — ח״י אלול, ובלשון הרב נשיא דורנו, כ״ק מו״ח אדמו״ר ב:\nא) ח״י אלול איז דער טאג וואס האט געבראכט און ברענגט א לעבן אין אלול. ב) ח״י אלול גיט א חיות אין דער עבודה פון אני ג לדודי ודודי לי ד.\nאון מען קען מוסיף זיין בדרך אפשר, אז די עבודה כללית פון אני לדודי (וועלכע בריינגט דעם כללות הענין פון ודודי לי) טיילט זיך אין די פרטים, וועלכע זיינען אויך מרומז בר״ת פון אלול:\nאלול — ר״ת: אנה לידו ושמתי לך ה, ענין ערי מקלט. ובעבודת האדם. זהו קו התורה, כי דברי תורה קולטין הן ו.\nאלול — ר״ת: אני לדודי ודודי לי ז, קו העבודה היא התפלה ח, ובפרט בימינו אלו שאין לנו אלא עבודה שבלב זו תפלה ט, שתופל י ומחבר את ישראל לאביהם שבשמים.\nאלול — ר״ת: איש לרעהו ומתנות לאביונים יא, קו דגמילות חסדים.\nובתור הקדמת ויסוד לכל קוין אלו\nאלול — ר״ת: (ומל ה׳ אלקיך) את לבבך ואת לבב (זרעך) יב — ענין התשובה.",[["","","*) ס״ה ואילך. א) שער היחוד והאמונה פ״א. ב) לקוטי דיבורים ח״ג ע׳ 946. ס׳ השיחות תש״ה ע׳ 122. ג) שה״ש ו, ג. — ר״ת אלול (אבודרהם סדר תפלת ר״ה. פע״ח שער ר״ה פ״א. שער הפסוקים עה״פ. ועוד). ד) וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041350\" data-slug=\"likkutei-sichot\" data-id=\"1300041350\">לקו״ש ח״ד ע׳ 1351</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091364\" data-slug=\"likkutei-sichot\" data-id=\"1300091364\">ח״ט ע׳ 337</a> ואילך. חי״ד ע׳ 347 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191263\" data-slug=\"likkutei-sichot\" data-id=\"1300191263\">חי״ט ע׳ 250</a> ואילך. ועיי״ש שהב׳ נוסחאות הם בהתאם להב׳ ענינים שביום זה: יום הולדת דהבעש״ט — מייסד תורת החסידות הכללית ויום הולדת דאדה״ז — מייסד תורת חסידות חב״ד. ה) פרי עץ חיים שם. שער הפסוקים שמות כא, יג. ראה ג״כ לקו״ש ח״ב <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021347\" data-slug=\"likkutei-sichot\" data-id=\"1300021347\">ע׳ 623</a>. ו) מכות י, א. ז) ראה לעיל הערה ג. ח) ראה ספר המצות להרמב״ם מ״ע ה׳. ובכ״מ. ט) תענית ב, א. י) ראה רש״י בראשית ל, ח, ובאור התורה שם. יא) בס׳ ערוגת הבושם בשם ס׳ אמרכל. יב) בעל הטורים דברים ל, ו. *) ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480073\" data-slug=\"or-hatorah-hb\" data-id=\"8316480073\">אוה״ת בראשית ח״ה תתסז, ב</a> ואילך. ויחי שפ, א. המו״ל."]]],[1300241194,"<h3>ח״י אלול</h3>\nא. ח״י אלול איז דער יום הולדת פון די שני המאורות הגדולים: מאנטאג ח״י אלול תנ״ח איז דער יום ההולדת פון דעם בעל שם טוב, און מיטוואך ח״י אלול תק״ה איז דער יום ההולדת פון רבינו הזקן1.\nדער ענין, אז אין יום הולדת פון א צדיק איז א זמן פון שמחה, שטייט בכמה מקומות בחז״ל — בפרט לגבי יצחק אבינו2 און משה רבינו3, ביז אז דאס האט אויפגעטאן בפועל במעשה רב, ווי עס שטייט אין מדרש אז דער טעם וואס מ׳האט דעם משכן אויפגעשטעלט שפעטער, און ניט גלייך נאך דעם ווי ער איז פארטיק געווארן — „מפני4 שחשב הקב״ה לערב שמחת המשכן בשמחת היום שנולד בו יצחק אבינו לפי שבאחד בניסן5 נולד יצחק אמר הקב״ה הריני מערב6 שמחתכם בשמחה״.\nנאך מער: מ׳געפינט אז דער יום הולדת פון משה רבינו, ז׳ אדר, האט גע׳פועל׳ט דעם ביטול גזירת המן וואס איז אויסגעפאלן אויף חדש אדר — „ולא הי׳ יודע שבשבעה באדר מת ובשבעה באדר נולד״7.\nאעפ״כ געפינט מען ניט, אז דער יום הולדת8 זאל ווערן א יום טוב ויום שמחה בגלוי ובפרסום, אין הנהגה במעשה בפועל לכל ישראל9 [ובנוגע לז׳ אדר איז, ע״פ שו״ע10, ז׳ אדר א יום תענית מצד שמת בו משה].\nבנוגע אבער דעם יום הולדת פון בעש״ט און דעם אלטן רבי׳ן בח״י אלול איז נתגלה געווארן ע״י נשיא דורנו בשם אביו כ״ק אדמו״ר מהורש״ב נ״ע, אז דאס איז א יום שמחה ביז באמירת „גוט יום טוב״11, און דער רבי דער שווער האט דעם יום טוב מגלה געווען צו אלע אידן12.\nאון ויבאלד אז ענינים פארבונדן מיט תורה זיינען בדיוק, איז מובן, אז די",[["1","1","שיחת כ״ק מו״ח אדמו״ר (סה״ש תש״ג ע׳ 141) — בשם אביו."],["2","2","תנחומא ס״פ פקודי. שמו״ר פנ״ב, ב."],["3","3","מגילה יג, ב. וראה ר״ה (יא, א) בנוגע לחודש שנולדו בו האבות. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051098\" data-slug=\"likkutei-sichot\" data-id=\"1300051098\">לקו״ש ח״ה ע׳ 86</a> בהערות ושוה״ג (וש״נ) בנוגע ליום הולדת דכל אחד מישראל. וראה סה״ש תשמ״ח ח״א ע׳ 331 ואילך. ח״ב ע׳ 398 ואילך."],["4","4","תנחומא שם. וראה גם שמו״ר שם."],["5","5","ראה עץ יוסף שם. ובשמו״ר שם נזכר רק החודש (וראה יפ״ת שם)."],["6","6","ראה יפ״ת לשמו״ר שם, דאי״ז סתירה להכלל דאין מערבין שמחה בשמחה."],["7","7","מגילה שם. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161343\" data-slug=\"likkutei-sichot\" data-id=\"1300161343\">לקו״ש חט״ז ע׳ 343</a> ואילך."],["8","8","יום הולדת סתם, משא״כ כשנעשה בר מצוה (זהר חדש טו, ד כביום החופה), בר ששים (מו״ק כח, א) ועוד. — וראה שיחת י״א ניסן תשכ״ב (ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051144\" data-slug=\"likkutei-sichot\" data-id=\"1300051144\">לקו״ש ח״ה ע׳ 132</a> ואילך)."],["9","9","ולהעיר מנזיר יד, א ובתוד״ה אמר כמשה שם „או כיום הולדו קאמר ושמחה קבל עלי׳״ (ועד״ז בפי׳ הרא״ש ותוס׳ הרא״ש בשטמ״ק שם), הרי לא מצינו מפורש ברזיל שהי׳ יום שמחה אחר מיתת משה. וראה בארוכה לקו״ש חט״ז שם."],["10","10","טושו״ע או״ח סי׳ תקפ ס״ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161342\" data-slug=\"likkutei-sichot\" data-id=\"1300161342\">לקו״ש שם ע׳ 342</a> הערה 5."],["11","11","סה״ש שם ע׳ 140 ואילך. ולהעיר שבשנה זו (ח״י אלול — תשמ״ג) נתמלאו ארבעין שנין משנה ההיא (ח״י אלול — תש״ג). וראה פרש״י סוף פרשתנו (תבא) — מע״ז ה, ב."],["12","12","ראה סה״ש שם ע׳ 142. וראה גם שם ע׳ 89 ואילך. ס״ע 185 ואילך. סה״ש תש״ה ע׳ 122 ואילך. ועוד."]]],[1300241195,"שמחה ועילוי פון דעם יום הולדת בח״י אלול, איז ניט נאר ווייל דורך דעם בעש״ט און אלטן רבי׳ן האט זיך אויפגעטאן א נייער גילוי אין תורה ועבודת ה׳ — דער גילוי פון תורת החסידות הכללית ותורת חסידות חב״ד צו כלל ישראל — נאר אויך ווייל דער חידוש ענין השמחה ביום הולדת איז פארבונדן במיוחד מיטן בעש״ט און דעם אלטן רבי׳ן און תורת החסידות שנתגלתה על ידם.\nאון נאך מער: די שייכות איז צו זיי ביידע צוזאמען. וכלשון אדמו״ר נ״ע וועגן ח״י אלול „היינט איז דער יום הולדת פון אונזערע שני המאורות הגדולים״, ד.ה. אז די נקודת הענין פון אט דעם יום הולדת דריקט זיך אויס דורך ביידע „מאורות הגדולים״ צוזאמען, דעם בעש״ט און רבינו הזקן.\nב. וועט מען דאס פארשטיין בהקדם הביאור בפשטות אין וואס עס באשטייט די שמחה ביום הולדת:\nאיידער דער קינד ווערט געבארן, ווען ער געפינט זיך נאך במעי אמו, האט ער אלע איברים ביז אויך שערות וצפרנים13. נאך מער: ביי אים איז אויך פאראן תנועות האברים, „אוכל ממה שאמו אוכלת ושותה ממה שאמו שותה״14, א.ז.ו.\nואדרבה: בשעת ער איז במעי אמו איז ער אין געוויסע זאכן „שטארקער״ ווי לאחרי שנולד: במעי אמו איז ער שמור15 פון עניני היזק כו׳ בדרך ממילא ע״י אמו, משא״כ נאך דעם ווי ער ווערט געבארן, דארף מען האבן פארשידענע השתדלות׳ן וטרחא אז ער זאל זיין בריא ושלם; (כנ״ל) אוכל מאכילת אמו בדרך ממילא, ועד״ז בנוגע שתי׳ — משא״כ לאחרי שנולד איז דאס פארבונדן מיט טירחא, וכמה פעמים מיט צער פאר דעם תינוק וכו׳.\nועאכו״כ בנוגע לרוחניות (בא א אידן): דער תינוק במעי אמו איז „נר דלוק על ראשו וצופה ומביט מסוף העולם ועד סופו״ און „מלמדין אותו כל התורה כולה״14, אבער „כיון שבא לאויר העולם בא מלאך וסטרו על פיו ומשכחו כל התורה כולה״14, און דערנאך און ערשט „משיתחיל לדבר״, איז „(אביו) מלמדו תורה צוה כו׳״16 און שפעטער „בן חמש למקרא בן עשר למשנה כו׳״ ביז ער קען צוקומען צו דער שלימות לימוד התורה פון „בן ארבעים לבינה״17 — און נאר א מיעוט קומט צו „למד כל התורה כולה״18.\nאיז דאך דער יום הולדת א געוואלדיקע ירידה19 לגבי דעם מצב ווי ער איז אלס עובר במעי אמו — טא וואס איז די שמחה פון א יום הולדת?\nאיז דער ביאור אין דעם20 מובן פון דעם חילוק צווישן אן עובר און א נולד",[["13","13","ראה נדה ל, סע״א — במשנה. ובגמ׳ שם, ב. יבמות פ, רע״ב."],["14","14","נדה ל, ב."],["15","15","להעיר מתנחומא תזריע ג."],["16","16","ל׳ אדה״ז בריש הלכות ת״ת שלו — מסוכה מב, א."],["17","17","אבות ספ״ה."],["18","18","ובל׳ המורה על חידוש (מנחות צט, סע״ב): שאל בן דמה כו׳ כגון אני שלמדתי כל התורה כולה. — וראה הל׳ ת״ת לאדה״ז פ״א ס״ד־ה. פ״ב ס״ב ואילך."],["19","19","ולהעיר מהמובא בדרישה יו״ד סו״ס רסד: מה שנוהגין בשבת לבקר אצל תינוק הנולד משום שהוא אבל על תורתו ששכח כו׳ ונראה משום הכי ניתנה מילה לח׳ ימים אחר שעברו ימי אבילות."],["20","20","בכל הנ״ל ובהבא לקמן — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021325\" data-slug=\"likkutei-sichot\" data-id=\"1300021325\">לקו״ש ח״ב ע׳ 601</a> ואילך."]]],[1300241196,"אין הלכה, ובלשון רש״י21: „כל זמן שלא יצא לאויר העולם לאו נפש הוא וניתן להרגו ולהציל את אמו (המקשה לילד ומסוכנת)״ און דוקא כש„יצא ראשו״ ווערט ער אנגערופן „נפש״, און דעריבער „אין נוגעים בו להורגו דהוה לי׳ כילוד ואין דוחין נפש מפני נפש״*21.\nדאס הייסט: כאטש אז אן עובר האט אלע רמ״ח אברים ומתנענע וכו׳, איז „לאו נפש הוא״, ווייל דער גדר פון א (לעבעדיקן) נפש איז — אז עס זיינען ניט קיין צווי באזונדערע זאכן (א) א מציאות פון א גוף, וואס (ב) אין אים געפינט זיך א נפש און — חיות הנפש, ווי א חפץ וואס ליגט אין א כלי\nנאר22 דאס איז איין לעבעדיקע מציאות. משא״כ אן עובר איז זיין נפש־חיות ניט זיינער*22 נאר של אמו23, און דעריבער ווערט ער ניט אנגערופן נפש, „לאו נפש הוא״.\nאון דאס איז די שמחה ביום הולדת בכל שנה ושנה, ווייל דאס איז דער טאג ווען ער איז געווארן א זעלבסטשטענדיקע לעבעדיקע מציאות, „נפש״.\nג. עפ״ז מובן וואס דער ענין פון יום הולדת אלס יום טוב איז מודגש בא דעם בעש״ט און דעם אלטן רבי׳ן, ווייל דאס איז די נקודת החידוש פון תורת החסידות — חסידות הכללית פון בעש״ט צוזאמען מיט חסידות חב״ד וואס איז נתגלה געווארן ע״י רבינו הזקן:\nס׳איז ידוע24 אז גלות איז „נמשל לעיבור״ און „גאולת ימי המשיח שיהי׳ במהרה בימינו נמשל ללידה״25. און ווי־באלד אז תורת החסידות איז („טועמי׳ חיים זכו״ פון דער גאולה<sup data-n=\"26\">26</sup> א הכנה והקדמה צו דער גאולה, און דורך יפוצו מעינותיך חוצה — הפצת החסידות חוצה — איז אתי מר דא מלכא משיחא (ווי משיח האט געענטפערט דעם בעש״ט)27, איז מובן, אז חידוש תורת החסידות איז מעין דעם (גילוי שבזמן הגאולה —) ענין הלידה.\nקיום התומ״צ קען זיין אויף צווי אופנים:\nא) דער לימוד התורה וקיום המצות אין אן אופן אז דער איד און די תומ״צ זיינען צווי זאכן, ער איז א פרומער איד, איז אריינגעטאן אין לימוד התורה און איז מדקדק במצוה קלה כבחמורה, ער איז אבער מרגיש אז ס׳איז דא אן „ער״, א מציאות בפ״ע (פון תומ״צ), און ער לערנט תורה ומקיים מצות, ביז אז זיי זיינען ממשיך אין עם חיים, זיי ווערן",[["21","21","סנהדרין עב, ב ד״ה יצא ראשו. ועד״ז במאירי שם. סמ״ע חו״מ סי׳ תכה סק״ז (וראה גו״א משפטים כא, כב). וראה רמב״ן נדה מד, ב. ועוד. *21) במשנה אהלות ספ״ז. סנהדרין שם. וראה גם בית האוצר מערכת א כלל יריד אם עובר נק׳ אדם."],["22","22","ראה המשך תרס״ו (דלקמן הערה 61). המשך תער״ב ח״א פר״י. ועוד. *22) כי נפשו עדיין אינה מיוחדת עם גופו (אף שנמצאת בו — ראה סנהדרין צא, ב). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061045\" data-slug=\"likkutei-sichot\" data-id=\"1300061045\">לקו״ש ח״ו ע׳ 45</a> בנוגע ל„תחילת כניסת נפש זו הקדושה כו׳״ (שו״ע אדה״ז או״ח מהדו״ת סוס״ד)."],["23","23","להעיר מרמב״ן שבת קז, ב ד״ה האמרינן: אע״ג דהאי עובר לית בי׳ בדידי׳ נשמה כיון דגידולו תלוי בנשמת אמו העוקרו משם נוטל נשמתו ממנו. וראה מאירי שבת שם: שכל שלא נולד אינו ראוי לומר בו נטילת נשמה כדכתיב כו׳."],["24","24","ראה דרושי וארא — תו״א נה, א ואילך. סה״מ תקס״ב ע׳ קלד ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540781\" data-slug=\"torat-chaim\" data-id=\"2300540781\">תו״ח שמות צו, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300139\" data-slug=\"or-hatorah-hb\" data-id=\"8316300139\">אוה״ת שמות כרך א׳ ע׳ קלט</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470120\" data-slug=\"or-hatorah-hb\" data-id=\"8316470120\">כרך ז — ע׳ ב</a>׳תקפד־ה (עפ״י מו״ג)."],["25","25","ל׳ התו״א שם."],["26","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201173\" data-slug=\"likkutei-sichot\" data-id=\"1300201173\">לקו״ש ח״כ ע׳ 173</a>. וש״נ."],["27","27","כמ״ש הבעש״ט באגרתו הידועה — נדפסה בראש ס׳ כתר שם טוב. ובכ״מ."]]],[1300241197,"„חיינו ואורך ימינו״, ווייל זיי זיינען חכמתו ורצונו פון דעם אויבערשטן מקור החיים,\nדאס איז מעין פון עיבור, א תינוק במעי אמו, וואס דער עובר עצמו, כאטש ער האט אלע אברים וכו׳, ס׳איז דא א לעבעדיקע28 מציאות, איז אבער דער חיות, דער לעבן, ניט זיינער נאר של אמו, זיינע אברים עצמם „הם כמתים״29.\nב) דער בעש״ט האט מגלה ומדגיש געווען30 דעם פנימיות ואמתית ענין פון „אין עוד מלבדו״31 — אז ס׳איז ניטא קיין מציאות זולתו ית׳, ובמילא זיינען ניטא צווי זאכן, א מציאות (דער מענטש) וועלכע איז מקיים תומ״צ — ווארום עס איז ניטא א מציאות אויסער דעם אויבערשטן: נאר עס איז פאראן נאר איין זאך32: דער אויבערשטער תורתו ומצותיו (שהוא וחכמתו ורצונו אחד),\nובמילא איז דא איין מציאות, זיין לעבן איז תורה ומצות.\nבדוגמת ענין הלידה, עס ווערן געבארן ניט צווי זאכן, א גוף מיט א נפש אין עם, נאר איין לעבעדיקע זאך33.\nאון דאס איז מודגש בלשון חז״ל34 „אני לא נבראתי (ס׳איז ניטא קיין בריאה פון מציאות האדם) אלא (נאר — וואס\nאיז באשאפן געווארן) לשמש את קוני (זיין מציאות איז וואס ער איז משמש את קוני)״ —\nווייל בכדי עס זאל זיך אויספירן רצונו וחכמתו של הקב״ה — תורתו ומצוותיו — דארף זיין א איד בעוה״ז הגשמי וואס זאל דאס דורכפירן. קומט אויס, אז ס׳איז מלכתחילה ניט באשאפן געווארן א נברא — א מציאות — בפ״ע, נאר בלויז א פרט אין (אופן קיום) רצון השם, וואס דורך אים פירט זיך אויס רצונו ית׳35.\nולדוגמא מהלכה בפועל — „המוציא אוכלין פחות מכשיעור בכלי פטור אף על הכלי שהכלי טפילה לו״36, ד.ה. כאטש אז די כלי האט א שיעור און אויב מ׳וואלט עס ארויסגעטראגן פאר זיך וואלט מען געווען חייב אויף דער הוצאה — וויבאלד אבער זי איז געווארן א כלי צו די אוכלין שבתוכה איז זי ניט קיין תורה־מציאות בפ״ע, נאר „טפילה לו״ — און די אוכלין זיינען פחות מכשיעורן, איז די הוצאה (כולל אויך הוצאת הכלי) ניט קיין הוצאה. ווארום וויבאלד אז די כוונה פון זיין ארויסטראגן די כלי איז צוליב די אוכלין, איז דאס די מציאות הכלי לאמיתתה, די כלי ווערט א „טייל״ — פון די אוכלין.\nד. אין דעם זעט זיך אויך דער קשר צווישן דעם יום הולדת פון בעש״ט און דעם יום הולדת פון אלטן רבי׳ן:\nדער חידוש פון א נולד וואס ער ווערט א „נפש׳דיקע״ מציאות, איז ניט",[["28","28","להעיר ד„עובר ירך אמו הוא״ (גיטין כג, ב. ובכ״מ). וראה בהנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221060\" data-slug=\"likkutei-sichot\" data-id=\"1300221060\">לקו״ש חכ״ב ע׳ 60</a> הערה 41 — ירך חי."],["29","29","ראה תו״א שם „משא״כ ראשו עם כל אברי הנשימה אין משמשין כלום והרי הם כמתים״."],["30","30","ראה סהמ״צ להצ״צ — מצות אחדות הוי׳ פ״ג: וע״פ עומק יסוד הבעש״ט כו׳."],["31","31","ואתחנן ד, לה."],["32","32","ראה סהמ״צ שם: וזהו אמיתית החסידות."],["33","33","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091247\" data-slug=\"likkutei-sichot\" data-id=\"1300091247\">לקו״ש ח״ט ע׳ 247</a> ואילך."],["34","34","משנה סוף קידושין — בגרי׳ המלאכת שלמה ועוד שם."],["35","35","וראה בהנ״ל גם לקו״ש חלק יו״ד ע׳ 102 ואילך."],["36","36","משנה שבת צג, סע״ב. רמב״ם הל׳ שבת ספי״ח."]]],[1300241198,"(נאר) מצד דעם כללות ענין החיות, נאר (בעיקר) פארבונדן מיט די פרטים:\nדאס וואס אן עובר איז ניט קיין „נפש״ און איז נאר א טפל און פרט (ירך) אין אמו, זעט זיך דאס אז (בעיקר) אין דעם אז ס׳איז ניטא די פעולות פון די חושים ואברים, ווי די גמרא זאגט דארטן „ולמה37 הולד דומה במעי אמו לפינקס מקופל ראשו בין ברכיו כו׳ ואוכל ממה שאמו אוכלת כו׳״, ד.ה. אז כאטש דער עובר האט דעם חיתוך כל האברים, ראש עינים ואזנים, איז „ראשו מקופל ומונח בין ברכיו, שאינו משמש כלום שאינו מחשב ומהרהר״, און אויך „עינים לו ולא יראה ואזנים ולא ישמע כו׳״38.\nאון אין דעם באשטייט דער אויפטו פון א נולד וואס ער ווערט א נפש בפ״ע, ניט נאר בכללות חיות הגוף, נאר עס הויבט זיך אן די פעולה פון זיינע חושים ואברים, יעדערער בפ״ע.\nאון דערפאר (בנמשל) זאגט מען אז ח״י אלול איז דער „יום הולדת״ פון „שני המאורות הגדולים״ בחדא מחתא — ווייל, כידוע39, באשטייט „דער חידוש״ פון רבינו הזקן מיט זיין תורת החסידות40 — חסידות חב״ד — אויף תורת חסידות הכללית פון בעש״ט — אין דעם וואס דער בעש״ט האט אויפגעטאן א חיות כללי אין תומ״צ, דורכן גילוי הנשמה פון יעדן אידן, וואס בכללות האט זיך דאס אויסגעדריקט אין דעם ענין פון אמונה. הגם אז דער כח האמונה נעמט דורך אלע כחות הנפש און פועל׳ט אויף זיי אין אן אופן פון חיות, וואס נעמט זיי דורך, וכמש״נ41 „צדיק באמונתו יחי׳״ — איז עס אבער ניט מכריח אז דער חיות האמונה נעמט דורך יעדן כח אויך אין ענינו הפרטי, נאר דעם ענין הכללי פון יעדן כח, וואס איז פארבונדן מיט דער נקודת האמונה פון דער נשמה.\nולדוגמא: די אמונה קען זיין ניט נאר באופן מקיף, וואס גנבא אפום מחתרתא רחמנא קריא42, נאר עס נעמט אים דורך אויך אין הנהגה בפועל, ביז אז עס פועל׳ט אויך אויף זיין ראית העין, אז תמורת זה וואס מצד עצמו זעט זיך די וועלט אלס א מציאות גשמיית בפ״ע (וואס איז בסתירה צו רוחניות ועאכו״כ צו אלקות), פועל׳ט זיין אמונה אז ער זעט ניט (בראית עין לא בשרי) וועלט אלס א סתירה צו אלקות. די אמונה פועל׳ט אבער ניט אז ער זאל זען43 דעם כח הפועל בנפעל44.",[["37","37","הלשון כאן הוא בתו״א שם. ובגמרא הוא בשינוי לשון וסדר. ואכ״מ."],["38","38","תו״א שם. וראה בשאר מקומות שבהערה 24. ובתו״ח שם (ע״ב): ואבריו כדומם ממש בלתי פועלים שום פעולה כלל. ובתו״א שם: אין משמשין כלום והרי הם כמתים (כנ״ל)."],["39","39","ראה גם לקו״ש חי״ט שם. ובכ״מ."],["40","40","סה״ש תש״ג ע׳ 142."],["41","41","<a class=\"ft-cite\" href=\"#/read/tanya/3401310038\" data-slug=\"tanya\" data-id=\"3401310038\">חבקוק ב, ד</a>. וראה מכות בסופה (כד, א). תניא פל״ג (מב, ב)."],["42","42","ברכות סג, א (גי׳ הע״י)."],["43","43","להעיר ממאמר הצ״צ לפני הסתלקותו (סה״ש תש״ב ע׳ 103) „אז ער זעט ניט דעם גוף נאר אור הנשמה״. ולהעיר ממה שאמר הה״מ (סה״ש תש״ג ע׳ 155) „אין די ג׳ ימים אחרונים פון מסירת הפקדון — הסתלקות — זעט מען נאר דעם דבר הוי׳ וואס אין יעדער דבר גשמי איז דער מהות פון דעם גשמי״, וכן מהמובא בבית רבי ח״א פכ״ב (מו, א) הערה א׳ שאיזה ימים לפני הסתלקותו שאל אדה״ז להצ״צ „האתה רואה את הקורה ונתפלא נכדו מהו״ע השאלה, וא״ל רבינו תאמין לי שאינני רואה עתה כ״א את האין האלקי המחי׳ כו׳״."],["44","44","ע״ד שהה״מ הכיר פרטי כח האומן הפועל שהי׳ סומא בעין אחת (שער האמונה ספכ״ז. ובכ״מ). ובשער האמונה שם: „שא״א להיות זה כ״א במי שיכול להכיר בכל רוחני שבגשם עד כללי׳ אור החיות האלקי הרוחני שהוא כח ומקור לכל פעולה״."]]],[1300241199,"[ע״ד ווי דער חיות כללי, דאס וואס דער מענטש לעבט) דאס נעמט דורך אלע אברים און דאס ווערט פאראיינציקט מיט זיי — דאס איז אבער ניט פארבונדן מיטן ענין פרטי פון יעדן אבר, נאר מיט דער נקודה כללית פון אלע אברים (וואס זיי זיינען א טייל פון גוף האדם)45].\nדער אלטער רבי האט אבער ממשיך געווען א חיות אין יעדן כח פון דער נשמה (און אין יעדער עבודה איז תומ״צ) אויך מצד דעם תוכן פרטי פון דעם כח (ע״ד ווי דער חיות פרטי וואס איז אויסגעמאסטן לויטן ענין פרטי פון יעדן אבר): אז די אמונה קומט אראפ און נעמט דורך אויך שכל האדם, ביז — אז זיין שכל גופא פארשטייט און איז מכריח אלקות,\nביז יעדער פרט פון דעם איד איז געוארן א נפש׳דיקער מצד ענינו: אנהויבנדיק פון חב״ד שבנפשו, דער גילוי אלקות בשכל איז באופן אז אין אים ווערט דערהערט אז כל מציאותו איז אויף צו פארשטיין אלקות; און פון די מוחין קומען די מדות ולפי אופן המוחין46, עס איז נרגש אז כל מציאותא פון מדת האהבה איז כדי עס זאל זיין אהבת ה׳. ועד״ז במדת היראה ושאר מדות. און דעמאלט איז יעדער כח מצד ענינו א נפש׳דיקער, זיין לעבן איז אלקות.\nאון דעריבער האט דער רבי נ״ע געזאגט „היינט איז דער יום הולדת פון אונזערע שני המאורות הגדולים״ בחדא מחתא (און ערשט דערנאך מפרש געווען יעדן איינעם בפ״ע) — ווייל דער\nיום הולדת ווי ער איז נוגע צו יעדן איינעם באופן גלוי ביז אז ער זאגט באמתית „גוט יום טוב״ צו אידן, איז בשעת ס׳איז דא דער גילוי און פעולה פון תורת החסידות הכללית פון בעש״ט דורך און צוזאמען מיט תורת חסידות חב״ד ע״י רבינו הזקן. ווייל דעמאלט טוט זיך אויף אז א איד ווערט א פולשטענדיקע „נפש״־מציאות מיט אלע פרטים.\nה. יעדער ענין שנתגלה ע״י צדיקים ווערט דאס געזאגט לכל לראש בתורתם. איז אויך דער ענין הנ״ל אין דער שייכות פון דעם בעש״ט מיטן אלטן רבי׳ן זעט זיך בגלוי און בהדגשה אין דער תורה וואס דער בעש״ט האט געזאגט בש״פ כי תבוא ח״י אלול47 בשנת תרנ״ב [ווי דער רבי דער שווער האט דערציילט48 וועגן זיין פאטער, דער רבי נ״ע, ווי ער האט געהערט די ז׳ תורות וואס דער בעש״ט האט געזאגט יענעם ח״י אלול אין גן עדן49]:\nדי ערשטע תורה האט דער בעש״ט געזאגט אחר קבלת שבת אויפן פסוק50 „והי׳ כי תבוא אל הארץ גו׳״. ופי׳ ארץ ל׳ מרוצה, כי בתיבת ארץ יש ב׳ פי׳ כדאיתא במדרש51 למה נק׳ שמה ארץ שרצתה לעשות רצון קונה וארץ ל׳ מרוצה52.",[["45","45","ראה ספר הערכים חב״ד ח״א ערך אברים ס״א. וש״נ."],["46","46","משא״כ בחסידות חג״ת — שבאין מן האמונה או שהמוחין רק דרך מעבר. ואכ״מ."],["47","47","כהקביעות דשנה זו (תשמ״ג)."],["48","48","שמע״צ תרצ״ז אטוואצק, מרשימת השומעים (נעתק בס׳ שבהערה הבאה)."],["49","49","היום יום — ח״י אלול (בקיצור קצת). כתר שם טוב בהוספות ס״ג. וש״נ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091365\" data-slug=\"likkutei-sichot\" data-id=\"1300091365\">לקו״ש ח״ט ע׳ 338</a> ואילך."],["50","50","ריש פרשתנו (כו, א)."],["51","51","ב״ר פ״ה, ח."],["52","52","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו״א</a> ד״ה כי כאשר (א, סע״ג ואילך). סה״מ תקס״ה ח״ב ע׳ תשיב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560030\" data-slug=\"or-hatorah-hb\" data-id=\"8316560030\">אוה״ת בראשית ח״ג תפא, ב</a> ואילך. ח״ו תתרמג, א ואילך. וראה גם סה״מ עטר״ת ע׳ תקכג. ועוד."]]],[1300241200,"„והי׳ כי תבוא אל הארץ״ — אז דו וועסט צוקומען צו דעם רצון ומרוצה — אשר ה״א נותן לך נחלה וירשתה — וואס דאס איז א מתנה מלמעלה בירושה53 בכל אחד מישראל, דארף זיין די עבודה אין דעם — וישבת בה — דאס זאל זיין בהתיישבות — ולקחת גו׳54 ושמת בטנא — מלביש זיין די אורות אין כלים — והלכת אל המקום — הוא ענין השגחה פרטית — אשר יבחר ה׳ אלקיך — אז א איד גייט אין אן ארט, איז דאס ניט וואס ער גייט נאר מי פירט עם, די השגחה העליונה. איז אז ער קומט אין אן ארט איז די כוונה — לשכן שמו שם — לפרסם אלקות בעולם.\nוויבאלד אז די תורה איז געזאגט געוואָרן ע״י הבעש״ט ביום ח״י אלול און דאס איז געהערט געווארן ע״י נשיאי חב״ד55, איז מובן56, אז אין דעם איז מודגש די נקודה און חידוש פון דעם טאג פון ח״י אלול — ענינו פון בעש״ט און דעם אלטן רבי׳ן.\nויש לומר (בדרך אפשר) אז דא זיינען צווי ענינים וואס דער בעש״ט זאגט:\nא) „והי׳ כי תבוא אל הארץ — דו וועסט צוקומען צו דעם רצון ומרוצה אשר ה״א נותן לך נחלה וירשתה וואס דאס איז א מתנה מלמעלה בירושה בכל\nאחד מישראל״ — דאס איז בכללות דער גילוי פון תורת החסידות הכללית וואס דער בעש״ט האט אויפגעטאן, גילוי רצון עצמי שבנשמה וואס איז פארנאן בא יעדער אידן,\nב) און די עבודה וואס דארף אין דעם זיין — „וישבת בה — דאס זאל זיין בהתיישבות, ולקחת גו׳ ושמת בטנא — מלביש זיין די אורות אין כלים״ — איז ענין חסידות חב״ד, אז דעם רצון ומרוצה פון דער נשמה טראגט מען אראפ בפרטיות, אורות בכלים. דאס ווערט דערהערט און אויפגעטאן אין יעדן כח פרטי פון דעם אדם, וכנ״ל.\nאון אין דעם איז דער בעש״ט מדגיש אז דאס זיינען ניט קיין צווי עבודות וענינים — „דו זאלסט צוקומען צו דעם רצון ומרוצה כו׳״ און (א צווייטע זאך) עס דארף זיין די עבודה צו אראפטראגן דאס בהתיישבות״,\nנאר דאס איז געזאגט געווארן אלס איין ענין: „און דו וועסט צוקומען כו׳״ — ד.ה. אז בא דיר איז געווארן די לידה, עס האט זיך אין דיין מציאות גופא אנגעהערט און נתגלה געווארן די „מתנה מלמעלה בירושה בכל אחד מישראל״, דער „רצון ומרוצה״ של הנשמה, דארף זיין די עבודה אין דעם — „מלביש זיין די אורות אין כלים״ — עס זאל אראפקומען אין חב״ד, ועל ידיהם — בכל כחות נפשו כנ״ל, און דעמאלט איז דאס שלימות הלידה57.\nו. עפ״ז יש לבאר דעם המשך אין דער תורה „והלכת אל המקום הוא ענין",[["53","53","ראה ב״ב (קכט, ב. קלג, א) בענין מתנה במי שראוי ליורשו. ונת׳ באוה״ת בראשית ח״א טז, ב ואילך."],["54","54","פרשתנו שם, ב: ולקחת . . לשכן שמו שם."],["55","55","היינו — גם בעלמא דין, כי בג״ע היו כל החסידים ג״כ (וראה הערה הבאה)."],["56","56","ומובן ג״כ ששייך ענין זה לכאו״א, מכיון שבעת אמירת התורה הנ״ל (והתורה הב׳ דלקמן, משא״כ שאר התורות) היו שם גם תלמידי הבעש״ט ותלמידיהם וחסידים (בכלל) וגם נשים (ראה בהמשך הרשימה בכתר ש״ט שם. וראה לקו״ש שם)."],["57","57","ע״פ הנ״ל בפנים תומתק ההקדמה של כ״ק מו״ח אדמו״ר לתורות הנ״ל שבלקו״ד ח״ב (שמא, א ואילך) שאינו מספיק הענין דאמונה בה׳ אלא שצריך להתייגע שאלקות יבא גם בהשגה, ועי״ז ההשגה באלקות נעשה אמונה טהורה כו׳. עיי״ש."]]],[1300241201,"השגחה פרטית . . אז ער קומט אין אן ארט איז די כוונה לשכן שמו שם — לפרסם אלקות בעולם״.\nדלכאורה: אין הכי נמי, דאס איז אויך פארבונדן מיט די יסודות פון שיטת הבעש״ט, דער ענין פון השגחה פרטית און מפרסם זיין אלקות וואו א איד קומט58 —\nוואס איז אבער דער קשר מיט התחלת התורה „והי׳ כי תבוא אל הארץ . . ולקחת . . ושמת בטנא — מלביש זיין די אורות אין כלים״?\nאין דער רשימה59 ווערט דערציילט וועגן דער צווייטער תורה וואס איז געוו־ען אחר תפלת ערבית, אז „אמר עוד הפעם התורה הקודמת והוסיף: והי׳ כי תבוא — בכדי אויף צוקומען צו דעם רצון וואס איז במתנה בא יעדערן, הוא ע״י — לשכן שמו שם — מוסר נפש זיין זיך לפרסם אלקותו בעולם. וואס איז דער מסירת נפש אין דעם — מיט א ברכה ופסוק תהלים״.\nדאס איז אבער ניט מספיק לבאר די שייכות פון די צווי ענינים אין דער תורה הא׳, ווארום פון המשך הלשון „אמר עוד הפעם התורה הקודמת והוסיף״ איז משמע, אז די הוספה בתורה שני׳ איז אן ענין ותורה בפ״ע, א הוספה, ניט (נאר) א הסבר אויף דער תורה הראשונה.\nאויך: עפ״ז איז בלויז מובנת די שייכות פון „לשכן שמו שם״ מוסר נפש זיין לפרסם אלקותו בעולם, מיט „והי׳ כי תבוא״, דער רצון וואס איז במתנה בא יעדערן וואס איז כללות החידוש פון תורת הבעש״ט, ניט מיטן עיקר פרט אין\nדער ערשטער תורה, דעם ענין וואס עס דארף זיין בהתיישבות ולקחת גו׳ ושמת בטנא מלביש זיין די אורות אין כלים — דער ענין פון אראפטראגן אין פרטים — חב״ד?\nוי״ל דעם ביאור בזה:\nדער חילוק צווישן אן עובר און א נולד (ניט נאר אין מציאותו לגבי עצמו, נאר אויך ובעיקר כלפי הזולת), אז אן עובר זיינען ענינו ופעולותיו לעצמו, און זיי האבן ניט קיין שייכות והשפעה צו דעם עולם שמחוץ. משא״כ ווען דער קינד ווערט געבארן, איז יעדער פעולה במציאות אויך חוץ ממנו, אנהויבנדיק פון דעם רגע הראשון שנולד, ווען זיין צעקה הערט זיך בחוץ60 און זיין פעולה בידים ורגלים ווערט געזען און געפילט פון אנדערע.\nאון דערפאר, איז אלס המשך צו דער „לידה״ פון א אידן, דאס וואס זיין תומ״צ און זיין חיות ונפש — דער רצון ומרוצה של הנפש קומט אראפ ביז אין אורות און כלים — ברענגט דאס במילא אויך דער פרסום אלקות, אז וואו ער קומט דערהערט ער אז די כוונה איז אויף מפרסם זיין אלקות בעולם.\nדער טעם דערפון ברוחניות: דער חילוק פון א זאך וואס ווערט באלעבט פון א צווייטער זאך און א חיות עצמי איז61: א זאך וואס ווערט באלעבט פון א צווייטער קען ניט מחי׳ זיין אנדערע, דוקא חי בעצם קען פון אים זיין חיות להחיות, עס קומט צו א צווייטע זאך נעמט עס",[["58","58","ראה כתר שם טוב בהוספות סקכ״ג ואילך."],["59","59","הנ״ל הערה 48, 49."],["60","60","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו״א</a> (ועד״ז בשאר המקומות שבהערה 24), „שאז מוציא הקול כמ״ש רז״ל (נדה מב, ב. טושו״ע יו״ד סקצ״ד סי״ב) שהוא סימן הלידה דשמעי׳ לולד דצריץ״."],["61","61","המשך תרס״ו ע׳ קעו. ובכ״מ."]]],[1300241202,"דורך און מאכט דאס לעבן. און ווי־באלד אז אלקות ותומ״צ איז חיות עצמי, איז בשעת דאס ווערט די מציאות פון א אידן, דאס איז זיין נפש, במילא62, וואו א איד גייט פועל׳ט ער און איז מפרסם אלקות בעולם63.\nז. אע״פ אז דער ענין פון פרסום אלקות בעולם האט זיך אנגעהויבן דורכן בעש״ט נאך איידער דער גילוי תורת חסידות חב״ד דורך דעם אלטן רבי׳ן — קומט צו אין דעם פרסום אלקות וואו דאס איז לאחרי גילוי תורת חב״ד, אז „די אורות״ קומען אראפ „אין כלים״.\nדי הסברה בזה:\nדער אויפטו פון דעם אלטן רבי׳ן מיט תורת חסידות חב״ד איז ניט נאר מצד דער אויסגעטיילטקייט פון חב״ד של האדם פון אנדערע כחות הנפש [און דערפאר איז נוגע אז תורת החסידות — אלקות — זאל דערהערט ווערן אויך שכלו של האדם],\nנאר ווייל די כוונה איז — לעשות לו ית׳ דירה בתחתונים, עס זאל דערהערט ווערן אז אין עוד מלבדו, אין מציאות העולם ומצד העולם, און וויבאלד אז התחלת המציאות וואס איז נבדל כביכול\nפון אלקות איז שכל64, איז לכל לראש נוגע צו מסביר זיין הנ״ל אין שכל, ביז אין שכל אנושי. און דורך דעם וואס אויך שכל האדם דערהערט און אנערקענט אחדות ה׳ הנ״ל, ביז באופן אז עס ווערט כל מציאותו פון דעם שכל צו פארשטיין אלקות, קומט דאס אראפ אין „והשבות אל לבבך״65, אין מדות שבלב, וואס די פעולה בשלימות אין מדות שבלב איז ווען דאס קומט דורך דעם שכל של האדם [ווי דער רמב״ם פסק׳נט אזוי להלכה66 „והאיך היא הדרך לאהבתו ויראתו בשעה שיתבונן כו׳״], ועי״ז אין די כחות התחתונים, ביז עס ווערט דערהערט אחדות ה׳ אין דער גאנצער וועלט ובכל עניני העולם67.\nאון דעריבער זעט מען אז ווי דער ענין פון „לפרסם אלקות בעולם״ קומט אלס המשך און א פרט אין דעם אויפטו פון חב״ד אין תורת החסידות הכללית „ולקחת גו׳ ושמת בטנא, מלביש זיין די אורות אין כלים״ — קומט צו אין דעם א חידוש,\nווייל נוסף ע״ז וואס ווען זעט מען אז דאס איז רצון ומרוצה פון עצם הנפש, וואס קומט אראפ אין חב״ד — ניט אן ענין וואס איז פארבונדן מיט זיין מציאות ותענוג — דוקא ווען מ׳זעט אז דער מענטש פארבויגט אויף דער עבודה מיט זיך (זיין השכלה אין אלקות, עבודתו",[["62","62","ראה שם ע׳ קעז־ח (ובכ״מ) הגוף חי ממנו שלא ע״י התעסקות דכאשר הנפש הוא שייך להגוף הרי הגוף ממילא חי ממנו."],["63","63","להעיר מד׳ הענינים (סה״מ תש״ח ע׳ 295 ואילך — ענין ו־ט) שמבאר כ״ק מו״ח אדמו״ר בדברי אביו ע״ד תורת החסידות „חיות תורת החסידות הוא עצם. חי בעצם הוא חי להחיות. תורת החסידות מחי׳ נפשות. רבינו במסירת נפשו הק׳ על תורת החסידות פעל למעלה, אשר בכל זמן ובכל מקום שילמדו תורת החסידות בספר או בעל פה, יפעל על השומעים״. ועפ״י הנ״ל בפנים תומתק השייכות ביניהם. ואכ״מ."],["64","64","כי הרצון — הוא תנועה בנפש (וגילוי) מציאותו הוא בשכל ומדות ומחדרו״מ."],["65","65","ואתחנן ד, לט."],["66","66","הל׳ יסוה״ת פ״ב ה״ב."],["67","67","ראה ד״ה פדה בשלום תרפ״ה בסופו „וכוונה העצמית שהטבע ממש יהי׳ אלקות והענינים שלמטה יהיו כלים לאלקות דזה בא ע״י רבינו בהתלבשות בהשגה דוקא כו׳״."]]],[1300241203,"באהבה ויראה) און גייט מפרסם זיין אלקות בעולם שמחוץ הימנו68.\nאיז אויך בנוגע דער עבודה גופא, כשם ווי ס׳איז נוגע אז דער פרסום אלקות מצד האדם זאל געטאן ווערן בכל כחות נפשו, ער זאל מפרסם זיין אלקות בהבנה והשגה, ועל ידי מדותיו ושאר כחות נפשו, ביז צו כח העשי׳ שלו — לייגן תפילין מיט א אידן, אנקלאפן א מזוזה בפתח ביתו, ועד״ז בשאר מצוות,\nאיז עד״ז נוגע אויסנוצן יעדער מיטל ואופן אויף מפרסם זיין אלקות לויט דעם מצב המיוחד שבכל זמן ובכל מקום, וואס דורכדעם איז מען מברר ומעלה אויך דעם מכשיר וענין מסוים69 אין וועלט לעבודתו ית׳70. ווארעם יעדער מכשיר ודבר בעולם איז „לא בראו אלא לכבודו״71.\nח. עפ״ז איז אויך מובן וואס די תורת הבעש״ט הנ״ל איז נתגלה געוואָרן דורך כ״ק מו״ח אדמו״ר, ווייל בא\nכ״ק מו״ח אדמו״ר האט מען געזען בפועל ווי די השגחה העליונה האט אים געפירט בכל מקום „לשכן שמו שם — לפרסם אלקות בעולם״, כפשוטו אין דער גאנצער וועלט — ובפרט דורך זיינע שלוחים כו׳ בכל קצוי תבל.\nאון אויך דער פרסום איז געווען בכל האופנים: סיי דורך מגלה זיין די טיפסטע ענינים אין תורת החסידות, סיי דורך מפרסם זיין ענייני תורה, נגלה און חסידות, אין פארשידענע שפראכן — ביז למטה ביותר פאר תינוקות שנשבו כו׳, ביז פועל׳ן אויף א אידן צו היטן שבת, טהרת המשפחה, לייגן תפילין וכיו״ב.\nוואס דורך דעם פועל׳ט מען אויף דעם אידן אז ביי אים זאל זיך דערהערן דער „אני היום ילדתיך״72, ער ווערט געבארן אלס איד, א לעבעדיקער „נפש״, אז זיין גאנצע מציאות איז תורה און אידישקייט.\nאון דאס איז נאך מער ממהר די גאולה בפועל במהרה בימינו, דורך משיח צדקנו, ווען עס וועט זיין בגלוי די לידת עם ישראל — „חלה גם ילדה ציון את בני׳״73, במהרה בימינו ממש.\n(משיחות ח״י אלול תשמ״א, תשמ״ב)",[["68","68","להעיר ממכתב כ״ק מו״ח אדמו״ר שנדפס בספר השיחות תש״ה בסופו. אג״ק שלו ח״ח ע׳ תצז ואילך."],["69","69","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151043\" data-slug=\"likkutei-sichot\" data-id=\"1300151043\">לקו״ש חט״ו ע׳ 43</a> ואילך."],["70","70","וע״י הבפועל שבזה — הן מצד האדם (שפירסום אלקות הוא בכל כחות נפשו) והן בעניני עולם (שהוא לפי אופן הזמן והמקום כו׳ שעי״ז מברר ומעלה כל עניני העולם כו׳), עשיית דירה לו ית׳ בתחתונים, בפועל, נתוסף בגילוי העצמות ובגילוי הרצון שבנשמה, ובמילא בהחדרתו בחב״ד כו׳."],["71","71","אבות ספ״ו."],["72","72","תהלים ב, ז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021329\" data-slug=\"likkutei-sichot\" data-id=\"1300021329\">לקו״ש ח״ב ע׳ 605</a> ואילך."],["73","73","ישעי׳ סו, ח."]]],[1300241204,"<h3>נצבים</h3>\nא. אין אנהויב סדרה ווערט דער־ציילט וועגן דער כריתת ברית פון דעם אויבערשטן מיט אידן — „לעברך בברית ה״א גו׳ למען הקים אותך היום לו לעם גו׳״<sup data-n=\"1\">1</sup>. שטעלט זיך רש״י אויף „למען הקים אותך היום לו לעם״ און איז מפרש: כל כך הוא נכנס לטרוח למען קיים אותך לפניו לעם.\nדארף מען פארשטיין: וואס איז דא רש״י מחדש אין דעם פירוש פון די ווערטער „למען הקים גו׳״ (ווי מ׳וואלט זיי געלערנט אן פירוש רש״י)?\nמפרשים<sup data-n=\"2\">2</sup> לערנען, אז רש״י׳ן איז שווער: דער צורך פון דער כריתת ברית איז דאך געווען (ניט „למען הקים גו׳ לו לעם״, נאר) „כדי שיפחדו מהם ויקיימו את התורה״<sup data-n=\"3\">3</sup>, א כריתת ברית אויף שמירת המצות — איז וואס זאגט דער פסוק „לעברך בברית גו׳ למען הקים גו׳ לו לעם״?\nפארענטפערט רש״י, אז דער פסוק קומט ניט זאגן דעם צוועק פון דער כריתת ברית, נאר דאס איז א טעם פאר־וואס „כל כך הוא נכנס לטרוח״ (אויף דעם אויבערשטנ׳ס טרחא צו כורת ברית זיין מיט אידן): היות אז „דבר לך ונשבע לאבותיך שלא להחליף את זרעם באומה אחרת״ (ווי רש״י איז מבאר גלייך אין דעם דיבור־המתחיל שלאח״ז<sup data-n=\"4\">4</sup>, האט דער אויבערשטער געמוזט כביכול כורת זיין א ברית מיט אידן אז זיי זאלן ניט\nעובר זיין אויף תום״צ, וועט ער זיי ניט דארפן מרחק זיין פון זיך (היפך פון זיין שבועה לאבותיך).\nדאס הייסט, אז דער „למען הקים גו׳״ באציט זיך ניט צום „לעברך בברית גו׳״ (אז „הקים גו׳״ איז די מטרה פון דער כריתת ברית), נאר (א טעם) אויף „כל כך הוא נכנס לטרוח״ — די טרחא של הקב״ה איז „למען״, כדי צו פארזיכערן אז אידן וועלן בלייבן „לו לעם . . כאשר דבר לך גו׳״<sup data-n=\"5\">5</sup>.\nדער פירוש איז אבער ניט פאר־שטאנדיק: דער ענין פון „הקים אותך גו׳ לו לעם והוא יהי׳ לך לאלקים״ און שמירת המצות זיינען דאך תלוי זה בזה, כמפורש בכמה פסוקים<sup data-n=\"6\">6</sup> — און ווי די מפרשים הנ״ל זאגן אליין דא גופא (כנ״ל), אז אויב אידן וועלן ח״ו עובר זיין אויף תום״צ, וועט דער אויבערשטער זיי דארפן מרחק זיין (היפך השבועה ש„אינו יכול להבדל מכם״<sup data-n=\"7\">7</sup> —\nאיז פארוואס דארף מען מחדש זיין און לערנען אז דער „למען הקים גו׳״ באציט זיך (ניט אויף המפורש בכתוב „לעברך בברית גו׳״, נאר) אויף „כל כך הוא נכנס לטרוח כו׳״, וואס שטייט ניט אין פסוק — בשעת מען קען לערנען כפשוטו (און במילא דארף עס רש״י גארניט זאגן), אז די מטרה פון „לעברך בברית גו׳״ — די כריתת ברית אויף שמירת המצות — איז „למען הקים",[["1","1","כט, יא־יב."],["2","2","רא״ם, גו״א ושפ״ת."],["3","3","לשון הרא״ם."],["4","4","וברא״ם כאן משמע שכל זה הוא דיבור אחד. וכן משמע בדפוס ראשון ושני."],["5","5","וכן משמע בתנחומא פרשתנו ג (כמו שציין בס׳ זכרון כאן שזהו מקורו דפרש״י זה)."],["6","6","ראה יתרו יט, ה־ו. ר״פ בחוקותי (כו, ג. שם, יב). ועוד."],["7","7","ל׳ רש״י בד״ה שלאח״ז."]]],[1300241205,"אותך גו׳ לו לעם והוא יהי׳ לך לאלקים״ (אז דורך קיום התום״צ, זאלן אידן ווערן „לו לעם״ און דער אויבערשטער — „לך לאלקים״)<sup data-n=\"8\">8</sup>.\nב. נאך א זאך איז ניט גלאטיק לויטן פירוש הנ״ל: לפירוש זה קומט אויס, אז דער חידוש פון רש״י איז ניט אין די ווערטער „הקים אותך היום לו לעם״, נאר בלויז אין ווארט „למען״\n— אז דאס באציט זיך ניט צום „לעברך בברית גו׳״ וואס שטייט אין פריערדיקן פסוק, נאר אויף „כל כך הוא נכנס לטרוח״ [אדער, אז דער „למען״ דא מיינט ניט „בשביל״ (די מטרה ותכלית בעתיד), נאר „לפי״ — ס׳איז א נתינת טעם אויפ׳ן עבר, פארוואס „כל כך הוא נכנס לטרוח״<sup data-n=\"9\">9</sup> —\nעפ״ז אבער — צ״ע פארוואס דארף רש״י מעתיק זיין פון פסוק אין זיין ד״ה, און דערנאך בגוף פירושו די אלע ווערטער „(למען) קיים אותך לפניו לעם״?\nנאך מער: רש״י איז משנה פון לשון הכתוב: (א) אין פסוק שטייט „הקים״, און רש״י זאגט „קיים״<sup data-n=\"10\">10</sup>. (ב) דער פסוק זאגט „לו לעם״, און רש״י איז משנה — „לפניו לעם״. (ג) רש״י איז משמיט דעם ווארט „היום״.\nפון דעם איז מוכח, אז דער חידוש אין פירוש רש״י דא, איז ניט אין די ווער־טער „כל כך הוא נכנס לטרוח״ (מיט וועלכע ער הויבט אן פירושו), נאר טאקע אין די ווערטער „(למען) קיים אותך לפניו לעם״: ער מיינט ניט מעתיק זיין דעם פסוק<sup data-n=\"11\">11</sup>, נאר — צו מפרש זיין דעם פשט אין פסוק, אז דער טייטש פון „הקים״ אין דעם פסוק איז — „קיים״, און „לו לעם״ מיינט — „לפניו לעם״.\nג. דער ביאור בזה: רש״י׳ן ארט דא א קשיא פשוטה:\nווי קען מען זאגן אז די כריתת ברית איז „למען הקים אותך היום לו לעם״ — אז אידן ווערן „היום״ (אין דעם טאג ווען „כינסם משה לפני הקב״ה ביום מותו״<sup data-n=\"12\">12</sup> אויפגעשטעלט אלס אן עם להקב״ה — בעת אידן זיינען שוין פון לאנג, ביי מתן תורה, געווארן אן עם, כמפורש בכמה פסוקים<sup data-n=\"13\">13</sup>?\n[וואס דערפאר, ווען דער פסוק<sup data-n=\"14\">14</sup> זאגט „היום הזה נהיית לעם״, באווארנט גלייך רש״י אז דאס מיינט ניט אז אין יענעם טאג „נהיית לעם״, נאר — „בכל יום יהיו בעיניך כאילו היום באת עמו בברית״; ועד״ז אויפן פסוק<sup data-n=\"15\">15</sup> „היום הזה ה״א מצוך גו׳״ איז רש״י מפרש „בכל יום יהיו בעיניך חדשים כאילו בו ביום נצטוית עליהם״ (און דערפון איז פאר־שטאנדיק, אז דאס איז אויך דער טייטש אין „את ה׳ האמרת היום גו׳ וה׳ האמירך היום להיות לו לעם סגולה״<sup data-n=\"16\">16</sup>, וואס",[["8","8","ועפ״ז לא קשה ג״כ קושיית המשכיל לדוד, דאם כוונת הכתוב היא „ומהו הברית להקים אותך גו׳״, „א״כ אין ל׳ למען נופל״ (ומציין לפרש״י וירא יח, יט) — כי הכריתת ברית עצמה היא על שמירת המצות, ותכליתה הוא — „למען הקים גו׳ לו לעם והוא יהי׳ לך לאלקים״."],["9","9","כן משמע קצת במפרשים הנ״ל הערה 2. וראה משכיל לדוד."],["10","10","בדפוס ראשון דרש״י „הקים״. אבל בדפוס שני, רוב כת״י רש״י (שתח״י) ודפוסי רש״י שלפנינו — הוא כבפנים."],["11","11","שלכן משמיט תיבת „היום״."],["12","12","רש״י ריש פרשתנו."],["13","13","ראה גם באר יצחק לפרש״י כאן."],["14","14","תבא כז, ט."],["15","15","שם כו, טז."],["16","16","שם, יז־יח."]]],[1300241206,"קומט בהמשך<sup data-n=\"17\">17</sup> צו „היום הזה ה״א מצוך גו׳״)].\nפארענטפערט רש״י, אז „למען הקים גו׳״ מיינט ניט צו „אויפשטעלן״, נאר — „קיים״, צו אויפהאלטן אידן אלס אן „עם״ (וואס איז פארבונדן מיט א פעולה פון דעם אויבערשטן):\nדי כריתת ברית פון מ״ת האט אויפגעטאן אז אידן זיינען געווארן אן עם פארבונדן מיטן אויבערשטן, אבער עס איז דאך מעגליך דערנאך — אויב די הנהגה פון אידן שפעטער (אדער אין שפעטערדיקע דורות) וועט ניט זיין כדבעי ח״ו — זאל ווערן אין דעם א שינוי<sup data-n=\"18\">18</sup>:\nאיז דער אויפטו פון דעם ברית — „למען קיים אותך כו׳ לעם״: עס האט אריינגעבראכט א קיום13 אין דעם ברית בין ישראל להקב״ה לעד ולעולמי עולמים<sup data-n=\"19\">19</sup>.\nעפ״ז ווערט אויך פארשטאנדיק פאר־וואס דוקא ביי דעם ברית איז מודגש אז ער איז (ניט נאר מיט „את אשר ישנו פה״<sup data-n=\"20\">20</sup>, נאר) אויך מיט „את אשר איננו פה״20 — „עם דורות העתידים להיות״21.\nד. פרעגט אבער א בן חמש למקרא: ויבאלד אז אין דעם ערשטן ברית האט יא געקענט זיין א שינוי — איז מאי אולמי׳ האי מהאי, מיט וואס איז דער ברית אנדערש און שטארקער — אז אין אים קען ניט ווערן קיין שינוי?\nאיז רש״י מקדים „כל כך הוא נכנס לטרוח״: ביי דעם ברית איז דער אויבערשטער אריינגעגאנגען אין א טרחא מיוחדת, ער האט זיך ספעציעל אריינגעלייגט, כביכול, אין דער כריתת ברית\n— ווי דער פסוק זאגט „לעברך בברית״, וכפרש״י „דרך העברה״, אז (אויך) דער אויבערשטער<sup data-n=\"22\">22</sup> איז, כביכול, „דורכגעגאנגען״ צווישן די „מחיצה מכאן ומחיצה מכאן״:\nאון אויך אז דעם ברית האט ער פאר־בונדן אויך מיט „אלתו״ —\nובמילא האט עס געהאט א פעולה מוחלטת (אויך) אויף אידן (וואס דערי־בער איז אין דעם ניט שייך קיין שינוי מצדם).\nאון דעם אויפטו אין אידן דורך דעם ברית איז רש״י מדגיש דערמיט וואס ער איז (משנה פון לשון הכתוב „לו לעם״, און איז) מדייק (אז דאס מיינט) „למען גו׳ לפניו לעם״:\nדער חילוק צווישן „לו לעם״ און „לפניו לעם״: „לו לעם״ מיינט, אז דער „עם״ געהערט צום אויבערשטן, ס׳איז זיינער אן עם; „לפניו לעם״ מיינט, אז דער „עם״ איז ניט נאר זיינער (אבער ער קען זיין בריחוק פון אים), נאר זיי זיינען",[["17","17","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091166\" data-slug=\"likkutei-sichot\" data-id=\"1300091166\">לקו״ש ח״ט ע׳ 166</a>."],["18","18","ראה גם תנחומא פרשתנו שם. ועוד."],["19","19","וזהו גם ההמשך לפרש״י שלאח״ז „לפי שדיבר כר׳ שלא להחליף את זרעם באומה אחרת כר׳״ (ראה לעיל הערה 4). ועפ״י המבואר בפנים מתורצת בפשטות שיטת רש״י (עד הפשט) בחידוש דכריתת ברית זו לגבי שלפני׳, דשקו״ט בזה בארוכה במפרשים (ראה תנחומא שם. רמב״ן כט, יז. בחיי שם, ט. אברבנאל ואלשיך פרשתנו. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191283\" data-slug=\"likkutei-sichot\" data-id=\"1300191283\">לקו״ש חי״ט ע׳ 270</a> הערה 28 בשיטת רש״י)."],["20","20","פרשתנו כט, יד."],["21","21","רש״י שם. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191010\" data-slug=\"likkutei-sichot\" data-id=\"1300191010\">לקו״ש שם</a>, שהפירוש בזה הוא, שהכריתת ברית היא באופן ישר „עם דורות העתידים להיות״ (ולא שנכנסים לברית ע״י האבות וכיו״ב), ע״ש."],["22","22","אף שבפסוק נאמר רק „לעברך״ — הרי מלשון רש״י „כך היו כורתי בריתות עושין״ מוכח, שגם הקב״ה „עבר״ כביכול בברית. וראה רש״י לך טו, י."]]],[1300241207,"און שטייען „לפניו״ — זיי זיינען און שטייען פאר אים (— צוזאמען מיט אים). ע״ד ווי עס שטייט אין התחלת הסדרה „אתם נצבים היום כולכם לפני ה״א גו׳״.\nאון דערפאר זיינען ניט שייך קיין שינויים אין דעם ברית: ווען מען איז בלויז „לו לעם״, אבער זיי קענען זיין אויך בריחוק פון דעם אויבערשטן, גיט עס אן ארט אז זיי זאלן ניט פילן ווי זיי זיינען אן עם וואס דער אויבערשטער האט אויסגעקליבן, ובמילא קענען פארקומען דערינען שינויים; אבער דורך דעם וואס דער אויבערשטער מאכט „קיים״ אז אידן זאלן (אלעמאל) זיין און שטייען „לפניו לעם״, צוזאמען מיט אים — איז מען פארזיכערט אז עס וועט ניט זיין קיין שום חלישות אין דער כריתת ברית.\nה. אין דעם פירוש רש״י זעט מען בולט, ווי רש״י בפירושו על התורה, צו־זאמען דערמיט וואס „אני לא באתי אלא לפשוטו״<sup data-n=\"23\">23</sup>, און יעדער ווארט איז נויטיק צוליב הבנת פשוטו של מקרא — האט ער אין די זעלבע ווערטער אויך מרמז געווען ענינים פון „יינה של תורה״24.\nדער ענין אין פרש״י ע״ד הפשט, אז דער אויפטו פון דעם ברית באשטייט אין דעם וואס אידן זיינען געווארן „לפניו לעם״ — ווערט מבואר נאכמער און איז מתאים מיטן פירוש פון אלטן רבי׳ן (אין לקוטי תורה פון היינטיקער סדרה<sup data-n=\"25\">25</sup>, אין דעם ווארט „עם״, אז דאס מיינט\n[ניט ווי דער טייטש פון „עם״ בכמה מקומות — „מלשון עוממות שהם\nדברים נפרדים וזרים ורחוקים ממעלת המלך״26 — נאר פארקערט]\n„עמו שהם אנשים כמותו ומתייחסים אליו״, און „למען הקים אותך גו׳ לו לעם״ איז דאס וואס דער אויבערשטער הויבט אויף אידן „עד בחי׳ מחשבה העל־יונה״.\nו. נאך אן ענין פון יינה של תורה שבפירוש רש״י:\nאויף „אתם נצבים היום״ זאגט דער אלטער רבי27, אז „היום קאי על ראש השנה״, און איז מבאר אז יעדער ראש השנה דארף זיין דער (זכרון ה)ברית צווישן אידן מיטן אויבערשטן.\nעד״ז איז ער מבאר28 די פסוקים הנ״ל (אין פ׳ תבא) „היום הזה ה״א מצוך גו׳ את ה׳ האמרת היום גו׳ וה׳ האמירך היום להיות לו לעם סגולה גו׳״ — אז דאס גייט אויף דער כריתת ברית וואס ווערט אויפגעטאן בראש השנה.\nוע״פ האמור לעיל, אז די צוויי פסוקים זיינען צוויי אופנים אין דער כריתת ברית צווישן אידן מיטן אויבערשטן — „להיות לו לעם״ און „הקים (קיים) אותך גו׳ לו (לפניו) לעם״ — קומט אויס, אז בר״ה ווערן אויפגע־טאן ביידע ענינים הנ״ל29.\nוועט מען דאס פארשטיין בהקדים הביאור אין די הערות פון טאטן אויף",[["23","23","רש״י בראשית ג, ח. שם, כד. ועוד."],["24","24","ראה היום יום ע׳ כד."],["25","25","מד, ד."],["26","26","שער היחוד והאמונה רפ״ז. ובכ״מ."],["27","27","לקו״ת שם מד, א ואילך. ועד״ז שם פ׳ תבא מב, א."],["28","28","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו״ת תבא מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380887\" data-slug=\"likkutei-torah\" data-id=\"4001380887\">שם מב, ג</a>. וראה אוה״ת עה״פ. לעיל ע׳ 164."],["29","29","להעיר מהשינוי בלקו״ת שם, דבפ׳ תבא שם (שבה נאמר „מצוך גו׳ להיות לו לעם״) כותב ד„בכל שנה קודם ראש השנה צריך כריתת ברית מחדש״: ובפ׳ נצבים (שנאמר „הקים גו׳ לו לעם״) מבאר זה שבר״ה ישנו „זכרון הברית״. וראה הערה 33."]]],[1300241208,"זהר30, וואו ער איז מפרש אז (אויך) דער פסוק<sup data-n=\"14\">14</sup> „היום הזה נהיית לעם״ גייט אויף ראש השנה, וז״ל:\nודע שהפסוק הזה יל״פ שקאי על ר״ה. זהו היום הזה שקאי על היום דר״ה (שנק׳ זה כמ״ש31 זה היום תחלת מעשיך והוא למעלה מן בכ״ה באלול נבה״ע . .) ואז נהיית לעם כמ״ש למען הקים אותך היום להיות32 לו לעם שקאי על ר״ה ועיין בלקו״ת בד״ה אתם נצבים היום ע״ש.\nדארף מען פארשטיין: דער עצם צו־שטעל פון די צוויי פסוקים — נהיית לעם״ און „למען הקים אותך גו׳״ — קען מען פארשטיין, ווייל דא איז מען נאר אויסן א ראי׳ אויף כללות הענין, אז דער „היום הזה נהיית לעם״ האט א שייכות מיטן טאג פון ר״ה, און דאס (אז „היום״ גייט אויף ר״ה) געפינט מען בפירוש (אין לקו״ת) אויף דעם פסוק „למען הקים אותך היום לו לעם״33.\nמען דארף אבער פארשטיין די ראי׳ אז „היום הזה״ גייט אויף ר״ה ווייל ר״ה „נק׳ זה״: דאס וואס „היום״ גייט אויף ר״ה איז דאך ניט ווייל ר״ה „נק׳ זה״, נאר ווייל דער ווארט „היום״ גופא איז מרמז אויף ר״ה (בלשון פון אלטן רבי״ן34: בכל מקום שנאמר היום הוא ראש השנה) — און ווי דער רמ״ז35\n(וואס ווערט אנגעצייכנט אין לקו״ת<sup data-n=\"36\">36</sup> איז מבאר, אז „נקרא היום לפי שהוא יום הששי שבו נברא אדה״ר היום הידוע״ —\nאבער דער טאטע זאגט אז „היום הזה נהיית לעם״ גייט אויף ר״ה ווייל „נק׳ זה״, און ניט (נאר) מצד דעם ווארט „היום״?\nדי תמי׳ איז נאך שטארקער: אין דער הערה גופא ברענגט ער גלייך דערנאך (כנ״ל) דעם פסוק „למען הקים אותך היום לו לעם״ — „שקאי על ר״ה״ — און דארט37 שטייט ניט „(היום) הזה״ (ועד״ז שטייט ניט „הזה״ אין פסוק „אתם נצבים היום״ וואס — „קאי על ר״ה״)!\nנאר — אין ראש השנה עצמו זיינען דא צוויי בחינות: איין בחינה וואס ווערט אנגערופן „זה״ — און אין פסוק „היום הזה נהיית לעם״ (אויף וועלכן דער טאטע שטעלט זיך) איז נוגע די בחינה אין ר״ה: און א צווייטע בחינה וואס ווערט אנגערופן „היום״ (סתם), ווי אין פסוק „אתם נצבים היום . . למען הקים אותך היום לו לעם״.\nז. דער ביאור בזה:\nאע״פ אז (אויך) „היום״ (סתם, אבער) בה״א הידיעה, ווייזט אויף א „יום הידוע״ — קומט עס אבער ניט צו דעם ענין פון „היום הזה״, וואס ווייזט אז ניט נאר איז ער א „יום הידוע״ (בשכל וכו׳), נאר",[["30","30","לקוטי לוי״צ לזהר כרך ב ע׳ שפח."],["31","31","בתפלת מוסף דר״ה (ר״ה כז, א)."],["32","32","ראה הערה הבאה."],["33","33","ע״פ המבואר בפנים מובן ג״כ דיוק לשון ההערה „למען הקים . . להיות לו לעם״ (אף שבכתוב ליתא תיבה זו), כי בכללות הוא אותו הענין ד„נהיית לעם״. וראה לקמן בפנים. ולהעיר שגם בלקו״ת שם הלשון „למען הקים . . להיות לו לעם״."],["34","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380885\" data-slug=\"likkutei-torah\" data-id=\"4001380885\">לקו״ת תבא מב, א</a>."],["35","35","לזח״ב לב, ב. הועתק בנצוצי אורות לזהר שם. וראה גם אור החמה שם. — ובזח״ג (רלא, א) „בכל אתר דכתיב ויהי איהו צער . . ויהי היום דאית בי׳ צער ודא הוא ראש השנה יומא דאית בי׳ דינא קשיא כו׳״. וראה אוה״ח לזח״ב שם ד״ה ר׳ אלעזר."],["36","36","שם מא, ג."],["37","37","וזה שלא נאמר „הזה״ בפסוקים „את ה׳ האמרת היום גו׳ וה׳ האמירך היום גו׳״ לא קשה, כי מכיון שבאים בהמשך ל„היום הזה ה״א מצוך גו׳״ מובן שה״ז אותו היום (ראה לעיל ס״ג ובהנסמן בהערה 17)."]]],[1300241209,"„זה״ — מ׳קען אנווייזן אויף אים (מראין . . באצבע<sup data-n=\"38\">38</sup>.\nוואס דאס איז אויך דער ביאור אין דעם שינוי לשון אין פירוש רש״י על התורה:\nאויפן פסוק (בפ׳ ואתחנן<sup data-n=\"39\">39</sup> „אשר אנכי מצוך היום״ איז רש״י מפרש: „לא יהיו בעיניך כדיוטגמא ישנה . . אלא כחדשה״ (מיט א כ״ף הדמיון); משא״כ אויפן פסוק אין פ׳ תבא (הנ״ל) „היום הזה ה״א מצוך״ זאגט ער: „בכל יום יהיו בעיניך חדשים״ — אן א כ״ף הדמיון40; ועד״ז אין פסוק (בפ׳ יתרו<sup data-n=\"41\">41</sup> „ביום הזה באו מדבר סיני״ זאגט רש״י „שיהיו דברי תורה חדשים עליך״.\nוע״פ הנ״ל י״ל הטעם: אין פ׳ יתרו ותבא, וואו אין פסוק שטייט „היום הזה״, „ביום הזה״ — איז דאס מדגיש, אז דער טאג מ״ת איז ביי אים מאיר בגלוי — ער איז „מראה באצבע״ (ער זעט עס פאר זיינע אויגן), ובמילא זיינען ביי אים די דברי תורה (פון מ״ת) „חדשים״ ממש;\nמשא״כ אין פ׳ ואתחנן וואו עס שטייט ניט „הזה״, פירושו אז דער טאג פון מ״ת\nאיז פארהאן (און „ידוע״) בכל יום, ווי־באלד אבער עס איז ניט אין אן אופן פון „זה״ (מראה באצבע), איז עס נאר „כחדשה״, מיט א כ״ף הדמיון42.\nח. עד״ז זיינען דא די צוויי בחינות אין ראש השנה, ווי מען זאגט31 אויף ראש השנה (א) „זה היום תחלת מעשיך״, (ב) „זכרון ליום ראשון״43:\n„זה היום תחלת מעשיך״ גייט אויף יום ששי למעשה בראשית, יום בריאת האדם, וואס דעמאלט האט זיך אויפ־געטאן דער ענין פון „זה״44 — אלקות זאל זיין בגילוי דא למטה, ווייל גילוי אלקות אין אן אופן פון „זה״ — איז דא דוקא ביי (נשמת ה)אדם.\n„זכרון ל)יום הראשון״ גייט אויף כ״ה אלול (יום ראשון דמעשה בראשית), וואס איז בחי׳ „כה״: אין דעם טאג האט זיך אויפגעטאן דער (עיקר) חידוש העולם, עס איז אבער געווען אן אופן פון „כה״ („כחדשה״) — וואס ווייזט אז מ׳זעט ניט די זאך אליין, מ׳זעט בלויז א „דמות״ (אן אפשפיגלונג פון דער זאך) — אין וועלט האט זיך ניט געזען דער חידוש באופן פון מראה באצבע; דער כח אלקי וואס האט באשאפן, מחדש געווען די מציאות העולם איז (מצ״ע) בהעלם אין וועלט.",[["38","38","רש״י בשלח טו, ב. ובכ״מ."],["39","39","ו, ו. והוא מספרי עה״פ."],["40","40","ואף שרש״י ממשיך „כאילו בו ביום נצטוית״, וכן בפרש״י יתרו (שהובא בפנים) ממשיך „כאילו היום נתנו״ — הרי מזה שרש״י משנה מלשונו בואתחנן שם („כחדשה״ וכותב „חדשים״), ויתירה מזו — גם ממקורות דפרש״י הנ״ל (תנחומא תבא א. פסיקתא דר״כ פ׳ בחודש השלישי. תנחומא (באבער) יתרו יג) שבהם לא נאמר „חדשים״, מוכח, (שע״ד הפשט) יש בזה הענין ד„חדשים״ (בלי כ״ף הדמיון). ויש לומר, כי ה„כאילו״ קאי רק ע״ז ש„בו ביום נצטוית״ (או „נתנו״), שבזה שייך לומר רק „כאילו״: אבל הד״ת הם אצלו „חדשים״ (ממש)."],["41","41","יט, א."],["42","42","וזה שעה״פ (עקב יא, יג) „אשר אנכי מצוה אתכם היום״ כותב רש״י „שיהיו עליכם חדשים״ (אף שלא נאמר „הזה״) — כי שם הרי נאמר לפנ״ז „שמוע תשמעו״, שפירושו (כפרש״י שם) „אם תשמע בישן תשמע בחדש״ (שזה כולל הענין שיהיו עליכם כחדשים), ועכצ״ל שתיבת „היום״ מוסיפה עוד ענין, והיינו „שיהיו עליכם חדשים״ (ממש)."],["43","43","בהבא לקמן ראה ד״ה זה היום באוה״ת (דרושים לר״ה ע׳ א׳תלב ואילך), בסה״מ תרל״ט. ועוד. וראה לקו״ת פרשתנו מז, ב־ג."],["44","44","ע״ד זה א־לי, נגלה עליהם והיו מראין אותו באצבע (בשלח טו, ב. ובפרש״י שם). *) ועד״ז בפרש״י עקב (שהובא בהערה 42) — „חדשים כאילו שמעתם בו ביום״."]]],[1300241210,"אבער איצט ווערט אויך דער ענין, דער חידוש פון „יום ראשון״ — בריאת העולם (וואס האט זיך אויפגעטאן בפעם הראשונה בכ״ה אלול), אויפגעטאן ביום ראש השנה — ווייל איצט זיינען אלע המשכות תלויות במעשה האדם, אויך די בריאת העולם ווערט נתחדש בראש השנה — יום בריאת האדם.\nט. דאס וואס ראש השנה האט אויך דעם ענין, אז דעמאלט ווערט נתחדש בריאת העולם („כה״), איז ניט א זייט־קער, צוגעגעבענער ענין (צו מהותו העיקרי (יום ששי למע״ב, יום בריאת האדם)) — נאר דאס קומט אלס תוצאה דערפון וואס בר״ה ווערט נתחדש דער ענין פון „זה היום תחלת מעשיך״, דער גילוי אלקות וואס איז שייך צום אדם.\nווי עס ווערט געבראכט45 דערויף א משל פון „אדם שעושה מלאכה מצד איזה תענוג ורצון שיש לו בה״, איז ווען ער ווערט פארמאטערט פון דער מלאכה, דארף מען מעורר זיין מחדש זיין תענוג אין דער מלאכה, און דורך דעם וואס ער באקומט נאכאמאל א תענוג אין דער מלאכה, ווערט בדרך ממילא א חיזוק אין דער עשיית המלאכה, אז זי זאל ניט זיין „ברפיון ידים״.\nועד״ז איז בראש השנה: בר״ה איז „תמליכוני״, מען איז ממשיך דעם תענוג דלמעלה אין ענין המלוכה, וואס דאס איז די השפעה פנימית46 מלמעלה (מהות אלקות — „זה״) וואס איז פאר־בונדן מיט אידן (אדם) דוקא; און דורך\nדעם ווערט אויך אויפגעטאן בדרך ממילא דער חידוש פון בריאת וחיות העולם (די עשיי׳).\nומובן, וויבאלד אז דער חידוש פון בריאת וחיות העולם בראש השנה קומט (ניט אלס אן זאך מצד עצמו, ווי בכ״ה אלול, נאר) אלס תוצאה פון דער התחדשות השפעה פנימית צו אידן, איז דאס לגמרי העכער47 פון דעם חידוש העולם ווי ער איז געווען בכ״ה אלול:\nדער ענין פון חידוש העולם וואס טוט זיך אויף בראש השנה, איז ניט נאר אז עס זאל זיין א וועלט, נאר אז אין וועלט זאל זיין גילוי אלקות48 (דער „זה״ פון ר״ה ווערט נמשך אין דעם „כה״). ע״ד ווי ביום ששי למעשה בראשית, וואס אדם הראשון האט ניט נאר אליין ממליך געווען דעם אויבערשטן אלס מלך, נאר ער האט פועל געווען אויף אלע נב־ראים אז „בואו נשתחוה ונכרעה נברכה לפני ה׳ עושנו״49.\n[אעפ״כ איז דא א חילוק גדול צווישן דעם גילוי אלקות שבהאדם און דעם גילוי אלקות אין וועלט. ביי דער נשמה פון א אידן איז דא ראיית מהות אלקות, „זה״: משא״כ אין וועלט, איז אויך ווען ס׳איז מאיר אלקות, איז דער אור ניט בגילוי כ״כ, און ער איז מאיר בלויז אין אן אופן פון „דמות״, כנ״ל].\nיו״ד. אט די שלימות וואס ר״ה (יום בריאת האדם, „זה״) טוט אויף אין דעם ענין פון חידוש העולם (אז אויך אין וועלט זאל אלקות זיין בגילוי), איז ניט נאר א בדרך־ממילא׳דיקע תוצאה פון",[["45","45","סידור ד״ה להבין ענין תק״ש (רמו, סע״א ואילך)."],["46","46","ראה בארוכה סידור שם (רמד, סע״ג ואילך) ע״ד ב׳ ההשפעות, ההשפעה חיצונית לצורך העולמות, וההשפעה פנימית לצורך הנשמות. ע״ש."],["47","47","ראה סידור שם (רמו, ג) „שע״י הארת הפנימית יומשך תוספת עוז וכח לחיצוניות״."],["48","48","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141135\" data-slug=\"likkutei-sichot\" data-id=\"1300141135\">לקו״ש חי״ד ע׳ 123</a>. ועוד."],["49","49","תהלים צה, ו. זח״ג ס״פ אמור. וראה פרקי דר״א פי״א."]]],[1300241211,"ענין העיקרי דר״ה, נאר דאס אליין איז אן ענין עיקרי אין ראש השנה\n[ביז אז דער עיקר הדין פון ר״ה איז „על הגופות״50, אויף ענינים גשמיים — וואס איז פארבונדן דערמיט וואס די התגלות פון „פנימיות רצון העליון״ דארף נמשך ווערן „למטה להתלבש בגשמיות״51].\nווייל אע״פ אז דער גילוי אלקות אין אן אופן פון „זה״ (ווי דאס איז אין דעם אדם), איז פיל העכער פון דעם גילוי וואס ווערט אויפגעטאן אין וועלט, כנ״ל — פונדעסטוועגן, איז די שלימות ענין הגילוי ווען עס נעמט דורך אלע ענינים, אויך די נידעריקע מדריגות אין וועלכע עס איז ניט א ראיית מהות אלקות, נאר בלויז א גילוי אין אן אופן פון „כה״52.\nועד״ד מ״ש הרמב״ם53, אז „כשם שהחכם ניכר בחכמתו כו׳ כך צריך שיהי׳ ניכר במעשיו במאכלו כו׳״: דער סימן פון אן אמת׳ן חכם, איז ווען זיין חכמה איז ניכר (ניט נאר דארטן וואו זיין מהות חכמה איז בגילוי, בלימודו, נאר) אויך אין די ענינים תחתונים שבו,\nוואס האבן לכאורה קיין שייכות ניט מיט „חכמתו״ — אז זיי ווערן געטאן בהתאם צו חכמתו.\nיא. ע״פ כל הנ״ל וועט מען אויך פארשטיין די שייכות צווישן דער כריתת ברית „להיות לו לעם״, „נהיית לעם״ — מיט „היום הזה״ (בחי׳ זה), און צווישן דער כריתת ברית „למען הקים גו׳ לו לעם״ מיט „היום״ (סתם, בחי׳ כה):\nדי צוויי בחינות פון „זה״ און „כה״ אין דעם אדם עצמו, זיינען נשמתו וגופו (אדער — עצם נשמתו, און חלק הנשמה המתלבש בגוף).\nביי מ״ת האט זיך אויפגעטאן דער עצם הברית צווישן אידן מיטן אויבערשטן („נהיית לעם״), וואס דאס איז בעיקר מצד הנשמה — וואס ביי איר איז אלקות מאיר בגילוי אין אן אופן פון „זה״; און כל זמן אידן זיינען געווען אין מדבר אויסגעשטאנען פון גשמיות העולם, איז דער ברית פאר זיי געווען מספיק צו אנהאלטן די התקשרות מיט הקב״ה:\nבשעת אבער זיי האבן געדארפט אריינגיין אין א״י, און ארץ נושבת, איז ניט גענוג די כריתת ברית שמצד הנשמה (עצמה). כדי זי זאל האבן א קיום אויך ווען א איד לאזט זיך אראפ אין ענינים גשמיים כו׳, איז דאס דורך דעם וואס די כריתת ברית שמצד הנשמה ווערט אויפגעטאן אויך אין דער נשמה המלובשת אין גוף, ועי״ז — מיטן עצם גוף, אז אויך אין דעם מצב זאלן זיי זיין „לפניו לעם״54 (ע״ד הנ״ל, ווי",[["50","50","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380956\" data-slug=\"likkutei-torah\" data-id=\"4001380956\">לקו״ת ר״ה נט, ב</a>. וש״נ."],["51","51","לקו״ת שם. וראה שם (והובא באוה״ת ד״ה זה היום הנ״ל), שלכן התקיעה, שענינה הצעקה דפנימיות הלב, צ״ל ע״י שופר גשמי דוקא."],["52","52","ע״פ המבואר בפנים יובן ג״כ מה שארז״ל (ספרי ורש״י ר״פ מטות — הובא בלקו״ת ואוה״ת (שצויינו לעיל הערה 43) לענין בחי׳ „זה״ ו„כה״ דר״ה וכי״ה אלול) „שכשם שנתנבא משה בכה אמר (בא יא, ד) כך נתנבאו נביאים בכה אמר, מוסף עליהם משה שנאמר בו (ר״פ מטות) זה הדבר״ — דלכאורה אינו מובן: מכיון דמשה נתנבא ב„זה״ (שלמעלה מ„כה״), מהי ההדגשה בזה, דגם משה נתנבא בכה אמר ככל הנביאים? וי״ל הביאור מפני שהשלימות דבחי׳ „זה״ היא כאשר נמשכת גם בבחי׳ „כה״. וראה לקו״ת שם (מז, ג) שיש מעלה גם בבחי׳ „כה״ (עצמה), שלכן צ״ל „התחברות ב׳ הבחי׳ יחד״."],["53","53","הל׳ דעות רפ״ה."],["54","54","משא״כ הכריתת ברית שלפנ״ז ענינה רק „לו לעם״ (ולא „לפניו״), כנ״ל — כי מכיון שהיא בהנשמה (מצ״ע), הרי כשהאדם הוא למטה, בגוף הוא „רחוק״ מאלקות (וראה לקו״ת פרשתנו (נעתק לעיל סוס״ה) „להקים ולרומם אותך כו׳״). בסגנון אחר קצת: „לו לעם״ היינו הבחי׳ בהאדם"]]],[1300241212,"בחי׳ „זה״ ווערט נמשך און טוט אויף אין בחי׳ „כה״),\nאון דאס איז גורם אז די כריתת ברית זאל האבן א קיום55 נצחי, אין אלערליי מצבים וואס אידן געפינען זיך.\nאון דעריבער, בכל שנה ושנה ווען עס קומט די צייט פון ראש השנה און די כריתת ברית ווערט נתעורר מחדש,\nזיינען אידן בטוח (און שוין פון ערב ראש השנה)56 אז זיי וועלן זוכה זיין בדין, און נוסף אויף די ענינים רוחניים (שמצד הנשמה), אויך אין ענינים גשמיים, כפשוטם (וואס זיינען פאר־בונדן מיטן גוף),\nאז עס ווערט נמשך לכל אחד ואחת מישראל א כתיבה וחתימה טובה לשנה טובה ומתוקה, סיי אין ענינים גשמיים — בני חיי ומזוני רוויחי כפשוטם, סיי אין ענינים רוחניים,\nובגשמיות וברוחניות גם יחד, ובטוב הנראה והנגלה.\n(משיחות מוצש״ק פ׳ נצבים תשל״ח, ש״פ תבוא תש״מ)",[["","","שהיא (מצ״ע) לא בקירוב לפניו ית׳ (עם מלשון עוממות), לא עצם נשמתו המיוחדת בו ית׳; והחידוש דהכריתת ברית דפרשתנו הוא שגם בחי׳ זו נעשה „לפניו לעם״ (וכן „עם״ בפירושו הב׳ — „אנשים כמותו״, כנ״ל סעיף ה). ועצ״ע."],["55","55","עד״ב בענין יחו״ע ויחו״ת, שהקיום בהעבודה דיחו״ת הוא ע״י הארת יחו״ע בה (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380772\" data-slug=\"likkutei-torah\" data-id=\"4001380772\">לקו״ת עקב יד, ג</a> ואילך. סידור קח, סע״ג ואילך (הובא באוה״ת ד״ה זה היום הנ״ל. ע״ש). קונטרס עה״ח פ״ז ואילך)."],["56","56","טור או״ח סו״ס תקפא."]]],[1300241213,"<h3>וילך</h3>\nא. אין דעם ציווי אויף מצות הקהל איז די התחלה „מקץ שבע שנים במועד שנת השמיטה בחג הסוכות“¹. איז רש״י מעתיק פון פסוק די ווערטער „מקץ שבע שנים“ און איז מפרש: בשנה ראשונה של שמיטה שהיא שנה שמינית² ולמה קורא³ אותה שנת השמיטה⁴ שעדיין שביעית נוהגת בה בקציר של שביעית היוצא למוצאי שביעית⁵.\nווי מען לערנט בפשטות⁶, איז די שאלה וואס רש״י קומט פארענטפערן: לשון הכתוב איז „מקץ שבע שנים“ דער סוף פון די זיבן יאר, פון דעם זיבעטן יאר⁷, און אזוי איז אויך מובן פון לשון „במועד שנת השמיטה“ אז דאס איז דער יאר פון שמיטה, און דערנאך איז דער פסוק מסיים „בחג הסוכות“ וואס איז ניט אין (סוף פון) זיבעטן יאר:\nאיז רש״י מפרש אז „מקץ שבע שנים“ דא מיינט „שנה ראשונה של שמיטה שהיא שנה שמינית“, דאס הייסט, אז „מקץ“ מיינט טאקע „סוף“, ווי רש״י טייטשט בר״פ מקץ „כל לשון קץ סוף הוא“⁸, אבער עס מיינט נאכן סוף⁹, נאך דעם ווי ס׳ענדיקן זיך די ז׳ שנים „שהיא שנה שמינית“.\nוויבאלד אבער אז פון דעם המשך הכתוב „במועד שנת השמיטה“ איז משמע אז דאס מיינט אין שנת השמיטה, איז רש״י ממשיך „ולמה קורא אותה שנת השמיטה“? און פארענטפערט „שעדיין שביעית נוהגת בה כו׳“.\nלפ״ז איז אבער ניט פארשטאנדיק:\nא) רש״י האט געדארפט מעתיק זיין אויך די ווערטער „בחג הסוכות“ (אדער עכ״פ זיי מרמז זיין מיט „וגו׳“), ווארום דאס איז דאך מעורר די שוועריקייט אין פסוק?\nב) אויב רש״י קומט מחדש זיין אז „מקץ שבע שנים“ מיינט דא נאכדעם ווי ס׳ענדיקן זיך די שבע שנים (ניט ווי מ׳וואלט געלערנט בפשטות אז דאס מיינט בסוף שנת השבע), האט ער בלויז געדארפט זאגן „שהיא שנה שמינית“ — פארוואס דארף ער מקדים זיין „בשנה ראשונה של שמיטה“¹⁰, וואס האט קיין שייכות ניט צו מפרש זיין דעם לשון „מקץ“, און גיט בכלל גאר ניט צו אין הבנת הכתוב¹¹, לכאורה?",[["1","1","לא, י־יד."],["2","2","כ״ה בדפוסים לפנינו ובדפוס ראשון „היא בשמינית“. ובדפוס ב׳ ובב׳ כת״י רש״י (שתח״י) „בשמינית“. וברוב כת״י רש״י (שתח״י) הוא „בשנה (ה)ראשונה של שמיטה“ והשאר ליתא."],["3","3","בדפוס שני „קרא“."],["4","4","בדפוס ראשון מוסיף כאן „והיא שמינית ולא (אלא) לפי שעדיין כו׳“."],["5","5","תיבות „היוצא למוצאי שביעית“ ליתא בדפוס שני."],["6","6","ראה דבק טוב, באר יצחק."],["7","7","ראה סוטה מא, סע״א: ואי כתב רחמנא שמיטה ה״א בסוף שמיטה, ובפרש״י (ד״ה בסוף שמיטה): קודם ר״ה של שמינית דהא מקץ שבע בסוף שנה משמע."],["8","8","ראה רא״ם כאן."],["9","9","ראה בארוכה רמב״ן ראה טו, א."],["10","10","ובדפוס ראשון התחלת פרש״י היא „מקץ שבע שנים של שנת השמיטה בשנה הראשונה של שמיטה“."],["11","11","ברע״ב ר״פ מקץ: וכן מה שאמר בפ׳ וילך מקץ שבע שנים במועד שנת השמיטה בחג הסוכות ר״ל בסוף השביעית . . ל׳ יום אחר השמיטה נחשב מן השמיטה. אבל לשון רש״י בתחלת לשונו „בשנה ראשונה של שמיטה שהיא שנה שמינית“ מדגיש להיפך. וראה לקמן בפנים סעיף ב."]]],[1300241214,"און ווי מען געפינט טאקע אין משנה וגמרא¹², אז מ׳רופט דעם זמן פון הקהל „בשמיני“, „בשמינית“, עס ווערט אבער ניט געזאגט אויף דעם אז דאס איז „שנה ראשונה של שמיטה“.\nב. לכאורה וואלט מען געקענט פארענטפערן (עכ״פ די צווייטע שאלה הנ״ל), אז רש״י קומט דא מחדש זיין אן אנדער פירוש סיי אין „מקץ“ סיי אין „שבע שנים“ (ובדרך ממילא — אויך שולל נאך א פירוש וואס מ׳וואלט גע־קענט לערנען אין פסוק):\nקס״ד צו זאגן — „מקץ“ פירושו „סוף“, און דאס מיינט דעם (גאנצן) זיבעטן יאר, וועלכער איז דער „מקץ“ פון דער תקופה פון שבע שנים¹³, אז צום סוף פון „זיבן יאר תקופה“ (היינו — דער גאנצער זיבעטער יאר), וואס איז „מועד שנת השמיטה“, אין דעם זמן פון חג הסוכות פון זיבעטן יאר זאל זיין „הקהל גו׳“.\nאיז רש״י שולל דאס ומפרש אז „מקץ שבע שנים“ דא איז א יוצא מן הכלל, דא מיינט עס ניט „סוף“, נאר — „התחלה“¹⁴ (ע״ד ווי מען געפינט בכמה מפרשי התורה¹⁵ — בפ׳ מקץ) „שנה ראשונה של שמיטה“ — דער אנפאנג פון זיבן יאר הבאות¹⁶.\nלפ״ז איז אבער ניט פארשטאנדיק לאידך: וואס רש״י איז מוסיף „שהיא שנה שמינית“ — זי איז א המשך פון דער פריערדיקער שמיטה.\nועוד ועיקר: אויב רש״י קומט מחדש זיין אין די ווערטער „מקץ שבע שנים“, אז עס איז אנדערש ווי פירושו בכל מקום, וואלט ער עס געדארפט זאגן א) בלשון חידוש אז ס׳איז ניט ווי דער כלל וואס ער אליין זאגט „כל לשון קץ סוף הוא“, און ברענגען א ראי׳ צו דעם פירוש. ב) עס האט געדארפט שטיין אלס טייטש פון די ווערטער „מקץ שבע שנים — שנה ראשונה של שמיטה“.\nפון לשון רש״י „בשנה ראשונה של שמיטה“¹⁷ איז משמע, אז ניט ער קומט אפטייטשן דעם ווארט „מקץ (שבע שנים)“, נאר — זאגן און מפרט זיין אין וועלכן זמן דאס איז — „בשנה ראשונה של שמיטה שהיא שנה שמינית“¹⁸.",[["12","12","סוטה שם."],["13","13","ע״ד פרש״י בא י, כב."],["14","14","כי ל׳ מקץ הוא מלשון קצה שיתכן גם על ההתחלה שהוא קצה הראשון. או „כי גם לפעמים הקץ הראשון מהענין יקרא קץ כי הוא סופו מהקצה ההוא“ (חידושי ופירושי מהרי״ק ר״פ מקץ). וראה בכ״ז בהנסמן בהערה הבאה."],["15","15","ראב״ע כאן, ובפ׳ ראה טו, א. אלא שלדעתו פירושו — תחלת שנת השמיטה. ראה גם פירושו בשמות כ, ח ופירושו כאן בפסוק יב. וכן מפורש באברבנאל כאן. וראה רמב״ן פ׳ ראה שם בארוכה. רא״ם (וגו״א) ר״פ מקץ. וראה פסיקתא זוטרתא כאן. *) וכ״פ הרד״ק (בספר השרשים ערך קצץ) ב„מקץ שבע שנים“ דראה שם. וברמב״ן ראה שם „וכן אמרו המדקדקים כולם“. וראה ספר זכרון ר״פ מקץ."],["16","16","והטעם שאינו מפרש ש„מקץ שבע שנים“ קאי על כל השנה — י״ל כי אינו מסתבר שהכתוב יקרא כן את כל השנה משום פעולה חד פעמית שבתחלת השנה. משא״כ ב„מקץ שבע שנים תעשה שמיטה“ להפי׳ שקאי על כל השנה, שמדובר בשמיטת קרקעות שזהו בכל השנה, ראה רמב״ן שם. ואי״ז שייך למ״ש רש״י (בהר כה, יו״ד): יובל הוא, שנה זו מובדלת משאר שנים בנקיבת שם לה לבדה ומה שמה יובל שמה על שם תקיעת שופר (אף שגם זה הוא פעולה א׳ בתחילת השנה), כי שם הר״ז בנוגע לנקיבת שם׳ (ובשעת התקיעה נקרא, ובמילא — נשאר כן ונקבע השם), משא״כ בנדו״ד שהמדובר בפי׳ הכתוב „מקץ שבע שנים“. ועצ״ע."],["17","17","ופשיטא לפי הגירסא בדפוס ראשון שמפרש „מקץ שבע שנים של שנת השמיטה“ ורק אח״כ כותב „בשנה ראשונה של שמיטה“."],["18","18","לכאורה יש לומר שרש״י מפרש הכתוב ע״ד *) ועד״ז נתבאר טעם שיש לקרות את כל השנה „שנת הקהל“ — ראה שיחת ש״פ ואתחנן תשמ״א (לקו״ש חל״ד ע׳ 329 בהערה)."]]],[1300241215,"אויך דארף מען פארשטיין בכלל: וואס איז דא נוגע אז דאס איז „(מועד) שנת השמיטה, שעדיין שביעית נוהגת בה בקציר של שביעית היוצא למוצאי שביעית“ —\nדעם איסור בקציר של שביעית היוצא למוצאי שביעית ווייס מען שוין (לויט איין דיעה) פון פריער בפרש״י אויף „בחריש ובקציר תשבות“¹⁹; ובכל אופן האט דאך דאס קיין שייכות ניט לציווי פון הקהל צו זאגן דיני שביעית, אז דע־מאלט זיינען נאך נוהג כמה דינים פון שביעית.\nג. דער ביאור בזה:\nרש״י דארף ניט מפרש זיין דעם טייטש פון „מקץ“, ווייל ער האט שוין מפרש געווען, כנ״ל, אז „כל לשון קץ סוף הוא“, ובמילא מובן, אז בכל מקום איז פירושו ווי דארטן ביי „ויהי מקץ“²⁰, אז אויך דא איז דער פירוש — לאחר²¹ די שבע שנים²².\nרש״י קומט אבער מבאר זיין דא א שאלה כללית אין דעם זמן פון מצות הקהל.\n[וכמדובר כמה פעמים, אז בכ״מ פאר־ענטפערט רש״י אן ענין כללי אין דער פרשה גלייך בתחלת הענין, כאטש די שאלה ווערט ערשט לויט די ווייטער־דיקע פסוקים — וויבאלד אז דאס איז די פסוקים פון דער פרשה, און דאס איז אן ענין כללי (נוגע צו אלע פסוקים), איז ער דאס מסביר תיכף בתחלת הענין].\nובהקדים: אויך בפשוטו של מקרא — זעט מען אז אין מצות התורה זיינען פא־ראן מצות וואס האבן א טעם און עס זיינען דא חוקים וואס האבן ניט קיין טעם; צווישן די מצות וואס האבן א טעם (צי תורה איז מפרש זייער טעם, אדער דער טעם איז מובן מעצמו), זיינען פא־ראן מצות וואס אויך זייערע פרטים האבן א טעם, און מצות וואס זייערע פרטים האבן (ע״ד הפשט) ניט קיין טעם²³.\nבמצות הקהל איז מפורש בפסוק דער טעם ומכוון המצוה — „למען ישמעו ולמען ילמדו ויראו את ה״א גו׳“²⁴ [און אזוי זיינען אויך מובן די טעמי הפרטים וואס די תורה זאגט: בבוא כל ישראל לראות את פני ה״א במקום אשר יבחר²⁵ — דעמאלט איז גרינגער מקהיל זיין אלע אידן, און אזוי אויך דער „מקום אשר יבחר“, איז מער מתאים אויף פועל׳ן „למען ישמעו ולמען ילמדו ויראו גו׳“].",[["","","מ״ש בגמרא („דאי כתב רחמנא מקץ הוה אמינא נימנו מהשתא ואע״ג דלא מתרמי בשמיטה“ — ראה פרש״י שם), והיינו שהי׳ אפשר לפרש שהציווי דמשה „הוי מקץ שבע שנים לכניסתם לארץ אז יעשו הקהל ואין מצוה לדורות (ראה עד״ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191336\" data-slug=\"likkutei-sichot\" data-id=\"1300191336\">לקו״ש חי״ט ע׳ 323</a> בביאור פרש״י בפסוק יא). ולשלול זה מפרש רש״י „בשנה ראשונה של שמיטה שהיא שנה שמינית“ (ובפרט לפי הגירסא בדפוס ראשון כנ״ל). והיינו שהוא מצוה לדורות, בשנה ראשונה של שמיטה. אבל לפ״ז: א) אינו מובן האריכות בפרש״י ב) הוצרך רש״י להעתיק מהכתוב גם התיבות „שנת השמיטה“."],["19","19","תשא לד, כא."],["20","20","ראה גם גו״א ודקדוקי רש״י (מירא דכיא) שם. ובכמה מפרשי רש״י שם. לקו״ש ח״ה ע׳ 196 ואילך. ובהערות שם."],["21","21","ראה פרש״י בכתוב דלפני „ויהי מקץ“ — „אסור שתי שנים“."],["22","22","ראה רמב״ן ראה שם. בחיי כאן. וגם בראה שם „מקץ שבע שנים תעשה שמיטה“ לא פרש״י אם הסוף מכלל השבע כי מובן הוא מפירושו שצ״ל שבע שנים שלימות. ולשון „מקצה שלש שנים“ (שם יד, כח) — ראה פרש״י תבוא כו, יב."],["23","23","ראה גם ע״ד החקירה והחסידות מו״נ ח״ג פכ״ו. אגה״ק סי״ט (קכח, א)."],["24","24","לא, יב."],["25","25","לא, יא."]]],[1300241216,"לפ״ז פאדערט זיך א ביאור וואס די תורה זאגט אז דער זמן (המתאים) איז „מקץ שבע שנים“: צו מעורר זיין אויף טא׳ן א זאך, ובפרט אויף יראת ה׳, וואס דאס איז דער מכוון אין מצות הקהל, דארף עס זיין ניט בסיום פון א תקופה, נאר אין דער התחלה פון א תקופה.\nאיז רש״י מפרש אז אין הכי נמי — דאס מיינט טאקע „בשנה ראשונה של שמיטה“.\nלפ״ז איז אבער ניט מובן פארוואס שטייט אין פסוק „מקץ שבע שנים“, וואס דאס איז מדגיש אז דאס קומט אלס א סוף (והמשך) פון די שבע שנים — זאגט רש״י „שהיא שנה שמינית“: דא איז נוגע אויך דער ענין וואס זי איז די שנה שמינית, דער יאר וואס קומט נאך שנה שביעית וועלכע איז א שנת שמיטה.\nד. די הסברה בזה:\nבשנת השמיטה, ווען „שבת שבתון יהי׳ לארץ . . שדך לא תזרע וכרמך לא תזמור את ספיח קצירך לא תקצור ואת ענבי נזירך לא תבצור“²⁶, איז פאר־שטאנדיק אויך אין פשוטו של מקרא, אז דעמאלט, זייענדיק פנוי פון עבודת האדמה וואס דאס איז געווען (דער עיקר פון) זייער באשעפטיגונג²⁷, האבן אידן (מער — ובעיקר) זיך אפגעגעבן מיט לימוד התורה, וואס האט גע־בראכט צו יראת ה׳ ושמירת המצות²⁸.\nועפ״ז איז מובן דער קשר צווישן מצות הקהל (וואס איז „בשנה הראשונה של שמיטה“) און שנת השמיטה (שלפנ״ז): ווען מ׳דארף אנהויבן די „שש שנים תזרע שדך ושש שנים תזמור כרמך“²⁹ אין דעם ערשטן יאר פון שמיטה, דארף מען האבן א ספעציעלע התעוררות וואס זאל פועל זיין אויך די ווייטערדיקע זעקס יאר, אז (אויך) דעמאלט זאל זיין „ויראו את ה״א ושמרו לעשות את כל דברי התורה הזאת“³⁰ —\nאון דאס פועלט מען דורך דער־מאנען זיך אויף דער שנת השמיטה, ווען מ׳האט זיך אפגעגעבן אין לימוד התורה כו׳ און זיך אנגעזאפט מיט יראת ה׳. דער תוכן פון מצות הקהל איז, צו פארזעצן און שטארקן די התעוררות פון דעם שמיטה־יאר אויך אין די זעקס נאכ־קומענדיקע יאר, ווען מ׳איז פארנומען אין עבודת האדמה.\nאון דאס דייטעט אז רש״י מיט זיין אנ־רופן דעם יאר — „שהיא שנה שמינית“: דער ערשטער פון די זעקס יאר, דארף זיין (ניט בלויז א התחלה פון דער נייער שמיטה, „שנה ראשונה של שמיטה“, נאר אויך) א המשך פון דעם פריערדיקן יאר. דאס איז אן אכטער יאר וואס קומט נאך דעם שנה השביעית.\nה. עפ״ז וועט מען אויך פארשטיין דעם ענין פון „קורא אותה שנת השמיטה שעדיין שביעית נוהגת בה כו׳“ — וואס איז, כנ״ל, לכאורה ניט מובן פארוואס דער פסוק (אין פ׳ הקהל) דארף מודיע זיין ש„עדיין שביעית כו׳“ — דאס איז ניט סתם א (זייטיקער) סימן אויפן יאר (וואס האט אבער קיין שייכות ניט צום תוכן פון מצות הקהל):\nצו פארזעצן די התעוררות פון דעם פריערדיקן שמיטה יאר, איז דער פסוק מדגיש, אז אויך דער אכטער יאר איז",[["26","26","בהר כה, ד־ה."],["27","27","כמובא בכ״מ בפשוטו של מקרא — ראה ר״פ בחוקותי. ועוד."],["28","28","ראה ספורנו שם, ד. אברבנאל כאן — לפירושו הקהל הוא בתחלת שנה השביעית. ראב״ע שמות שם. ועוד."],["29","29","בהר שם, ג."],["30","30","פרשתנו לא, יב."]]],[1300241217,"„שנת השמיטה“, ווייל „עדיין שביעית נוהגת בה“: ניט נאר איז אין דער התחלה פון „שנה הראשונה של שמיטה“ דא דער זכרון און די התעוררות פון דעם פריערדיקן שמיטה יאר, נאר מ׳האט אויך שמיטה בפועל (אין דעם „קציר של שביעית היוצא למוצאי שביעית“), ובמילא — נאך פרייע צייט אויף לימוד התורה וכו׳.\nו. מענינים מופלאים ע״ד ההלכה וואס מ׳קען ארויסנעמען פון דעם פרש״י:\nאין דעם וואס די מצוה פון הקהל איז „מקץ שבע שנים במועד שנת השמיטה“, אז דאס איז דער יאר נאך שמיטה, קען מען קלערן צי דאס איז בלויז א סימן אין וועלכן יאר מ׳דארף מקיים זיין מצות הקהל — בשמינית, אין דעם יאר נאך שמיטה³¹, אדער — ס׳איז תלוי אין (דעם קיום פון) מצות שמיטה.\nדי נפק״מ דערפון³² בפועל קומט ארויס בזמן בית שני, לויט די דיעות אז דעמאלט איז מצות שמיטה געווען נאר מדרבנן: לויט דער ערשטער סברא, אז ס׳איז בלויז א סימן ווען מ׳דארף מקיים זיין מצות הקהל, איז מובן, אז אויך דעמאלט איז מען געווען מחוייב במצות הקהל מה״ת. און לויט דער צווייטער סברא, איז מען דעמאלט געווען פטור מה״ת.\nע״פ הנ״ל אין הסברת לשון רש״י (ובפרט סיום לשונו „ולמה קורא אותה שנת השמיטה שעדיין שביעית נוהגת בה כו׳“), אז דאס איז א המשך פון דעם קיום מצות שמיטה בשנת השביעית, קומט אויס, אז מצות הקהל איז תלוי אין דעם קיום מצות שמיטה מה״ת.\n[דאס איז אבער ניט מוכרח. מ׳קען זאגן, אז אויב נאר מ׳איז מקיים מצות שמיטה בשנת השבע, אפילו נאר מד־רבנן, וויבאלד אז לפועל איז מען שובת מעבודת האדמה, הייסט עס לגבי מצות הקהל מה״ת — א שנת השמיטה ער אקערט ניט וכו׳, און מ׳איז אויך דעמאלט מחוייב אין מצות הקהל³³.\nוע״ד ווי מ׳געפינט אז א קנין מדרבנן העלפט אויף ענינים מה״ת³⁴].\nז. מען דארף נאך אבער פארשטיין (בפנימיות הענינים):\nדער תוכן פון שנת השמיטה, וועל־כער איז מפורש בתורה (שבכתב), איז (ניט דאס וואס אידן וועלן במשך דעם יאר (ווען מ׳איז פנוי פון עבודת הא־דמה) זיך פארנעמען מערער מיט לימוד התורה כו׳, נאר) — „שבת שבתון יהי׳ לארץ גו׳ שדך לא תזרע וכרמך לא תזמור“;\nאון דאס פועלט אויך אין די שפעטערדיקע „שש שנים“ ווען „תזרע שדך“ און „תזמור כרמך“, וויבאלד בקיום מצות שמיטה ווייזט א איד אן בא־ווייזט בפועל אז „אין דבר מיוחד ברשותו רק שהכל ברשות אדון הכל“³⁵, אז דער אויבערשטער איז דער בעה״ב",[["31","31","כדהמשמע לכאורה מפשטות לשון רש״י סוטה שם „כל הסימנין הללו מקץ שנת השמיטה כו׳“."],["32","32","ראה בכ״ז אנציקלופדי׳ תלמודית ערך הקהל. וש״נ."],["33","33","וראה עד״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011285\" data-slug=\"likkutei-sichot\" data-id=\"1300011285\">לקו״ש ח״א ע׳ 271</a> ואילך דע״י דספה״ע דרבנן בתחלת ימי הספירה מהני לחיובו בספה״ע מדאורייתא לאחרי זה, כי לאחרי שישנה למציאות הספירה מצד המצוה דרבנן, הר״ז מועיל לדאורייתא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081054\" data-slug=\"likkutei-sichot\" data-id=\"1300081054\">לקו״ש ח״ח ע׳ 54</a> ואילך. לקו״ש חה״ש תנש״א. סה״ש תנש״א ח״א ע׳ 452 ואילך."],["34","34","ראה הדיעות בזה: פס״ד להצ״צ ואו״ח סתמ״ח ס״ג, בספרים שנסמנו בשד״ח כללים מערכת הקו״ף כלל ח״י. ועוד."],["35","35","חינוך מצוה שכח. וראה חינוך מצוה פד."]]],[1300241218,"אויף זיין שדה און אויף אלץ וואס איז דא אין וועלט (כמבואר בארוכה אין מפרשי טעמי המצות³⁶), און דערפאר איז זיין „תזרע“ און „תזמור“ אין די „שש שנים“ בהתאם צום רצון השם, דער רצון פונעם בעה״ב פון דער וועלט.\nאון וויבאלד די תורה איז מדגיש אז מצות הקהל איז „במועד שנת השמיטה“ — וכנ״ל, אז הקהל איז א פארזעצונג פון (דער התעוררות פון) שנת השמיטה, ווי דאס קומט אין „שנה שמינית“ — דארף מען זאגן, אז אויך די התעוררות פון שמיטה ווערט נמשך אין די שש שנים דורך דער התעוררות פון הקהל —\nדארף מען פארשטיין: וואו געפינט מען אין הקהל א התעוררות אויף דעם ענין?\nויש לומר, אז דאס איז פארבונדן מיט די פרשיות בתורה וואס דער מלך לייענט בהקהל, ווי די משנה³⁷ רעכנט זיי אויס (לגירסת רש״י³⁸): מתחלת אלה הדברים עד שמע ושמע³⁹ והי׳ אם שמוע⁴⁰ עשר תעשר⁴¹ כי תכלה לעשר⁴² ברכות וקללות⁴³ און פרשת המלך אשימה עלי מלך⁴⁴.\nח. דער ביאור בזה:\nמצות שמיטה טיילט זיך, בכללות, אין דריי ענינים:\nא) „שביתת האדם“⁴⁵ — דער איסור אויפן אדם צו פארנעמען זיך מיט עבודת האדמה⁴⁶, אפגעבן זיך אינגאנצן מיט לימוד וכו׳, כנ״ל.\nב) שביתת הארץ — „ושבתה הארץ שבת לה׳“⁴⁷: וויבאלד די ארץ איז דאן שובת פון אלע עבודות, עס ווערט דעם יאר ניט געטאן קיין עבודת האדמה, איז עס בא ארץ גופא אן ענין פון „שבת לה׳“.\nג) די פירות וואס וואקסן אויס בשנת השמיטה זיינען הפקר לכל, דער בעה״ב פון שדה טאר זיי ניט האלטן אלס א זאך וואס באלאנגט צו אים⁴⁸.\nדער מכוון כללי ועיקרי פון מצות שמיטה איז, כנ״ל, צו באווייזן ווי „הכל ברשות אדון הכל“ — איז י״ל אז אין יעדערן פון די דריי ענינים הנ״ל דריקט זיך אויס א באזונדער פרט אין דער „בעלות“ פון אויבערשטן⁴⁹, כדלקמן.\nט. דער ענין פון שביתת האדם איז מדגיש די „בעלות“ ואדנות פון דעם אויבערשטן אויפן אדם — „אני נבראתי",[["36","36","ראה גם רמב״ן בהר כה, ב. אברבנאל ר״פ בהר."],["37","37","סוטה שם."],["38","38","סוטה שם. וראה גירסת הירושלמי במשנה שם. רמב״ם פיה״מ שם. הל׳ חגיגה פ״ג ה״ג. לח״מ שם."],["39","39","ואתחנן ו, ד־ט."],["40","40","עקב יא, יג־כא."],["41","41","ראה יד, כב־כו."],["42","42","תבוא כו, יב־טו."],["43","43","שם כח, א־סט."],["44","44","שופטים יז, יד־כ."],["45","45","המ״ע „בחריש ובקציר תשבות“, „לשבות מעבודת הארץ ועבודת האילן“ (לשון הרמב״ם ריש הל׳ שמיטה ויובל. ועד״ז בסהמ״צ ובמנין המצות מ״ע קלה)."],["46","46","הלאוין שבו „שדך לא תזרע גו׳“ „שלא יעבוד עבודת הארץ בשנה זו“ (לשון הרמב״ם בהכותרת להל׳ שמיטה ויובל מצוה ב. וראה סהמ״צ ומנין המצות מל״ת רכ ואילך)."],["47","47","בהר כה, ב. „שבת שבתון יהי׳ לארץ“, „שנת שבתון יהי׳ לארץ“ (שם, ד־ה). ובלשון הרמב״ם בהכותרת להל׳ שמיטה ויובל (מצוה א). „שתשבות הארץ בשביעית“. וראה השקו״ט בכל הנ״ל <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171286\" data-slug=\"likkutei-sichot\" data-id=\"1300171286\">לקו״ש חי״ז ע׳ 286</a>. וש״נ."],["48","48","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171287\" data-slug=\"likkutei-sichot\" data-id=\"1300171287\">לקו״ש שם ע׳ 287</a> ואילך. וש״נ."],["49","49","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171487\" data-slug=\"likkutei-sichot\" data-id=\"1300171487\">לקו״ש חי״ז ע׳ 476</a> ואילך."]]],[1300241219,"לשמש את קוני“⁵⁰:\nאז א איד פארנעמט זיך מיט עניני העולם איז ער עלול בשעת מעשה צו פארגעסן אויף תכלית בריאתו, אז ער איז אן עבד ה׳, און זיין רצון און עבודה דארף זיין צו ווערן דבוק צום אויבערשטן.\nהאט דער אויבערשטער ב״ה יעדע זעקס יאר געגעבן איין יאר, ווען א איד דארף זיין אפשיידן פון עניני העולם און זיך אפגעבן אינגאנצן מיט עבודה רוחנית (אין וועלכער עס איז ניכר בגלוי זיין דביקות בה׳); און דאס גיט א אידן כח, אז ווען עס קומט דערנאך „שש שנים תזרע שדך גו׳“ זאל ער פועל׳ן, אז אויך די התעסקות איז אן ענין פון עבודת ה׳, „לשמש את קוני“ — ער טוט עס לשם שמים⁵¹, ביז „בכל דרכיך דעהו“⁵².\nשביתת הארץ איז מדגיש די בעלות פון אויבערשטן — אויף דער ארץ בכלל — אויף טבע (וחוקי הטבע בכלל), ווי דער פסוק זאגט⁵³ „וכי תאמרו מה נאכל בשנה השביעית הן לא נזרע ולא נאסוף את תבואתנו, וצויתי את ברכתי לכם בשנה הששית ועשת את התבואה לשלש השנים“:\nע״פ חוקי הטבע איז די צמיחה און וואוקס פון דער תבואה תלוי אין דעם פריערדיקן אקערן און זייען: באווייזט דער אויבערשטער אין שנת השמיטה, אז דאס איז ער וואס מאכט וואקסן תבואה און פירות — עס „לא בכחה וסגולתה“⁵⁴, און עפ״ז איז עס אפ־הענגיק אין חרישה וזריעה, נאר „הוא הנותן לה כח לעשות חיל“; און ווען דער אויבערשטער וויל, וואקסט תבואה שלא ע״פ חוקי הטבע ביז אז די זריעה פון איין יאר, שנה הששית, ווערט (למעלה מהטבע) גענוג אויף דריי יאר — „ועשת את התבואה לשלש השנים“.\nאון פון דעם נעמט מען די הכרה און הרגש אויך אין די שש שנים ווען מ׳איז חורש וזורע, אז די תבואה וואס וואקסט בא אים אין שדה איז באמת ניט מצד דער חרישה וזריעה, נאר מצד ברכת ה׳⁵⁵.\nיו״ד. דער דריטער ענין אין שמיטה — וואס פירות שביעית זיינען הפקר — ברענגט ארויס ווי דער אויבערשטער איז דער בעה״ב אויף נכסי האדם. אויך נאך דעם וואס דער אויבערשטער בענטשט א אידן מיט נכסים, פאר־בלייבן זיי אין דעם אויבערשטנ׳ס בעלות ורשות.\nמ׳קען דאך טראכטן: הן אמת אז נאר דער אויבערשטער גיט די ברכה און כח אז די תבואה זאל וואקסן (און ניט זיין חרישה וזריעה, אדער „סגולת“ הארץ), אבער נאך דעם ווי דער אויבערשטער האט אים געגעבן די ברכה, און די תבואה איז אויסגעוואקסן און איז ביי",[["50","50","קדושין בסופה."],["51","51","אבות פ״ב מי״ב."],["52","52","משלי ג, ו. רמב״ם הל׳ דיעות ספ״ג. טושו״ע או״ח סרל״א."],["53","53","בהר כה, כ־כא."],["54","54","חינוך מצוה פד. בחינוך כתב זה בהמצוה „והשביעית תשמטנה“ — „להפקיר כל מה שתוציא הארץ“, „לכן ציוה ב״ה להפקיר כ״מ שתוציא הארץ בשנה זו מלבד השביתה בה כדי שיזכור האדם כי הארץ שמוציאה אליו הפירות בכל שנה ושנה לא בכחה וסגולתה כי יש להם אדון על אדוני׳. אבל רש״י מפרש: תשמטנה זו שהיא להפקיר כל פירותי׳ ומצוה אחרת שאינו רשאי לשנות בה כי קודש הוא להם. ובמצוה שכו „שביתת קרקעות“ כ׳ „שורש מצוה זו כר כתב בס׳ אם כסף תלוה מצוה פד קחנו משם“."],["55","55","להעיר ממשנ״ת בכ״מ (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011230\" data-slug=\"likkutei-sichot\" data-id=\"1300011230\">לקו״ש ח״א ע׳ 216</a>. ועוד) בפי׳ הירושלמי (הובא בתוד״ה אמונת שבת לא, א) שמאמין בחי העולמים וזורע."]]],[1300241220,"אים, האט דאך דער אויבערשטער אפגעגעבן די תבואה לרשותו.\nאמת טאקע, אז וויבאלד „אני (לא⁵⁶) נבראתי (אלא⁵⁶) לשמש את קוני“, און דעריבער איז קלאר, אז אויך אלץ וואס א איד פארמאגט דארף אויסגענוצט ווערן „לשמש את קוני“ (דורך נוצן עס אין עניני קדושה, אדער „כל מעשיך לשם שמים“ כנ״ל) — אעפ״כ איז פארט דא אן ארט פאר א הרגש אז די נכסים באלאנגען צו אים, נאר ער איז מחליט און נוצט זיי בהתאם צום רצון השם.\nלערנט דער דריטער ענין פון שביעית, אז א איד האט ניט קיין (אייגענע) בעלות אויף זיינע נכסים — וואס דאס דריקט זיך אויס אין דעם וואס אין מאל זיבן יאר זאגט אן תורה, אז אלע פירות וועלכע זיינען אויסגע־וואקסן ביי אים אין פעלד, זיינען הפקר לכל⁴⁹;\nדאס דערמאנט, אז אויך אין די שש שנים ווען ער מעג האלטן די פירות פאר זיך, איז עס ניט ווייל זיי געהערן אים (צו טאן מיט זיי וואס ער וויל), נאר זיי זיינען דעם אויבערשטנ׳ס נכסים וועלכע זיינען אים געגעבן געווארן (בפקדון?!), אז ער זאל זיין דעם אויבערשטנ׳ס שליח צו דורכפירן מיט זיי דאס וואס דער אויבערשטער וויל.\nיא. עפ״ז וועט מען פארשטיין די שייכות פון מצות הקהל אויך צו פרטי מצות שמיטה⁵⁷ —\nדער תוכן פון די דריי ענינים הנ״ל [שביתת האדם, שביתת הארץ און דאס וואס פירות שביעית זיינען הפקר לכל — וואס דריקן אויס די „בעלות“ של הקב״ה אויפן אדם, ארץ (וחוקי הטבע) און נכסי האדם]\nאיז דער (חלק ה)תוכן פון די פרשיות וועלכע מען לייענט בהקהל: פרשת שמע⁵⁸, והי׳ אם שמוע, און „עשר תעשר“, „כי תכלה לעשר“:\nאין פרשה שמע רעדט זיך וועגן דער עבודה הרוחנית פון א אידן — קבלת עול מלכות שמים⁵⁹, לימוד התורה, קיום המצות (תפלין ומזוזה), וואס דאס איז בהתאם צום ערשטן ענין הנ״ל אין שמיטה — שביתת האדם, כדי ער זאל קענען זיין פנוי אויף צו אפגעבן זיך מיט ענינים רוחניים, כנ״ל.\nאין פרשת והי׳ אם שמוע רעדט זיך — ווי דורך „שמוע תשמעו גו׳“ איז — „ונתתי מטר ארצכם בעתו גו׳ ואספת דגנך גו׳“ (און אויב ח״ו „וסרתם גו׳“, איז — „ולא יהי׳ גו׳ והאדמה לא תתן גו׳“). דאס איז מדגיש ווי דער אויבערשטער — דער בעל הבית אויף חוקי הטבע, און דערפאר איז די גשמיות פון א אידן, „ואספת דגנך גו׳“, אפהענגיק (ניט אין דער חרישה וזריעה של האדם, נאר) אין „תשמעו גו׳ תשמעו אל מצותי“, אין אויס־",[["56","56","כ״ה ביל״ש ירמי׳ רמז רעו."],["57","57","י״ל שזהו גם טעם נוסף ע״ז שמצות הקהל נאמרה בסוף זמן היותם במדבר ולפני כניסתם לא״י, כי החילוק דשנת השמיטה (שבת לה׳) להשש שנים שלאחרי׳, הוא כדוגמת החילוק בין מצב בנ״י במדבר שהי׳ להם לחם מן השמים בלי שום עבודה ויגיעה (ולא הי׳ מקום לטעות הנ״ל), למצב בנ״י בא״י שהותחל סדר דעבודת אדמה כו׳. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161176\" data-slug=\"likkutei-sichot\" data-id=\"1300161176\">לקו״ש חט״ז ע׳ 176</a> ואילך."],["58","58","אלא שקורא „מתחילת אלה הדברים“ — דברי תוכחה שהוא כעין הקדמה כללית שיקבע בלבם תוכן הפרשיות שקורא לאח״ז: ולהעיר שלדעת רבי (תוספתא סוטה פ״ז, ט) לא הי׳ צריך להתחיל מראש הספר אלא שמע והי׳ אם שמוע עשר תעשר וכי תכלה לעשר ופרשת המלך עד שגומר את כולה."],["59","59","פרש״י סוטה שם."]]],[1300241221,"פאלגן דעם אויבערשטנ׳ס רצון⁶⁰.\nאון די פרשיות „עשר תעשר“, „כי תכלה לעשר“ זיינען מדגיש, ווי די נכסים פון א אידן זיינען ביי אים ווי א פקדון פון דעם אויבערשטן⁶¹ און דער אדם איז אויף זיי ניט קיין בעה״ב; וואס דאס דריקט זיך אויס אין דעם וואס א חלק פון זיינע נכסים מוז ער אוועק־געבן (א צווייטן אידן)⁶² — „מתנות עניים“ און „הפרשת התרומות ומעש־רות“⁵⁹: בדוגמא צו פירות שביעית וועלכע זיינען הפקר לכל⁶³.\nאון דערפאר איז מען דערנאך מסיים די קריאה מיט פרשת המלך⁶⁴ (און אויך די קריאה פון אלע פרשיות הנ״ל איז דורכן מלך) — ווייל די אמת׳ע הכרה ווי דער אדם וכל אשר לו און די גאנצע בריאה זיינען ניט קיין מציאות פאר זיך, נאר אלץ געהערט צו דעם אויבערשטן, ווערט אויפגעטאן דורך דעם מלך; ווארום התפקיד העיקרי פונעם מלך איז צו ממשיך זיין צו (און — אין) דעם ענין פון קבלת עול מלכות שמים און יראת ה׳, ביז צום הרגש פון אמיתי׳ ביטול (וואס גיט ניט קיין ארט פאר א מציאות ורצון פון אויבערשטן), ווי דער צ״צ איז דאס מבאר בארוכה⁶⁵.\nיב. דאס איז אויך דער ביאור פנימי וואס דער דין פון „עדיין שביעית נוהגת בה“ (אין שנה שמינית) איז דוקא אין דעם „קציר של שביעית היוצא למוצאי שביעית“:\nדי הכרה (וואס מ׳נעמט ארויס פון שביתת הארץ) אז דער אויבערשטער איז בעה״ב אויף ארץ (וחוקי הטבע), איז סיי ווי דא אין „שנה השמינית“, ווייל מ׳עסט נאך (און דער חיות האוכל איז) פון דער תבואה וואס איז געצייט געווארן בשנה הששית, ווי דער פסוק זאגט⁶⁶ „וזרעתם את השנה השמינית ואכלתם מן התבואה ישן עד השנה התשיעית“ — מען זעט דא אין גילוי ברכת השם (לויט טבע הארץ קען זי ניט זיין בשנה השמינית).\nכדי אז מ׳זאל אויך האבן (אין דער שנה השמינית גופא) די הכרה, אז דער אדם וכל אשר לו געהערט צום אויבערשטן, איז דא דער צווייטער ענין אין שנה השמינית, אז „עדיין שביעית נוהגת בה בקציר של שביעית היוצא למוצאי שביעית“ — אז אויך אין שנה השמינית איז דער אדם ניט קיין בעה״ב אויף דעם קציר (וואס איז פון זיין שדה), ובמילא איז ער מרגיש ומכיר ווי דאס געהערט דעם אויבערשטן.\nובמילא, בשעת ס׳איז דער זמן ווען עס פילט זיך א מעין פון תוכן ענין השמיטה, הן אין דעם וואס מ׳עסט אז אויך דאן שפייזט דער אויבערשטער דעם מענטשן, הן אין דעם וואס דער מענטש פילט אז ער איז ניט א מציאות",[["60","60","בפרש״י שם „והי׳ אם שמוע קבלת עול מצות“."],["61","61","ראה ד״ה א״ר שמואל בר נחמני תר״ץ פ״ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131235\" data-slug=\"likkutei-sichot\" data-id=\"1300131235\">לקו״ש חי״ג ס״ע 229</a> ואילך. וש״נ."],["62","62","חינוך מצוה סו: שנעשינו שלוחים לזכותם לזכותינו."],["63","63","ולכן לאח״ז דוקא קורא „ברכות וקללות קבלת בריתות של תורה“ (ל׳ רש״י סוטה שם), כי לאחרי שקובע בדעת האדם שהוא וכל אשר לו שייך להקב״ה, אז מקבל התורה באופן של ברית, שנעשו דבר אחד."],["64","64","ועפ״ז מובן הסדר לגירסת ופי׳ רש״י (סוטה שם) דקורא פרשת המלך לבסוף."],["65","65","סהמ״צ מצות מינוי מלך. עיי״ש פ״ג."],["66","66","בהר כה, כב."]]],[1300241222,"פאר זיך, ווייל אין זיין אייגענעם שדה איז אים ניט דערלויבט געווארן צו פירן זיך ווי א בעה״ב —\nאיז דעמאלט די פאסיקע צייט אז די קריאת הפרשיות פון הקהל דורכן מלך זאל האבן א פנימיות׳דיקע ווירקונג אויף די ווייטערדיקע שש שנים,\nביז אז — „ולמדו ליראה את ה״א כל הימים אשר אתם חיים על האדמה“⁶⁷.\n(משיחות ש״פ (נצבים) וילך תשי״ב ותש״כ, שמחת בית השואבה תשכ״ג)",[["67","67","פרשתנו לא, יג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191382\" data-slug=\"likkutei-sichot\" data-id=\"1300191382\">לקו״ש חי״ט ע׳ 369</a>."]]],[1300241223,"<h3>וילך ב</h3>\nא. איינע פון די מצוות וואס אידן זיינען נצטווה געווארן ביים סוף פון די ארבעים שנה, וסמוך ממש (עכ״פ ליום) פטירת משה, איז די מצוה פון כתיבת ספר תורה. ווי מען לערנט אפ פון דעם פסוק¹ „ועתה כתבו לכם את השירה הזאת“, אז „מצות עשה על כל איש ואיש מישראל לכתוב ספר תורה לעצמו“².\nוויבאלד אז דער ציווי „ועתה כתבו לכם את השירה גו׳“ איז געקומען אלס א הכנה צו דער כניסה לארץ — „כי אביאנו אל האדמה גו׳ וענתה השירה הזאת גו׳“³ — איז מובן, אז יעדער איד האט גלייך (ועתה) געדארפט מקיים זיין אט־דעם ציווי און שרייבן א ספר תורה לעצמו.\nאיז תמוה: דער ציווי „ועתה כתבו גו׳“ איז געווען און געזאגט געווארן צו אידן ביום פטירת משה (ז׳ אדר)⁴ — און מען געפינט ניט אז עס זאל דערמאנט ווערן בשום מקום, אז אין איין טאג זאלן מער ווי ששים ריבוא אידן זיך משתדל זיין צו מעבד זיין עורות וכו׳ און שרייבן (עכ״פ אנהייבן⁴*) בכתיבת מה שהוא פון א ס״ת! [וואס אזא זאך איז דאך א גרע־ סערער חידוש פון „ויחן שם ישראל — בלב אחד“⁵ — דא איז עס אן עשר׳ אחת].\nנוסף אויף דעם וואס אידן זיינען גע־ ווען פארנומען מיט אבלו של משה שלשים יום⁶; און דערנאך, בעשירי בניסן⁷, זיינען די אידן אריבער (און בהקדמת כמה הכנות לזה⁸) דעם ירדן —\nולהעיר, אז כדי צו שרייבן אזויפיל ספרי־תורה (מער ווי ששים ריבוא!) מוז מען האבן א ריבוי עצום פון יריעות של קלף (וואס מוזן זיין „מן המותר בפיך“⁹), דיו וכו׳, וואס די צוגרייטונג פון די אלע זאכן איז פארבונדן מיט גאר א סך צייט, התעסקות וכו׳. און דערצו איז אויך ניט מסתבר צו זאגן, אז יעדער איינער האט געקענט אליין שרייבן א ספר־תורה¹⁰ (ווי מיר זעען היינט במוחש, אז בלויז א מיעוט זיינען מוכשר און זיינען אומן־ סופר צו שרייבן א ס״ת). ובפרט באופן „התנאה לפניו“ — בקלף, דיו, קולמוס וכתב נאה¹¹ — איז דאך מלכתחילה ובנוגע — ריבוי אנשים — געמיינט נאר ע״י שליח¹².\nב. על דרך הנ״ל איז אויך די שאלה",[["1","1","פרשתנו לא, יט."],["2","2","ל׳ הרמב״ם הל׳ ס״ת פ״ז ה״א. ועד״ז בסהמ״צ מ״ע יח. והוא ע״פ סנה׳ כא, ב."],["3","3","לא, כ־כא. ולהעיר מאשכול ריש הל׳ ס״ת (וראה תוס׳ ור״ן נדרים לח, א. שו״ת חת״ס יו״ד סרנ״ד. ועוד) שהלימוד מפסוק דילן שמצוה לכתוב ס״ת, הוא מזה שהשירה היא „לעד“. ע״ש."],["4","4","כהתחלת הפרשה (לא, ב) ובפרש״י שם. 4*) כי אף את״ל שאין הכרח (מצד הציווי דועתה כתבו גו׳) לסיים כתיבת ס״ת קודם כניסתם לארץ (משא״כ ס״ת שכתב משה דלקמן ס״ב) — מ״מ, הרי לא מצינו מוזכר אשר ששים ריבוא אנשים התחילו בכתיבת ספרי תורה (עכ״פ בהכנות לזה —) תומ״י."],["5","5","פרש״י יתרו יט, ב (ממכילתא שם)."],["6","6","ברכה לד, ח."],["7","7","יהושע ד, יט."],["8","8","ראה יהושע א, יא. שם ג, ג ואילך."],["9","9","ראה שבת קח, א. מס׳ סופרים בתחלתה. טושו״ע יו״ד ר״ס רעא."],["10","10","להעיר מראב״ע פרשתנו כאן."],["11","11","שבת קלג, ב."],["12","12","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231017\" data-slug=\"likkutei-sichot\" data-id=\"1300231017\">לקו״ש חכ״ג ע׳ 17</a>, וש״נ."]]],[1300241224,"אין דעם וואס חז״ל¹³ זאגן, אז ביום פטירתו האט משה רבינו געשריבן „י״ג תורות, י״ב לי״ב שבטים, ואחת הניח בארון“ — דלכאורה: ווי איז עס מעג־ לעך¹⁴ צו שרייבן י״ג ספרי תורה ביום אחד?!\nזיינען מפרשים¹⁵ מסביר דעם פשט אין דעם, אז משה האט יענעם טאג נאר פארענדיקט צו שרייבן די ספרי תורה¹⁵*. ווארום בכלל איז „כל מה ששמע ביום אחד כתב וכן בכל יום ולא הי׳ חסר בכל התורה רק הסיום מפר־ שיות אחרונות“.\nבהמשך לזה קען מען מוסיף זיין אפילו בנוגע די סדרות נצבים ואילך — אז כשם ווי מען געפינט אז משה האט געשריבן „וימת משה“ (ע״ש העתיד?)¹⁶ האט ער כמו״כ געקענט שרייבן די סדרות הנ״ל (עכ״פ רובם) אין די ימים שלפני הסתלקותו [כאטש עס איז פאר־ שטאנדיק, אז מען קען ניט זאגן אז ער האט זיי געזאגט צו אידן לפני יום הסתלקותו].\nועד״ז וואלט מען לכאורה געקענט פארענטפערן אויך בנוגע אלע אידן — לויט ווי דער רמב״ם¹⁷ איז מתאר דעם סדר הלימוד פון אידן אין מדבר, אז נאך דעם ווי זיי האבן געהערט די מצוה והלכותי׳ פון משה ואהרן כו׳, האבן זיי פארשריבן „המצוה ההיא במגלות“ (פון וועלכע זיי פלעגן דערנאך לערנען):\nקומט אויס, אז במשך די מ׳ שנה במדבר זיינען (אויך) ביי אידן געווען פארשריבן רובן ככולן פון די פרשיות התורה, „ולא הי׳ חסר . . רק הסיום מפרשיות אחרונות“.\nקען מען במילא זאגן, אז נאכן ציווי „ועתה כתבו לכם גו׳“ האט יעדער איד נאר מסיים געווען די כתיבה פון זיין ספר תורה¹⁸.\nג. עס איז אבער א דוחק אזוי צו פארענטפערן, ווייל:\nא) דער תירוץ קען מען זאגן נאר לויטן מ״ד¹⁹ אז „תורה מגילה מגילה ניתנה“, אבער אפילו כמ״ד¹⁹ „תורה חתומה ניתנה“ — כפירוש התוספות²⁰, אז דאס מיינט „שעל הסדר נכתבה“\n[דאס הייסט, „על הסדר“ ווי זיי קומען אין תורה: וויבאלד אז „אין מוקדם ומאוחר בתורה“ און עס זיינען פאראן פרשיות וועלכע זיינען געזאגט געווארן „לפני אותם הכתובים לפניהם“, האט מען זיך אפגעהאלטן צו פארשרייבן אט די פרשיות ביז עס זיינען געזאגט גע־ ווארן די פרשיות וועלכע זיינען „כתובים לפניהם“, און דעמאלט האט",[["13","13","דב״ר פרשתנו פ״ט, ט. פסיקתא דר״כ פ׳ וזאת הברכה. מדרש תהלים עה״פ צ, א. ועוד. הובא בהקדמת הרמב״ם לפיה״מ (ולס׳ היד). ועוד."],["14","14","להעיר מב״ב יד, א ובפרש״י ד״ה דילמא שם."],["15","15","פי׳ מהרז״ו לדב״ר שם. — ובשו״ת חת״ס (ח״ו סכ״ט) בשם השל״ה כתב (לתרץ איך כתב משה ביום פטירתו שהי׳ בשבת), שמשה כתב הס״ת בהשבעת הקולמוס. וראה גם צרור המור ס״פ עה״פ עד תומם. וצע״ג שעפ״ז — ס״ת הכתובה בנס כשרה ולכתחילה. — ולהעיר מדברי הצ״צ בנוגע למהירות כתיבת אדמו״ר האמצעי (ס׳ השיחות תש״ג ע׳ 122. התמים ח״ב ע׳ עח־ט) ואכ״מ. 15*) אבל להעיר שבהקדמת הרמב״ם לס׳ היד מפורש: כל התורה כתבה משה רבינו קודם שימות בכתב ידו. וכן בהקדמתו לפיה״מ שם: וכשהי׳ לפני מותו החל לכתוב התורה בספרים (וראה תרגום קאפח שם)."],["16","16","ראה ב״ב טו, א. פרש״י ברכה לד, ה."],["17","17","בהקדמתו לפיה״מ בתחלתה ד״ה דע (וראה תרגום קאפח שם)."],["18","18","עד״ז תי׳ בחשק שלמה לגיטין ס, א (שו״ת בנין שלמה בהקדמתו השני׳)."],["19","19","גיטין שם."],["20","20","ד״ה תורה חתומה גיטין שם."]]],[1300241225,"מען געשריבן די אלע פרשיות פאר־ בונדן מיט דער פרשה על הסדר]\n— אבער ניט לויט רש״י²¹, וואס איז מפרש אז „חתומה ניתנה“ מיינט — „לא נכתבה עד סוף מ׳ לאחר שנאמרו כל הפרשיות כולן“.\nב) בכלל צ״ע צי דער רמב״ם מיינט צו זאגן, אז כל אחד ואחד מישראל — יעדער בר חיובא — פלעגט אליין שרייבן במגילות אלע פרשיות התורה²² במשך די ארבעים שנה (ובפרט אז א חלק גדול פון די וועלכע זיינען אריין אין א״י זיינען געבארן געווארן אין מדבר).\nג) ועיקר: בדברי חז״ל²³ געפינט מען נאר, כנ״ל, אז משה האט געשריבן י״ג ס״ת.\nאויב יעדער בר חיובא שבאותו דור האט (נאכן ציווי ועתה כתבו לכם גו׳) געשריבן א „ספר תורה לעצמו“ — וואלט עס, לכאורה, געדארפט דער־ מאנט ווערן אין דברי חז״ל, כנ״ל. פון דעם וואס חז״ל ריידן נאר וועגן די י״ג ספרי תורה איז משמע, אז עס איז ניט געווען דער חידוש הכי גדול — אז דא־ מאלס זיינען פארענדיקט געווארן מער ווי ס׳ ריבוא ס״ת (אדער אפילו — אנגעהייבן געשריבן ווערן)²⁴.\nד. וועט מען דאס פארשטיין בהקדים התמי׳ המפורסמת: וויבאלד ס׳איז א מ״ע על כל איש ואיש מישראל לכתוב ס״ת לעצמו — פארוואס זעט מען ניט אז אידן בכלל, און כו״כ פון גדולי ישראל בפרט, זאלן דאס מקיים זיין בפועל? און בסמוך צום זמן החיוב במצות אנהייבנדיג פון דער מצוה־טעם פון מצות כתבו לכם ולמדה.\nלכאורה י״ל דעם טעם דערויף: עס שטייט אין רא״ש²⁵ (און אזוי איז די הלכה²⁶) אז „האידנא שכותבין ס״ת ומניחין אותו בבתי כנסיות לקרות בו ברבים מ״ע היא על כל איש מישראל . . לכתוב חומשי תורה ומשנה וגמרא ופירושי׳ להגות בהן הוא ובניו כי מצות כתיבת התורה היא ללמוד בה . . הם הם הספרים שאדם מצוה לכותבם“ — וכפסק הש״ך²⁷, אז „האידנא“ איז די „מ״ע נאמר דוקא באלו, ולא בס״ת“.\nאון בנוגע סתם (געשריבענע אדער געדרוקטע) ספרים, איז דאך כו״כ — אפילו פון די וואס זיינען ערשט אריין אין גיל פון בר מצוה — קויפן ספרים אויף צו לערנען אין זיי, און אזוי ארום איז ער דערמיט יוצא די מצוה פון „כתבו לכם“²⁸.\nאון אע״פ אז דער רמ״א²⁹ פסק׳נט אז „לקחו כך ולא הגיהו בו דבר הוי כחוטף מצוה מן השוק ואינו יוצא בזה“ (ולכל הדיעות³⁰ איז עס ניט קיין קיום מצוה כדבעי ולכתחילה) —",[["21","21","ד״ה חתומה גיטין שם. וכ״כ ברמב״ן בהקדמתו לפירושו עה״ת, דלמ״ד זה „נכתב הכל בשנת הארבעים כשנצטווה כתבו לכם גו׳“. וראה לעיל הערה 15*."],["22","22","ובכל התנאים הדרושים שתהי׳ ס״ת כשרה."],["23","23","ראה ג״כ רש״י פרשתנו לא, ט (ובגו״א וכו׳ שם). שם לא, כב, כד־כו."],["24","24","ראה ביאור הרי״פ פערלא לסהמ״צ לרס״ג מנין הפרשיות פרשה ס (ריג, ג) — שלדעת הרס״ג משמעות הכתוב היא שלא צוה הכתוב אלא לכתוב ס״ת אחת לכל ישראל. ע״ש."],["25","25","הל׳ קטנות ריש הל׳ ס״ת."],["26","26","טושו״ע יו״ד סי׳ ער ס״ב."],["27","27","יו״ד שם סק״ה."],["28","28","ראה לקו״ש חכ״ג <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231024\" data-slug=\"likkutei-sichot\" data-id=\"1300231024\">שם (ע׳ 24־5</a>) שלדיעה זו י״ל שא״צ ספרים מכל הסוגים שמנה הרא״ש (ודי אולי בספר אחד?)."],["29","29","יו״ד שם ס״א."],["30","30","גם להדיעות שקיים המצוה — רש״י מנחות ל, א ד״ה כחוטף. נמוק״י להלכות קטנות שם. וכן"]]]]});
